inits.complications=()=>{
  const svg=$('#coSvg'),rg=$('#coT'),note=$('#coNote');
  const lg=Math.log(14);
  function heartPath(c,h){const[x,y]=c;return `M${f1(x)} ${f1(y+h*.9)}C${f1(x-h*1.3)} ${f1(y+h*.1)} ${f1(x-h*1.1)} ${f1(y-h*.9)} ${f1(x-h*.35)} ${f1(y-h*.8)}C${f1(x-h*.1)} ${f1(y-h*.78)} ${f1(x)} ${f1(y-h*.55)} ${f1(x)} ${f1(y-h*.45)}C${f1(x)} ${f1(y-h*.55)} ${f1(x+h*.1)} ${f1(y-h*.78)} ${f1(x+h*.35)} ${f1(y-h*.8)}C${f1(x+h*1.1)} ${f1(y-h*.9)} ${f1(x+h*1.3)} ${f1(y+h*.1)} ${f1(x)} ${f1(y+h*.9)}Z`}
  /* organ style: v = 0 resting, then visited (.25) and lit (1) */
  const sty=(v,base)=>v>.02?`fill:var(--risk);fill-opacity:${f1(.18+.55*v)};stroke:var(--risk);stroke-width:${f1(1+v)}`:`fill:${base||'var(--panel-2)'};fill-opacity:.85;stroke:var(--figure-line);stroke-width:1`;
  function body(X,Y,S,L,cur,u){
    const k=S/100,G=(px,py)=>[X+px*k,Y+py*k];let s=person(X,Y,S,{size:.55}).svg;
    const e=(c,rx,ry,v,rot=0)=>`<ellipse cx="${f1(c[0])}" cy="${f1(c[1])}" rx="${f1(rx*k)}" ry="${f1(ry*k)}" transform="rotate(${rot} ${f1(c[0])} ${f1(c[1])})" style="${sty(v)}"/>`;
    /* vessels */
    const vs=L.vessels||0,vp=[G(1.4,40),G(.6,52),G(.4,58)];
    s+=`<path d="${ptsD(vp)}M${f1(G(.4,58)[0])} ${f1(G(.4,58)[1])}L${f1(G(-5.4,72)[0])} ${f1(G(-5.4,72)[1])}M${f1(G(.4,58)[0])} ${f1(G(.4,58)[1])}L${f1(G(5.8,72)[0])} ${f1(G(5.8,72)[1])}M${f1(G(1.4,34)[0])} ${f1(G(1.4,34)[1])}L${f1(G(-1.6,20)[0])} ${f1(G(-1.6,20)[1])}M${f1(G(1.4,34)[0])} ${f1(G(1.4,34)[1])}L${f1(G(2.4,20)[0])} ${f1(G(2.4,20)[1])}" style="fill:none;stroke:${vs>.02?'var(--risk)':'var(--vessel)'};stroke-width:${f1(1.2+vs*1.6)};stroke-linecap:round;opacity:${f1(.35+.6*vs)}"/>`;
    /* brain */
    s+=e(G(0,7.6),5.6,4.4,L.brain||0);
    /* airway and lungs */
    const aw=L.airway||0;s+=e(G(-6.2,33),4.3,7.4,L.lungs||0,8)+e(G(6.2,33),4.3,7.4,L.lungs||0,-8);
    s+=`<path d="${ptsD([G(0,15),G(0,28)])}M${f1(G(0,28)[0])} ${f1(G(0,28)[1])}L${f1(G(-3.6,31)[0])} ${f1(G(-3.6,31)[1])}M${f1(G(0,28)[0])} ${f1(G(0,28)[1])}L${f1(G(3.6,31)[0])} ${f1(G(3.6,31)[1])}" style="fill:none;stroke:${aw>.02?'var(--risk)':'var(--figure-line)'};stroke-width:${f1(2+aw*2.2)};stroke-linecap:round"/>`;
    /* gullet */
    const gu=L.gullet||0;if(gu>.02)s+=`<path d="${ptsD([G(.3,22),G(.6,32),G(2,41)])}" style="fill:none;stroke:var(--risk);stroke-width:${f1(1.5+gu*1.6)};stroke-linecap:round;opacity:${f1(.4+.6*gu)}"/>`;
    /* heart */
    s+=`<path d="${heartPath(G(2.2,37),3.8*k)}" style="${sty(L.heart||0,'var(--panel-2)')}"/>`;
    /* liver (kit), its fat shows when the liver lights */
    const lv=L.liver||0,ls=12.5*k/140,lo=G(-11.5,39.2);
    s+=liver(lo[0],lo[1],ls,{fat:lv,seed:5}).svg;
    if(lv>.02){s+=`<path d="${smoothPath(LV_OUT.map(p=>[lo[0]+p[0]*ls,lo[1]+p[1]*ls]))}" style="fill:none;stroke:var(--risk);stroke-width:${f1(1+lv*1.4)}"/>`}
    s+=e(G(-4.6,47.8),1.1,1.3,L.gallbladder||0);
    /* pancreas and kidneys */
    s+=e(G(6.4,52),1.8,3,L.kidneys||0,-8)+e(G(-6.4,52),1.8,3,L.kidneys||0,8);
    s+=e(G(3.6,48),5,1.3,L.pancreas||0,-12);
    /* pelvis: uterus and ovaries */
    const pv=L.pelvis||0;s+=`<path d="${smoothPath([G(-2.2,55.4),G(2.2,55.4),G(1.2,59.4),G(0,60.6),G(-1.2,59.4)])}" style="${sty(pv)}"/>`+e(G(-3.4,56.6),.9,.9,pv)+e(G(3.4,56.6),.9,.9,pv);
    /* knees */
    s+=e(G(-5.6,77),2.4,2.6,L.knees||0)+e(G(5.6,77),2.4,2.6,L.knees||0);
    /* the 13 cancer sites, lit one by one in the last step */
    let ns=0;if(cur===5){ns=Math.round(13*ease(ramp(u,.05,.7)));CO_SITES.forEach((q,i)=>{if(i>=ns)return;const c=G(q[1],q[2]);
      s+=`<circle cx="${f1(c[0])}" cy="${f1(c[1])}" r="${f1(1.25*k)}" style="fill:var(--risk);stroke:var(--panel);stroke-width:1.2"/>`;
      if(i===ns-1)s+=`<circle cx="${f1(c[0])}" cy="${f1(c[1])}" r="${f1(2.6*k)}" style="fill:none;stroke:var(--risk);stroke-width:1.4;opacity:.7"/>`})}
    return {svg:s,G,ns};
  }
  function draw(t){
    const N=vb(svg,'720 380','400 650'),p=phaseOf(CO_STEPS,t),u=clamp((t-CO_STEPS[p].from)*6);
    /* lit organs: the current step glows, earlier steps keep a faint trace */
    const L={};CO_ORGANS.forEach((os,i)=>os.forEach(o=>{L[o]=i<p?.22:i===p?ease(ramp(u,0,.3)):0}));
    const X=N?92:150,Y=N?12:10,S=N?296:352,B=body(X,Y,S,L,p,u);let s=B.svg;
    /* labels for the lit organs, with leader lines */
    const right=N?178:228,left=78;
    CO_ORGANS[p].forEach((o,j)=>{if(o==='sites')return;const q=CO_LBL[o],c=B.G(q[0],q[1]),onLeft=!N&&q[0]<0,lx=onLeft?left:right,ly=c[1];
      const a=clamp(ramp(u,.05+.1*j,.3+.1*j));if(a<=0)return;
      s+=`<g style="opacity:${f1(a)}"><path d="M${f1(c[0])} ${f1(c[1])}L${f1(lx+(onLeft?4:-4))} ${f1(ly)}" style="stroke:var(--risk);stroke-width:1.1;fill:none;stroke-dasharray:3 2"/>${kitLabel(lx,ly+3.5,q[2],{a:onLeft?'e':''})}</g>`});
    if(p===5){s+=kitLabel(right,(N?96:120),`IARC sites: ${B.ns} of 13`,{});
      if(B.ns>0)s+=`<text x="${right}" y="${N?110:134}" class="t-xs">${CO_SITES[B.ns-1][0]}</text>`}
    /* the risk panel */
    const P=N?{x:20,y:356,w:360,rh:44,lw:0}:{x:322,y:42,w:378,rh:51,lw:0};
    const rows=CO_ROWS[p],X0=P.x,W=P.w-56,Xv=v=>X0+W*Math.log(v)/lg;
    s+=`<text x="${P.x}" y="${P.y-24}" class="t-big">${CO_STEPS[p].t}</text><text x="${P.x}" y="${P.y-8}" class="t-xs">relative risk vs the reference group (log scale)</text>`;
    const top=P.y+6,bot=top+rows.length*P.rh;
    [1,2,5,10].forEach(v=>{const x=Xv(v);s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${f1(top)}" y2="${f1(bot)}" class="grid"/><text x="${f1(x)}" y="${f1(bot+13)}" class="t-xs t-mid">${v===1?'1 = same':'×'+v}</text>`});
    rows.forEach((r,j)=>{const y=top+j*P.rh,g=ease(clamp(ramp(u,.12+.07*j,.42+.07*j))),x1=Xv(1+(r.v-1)*g);
      s+=`<text x="${X0}" y="${f1(y+14)}" class="t-lbl" style="font-size:12px">${r.l}</text>`;
      s+=`<rect x="${f1(X0)}" y="${f1(y+21)}" width="${f1(Math.max(1.5,x1-X0))}" height="14" rx="3" style="fill:var(--risk);opacity:${f1(.35+.5*g)}"/>`;
      if(g>.05)s+=`<text x="${f1(x1+6)}" y="${f1(y+32)}" class="t-sm" style="fill:var(--ink);font-weight:600">${r.m==='odds ×'?'×'+r.v:r.m+' '+r.v.toFixed(2).replace(/0$/,'')}</text>`});
    rows.forEach((r,j)=>{const y=top+j*P.rh;s+=`<line x1="${f1(Xv(1))}" x2="${f1(Xv(1))}" y1="${f1(y+18)}" y2="${f1(y+38)}" style="stroke:var(--ink);stroke-width:1.4"/>`});
    svg.innerHTML=s;
    note.innerHTML=noteHTML(CO_STEPS[p]);setA(p);
  }
  const stop=playWire(rg,$('#coPlay'),draw,24000,'Replay','complications');
  const setA=stepWire($('#coSteps'),CO_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- relative risk as icons ---- */
  const isvg=$('#coIcSvg'),sel=$('#coIcSel'),read=$('#coIcRead');
  sel.innerHTML=CO_RR.map((c,i)=>`<option value="${i}">${c.n}</option>`).join('');
  let ci=0,stopI=null;
  function drawI(g){
    const c=CO_RR[ci],N=vb(isvg,'720 300','400 520'),nb=c.b.length,per=N?Math.min(nb,3):nb,W=N?380:700,x0=N?10:10;
    const bw=W/per,sz=Math.min(c.abs?10:9,(bw-18)/10-2.2),gp=2.2;let s='',y0=N?30:34,maxH=0;
    c.b.forEach((b,i)=>{const col=i%per,row=Math.floor(i/per);
      const n=c.abs?100:Math.round(10*b[1]),k=c.abs?Math.round(b[1]*g):Math.round(n*g);
      const tot=c.abs?100:n,arr=iconArray(0,0,{n:tot,cols:10,size:sz,gap:gp,shape:'dot',k:0});
      const bx=x0+col*bw+(bw-arr.w)/2,by=y0+row*(N?215:0);
      const ia=iconArray(bx,by+30,{n:tot,cols:10,size:sz,gap:gp,shape:'dot',groups:[{k,col:'var(--risk)'}],base:c.abs?'var(--line)':'var(--panel-2)'});
      s+=`<text x="${f1(bx+arr.w/2)}" y="${f1(by+4)}" class="t-lbl t-mid" style="font-size:12.5px">${b[0]}</text>`;
      s+=`<text x="${f1(bx+arr.w/2)}" y="${f1(by+20)}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">${c.abs?k+' of 100':k+' cases'+(i===0?' (reference)':'')}</text>`;
      s+=ia.svg;maxH=Math.max(maxH,by+30+ia.h)});
    isvg.setAttribute('viewBox',`0 0 ${N?400:720} ${Math.ceil(Math.max(150,maxH+12))}`);
    isvg.innerHTML=s;
    const big=c.b[c.b.length-1];
    read.innerHTML=c.abs?`<b>${c.n}.</b> In a meta-analysis of 151 studies, NAFLD (now MASLD) was found in 69.99% of people with overweight and 75.27% of people with obesity, shown here as people out of 100. ${c.src} This counts how common the disease is, not how many people will develop it.`
      :`<b>${c.n}.</b> Each block shows how many cases occur in a group for every 10 cases in an equal-sized group with ${c.ref}. With ${c.m} ${big[1]}, the ${big[0].toLowerCase()} group has about ${Math.round(10*big[1])}. ${c.src} A relative risk says nothing on its own about how common a disease is: if it is rare, even a large ratio means few extra cases.`;
  }
  function runI(){stopI&&stopI();drawI(0);stopI=animate(1100,p=>drawI(ease(p)),()=>{stopI=null})}
  sel.addEventListener('change',()=>{ci=+sel.value;runI()});
  drawI(1);

  /* ---- what modest loss improves ---- */
  const lsvg=$('#coLaSvg'),lb=$('#coLaBtns'),lread=$('#coLaRead');let lv=0,stopL=null;
  function drawL(g){
    const N=vb(lsvg,'720 312','400 440');let s='';
    if(lv===0){const x0=N?20:250,w=N?300:380,y0=N?30:34,rh=N?78:48,X=v=>x0+w*v/4;
      [0,1,2,3,4].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${y0}" y2="${y0+rh*5}" class="grid"/><text x="${f1(X(v))}" y="${y0+rh*5+14}" class="t-xs t-mid">${v}</text>`});
      s+=`<text x="${f1(X(4))}" y="${y0+rh*5+28}" class="t-xs t-end">odds ratio vs stable weight</text>`;
      CO_LA.forEach((r,j)=>{const y=y0+j*rh,ly=N?y+14:y+22,by=N?y+24:y+10,e=ease(clamp(g*1.4-j*.1));
        s+=`<text x="${N?x0:x0-12}" y="${ly}" class="t-lbl${N?'':' t-end'}" style="font-size:12.5px">${r.l}</text>`;
        if(r.none)s+=`<text x="${f1(X(1)+8)}" y="${by+16}" class="t-sm" style="fill:var(--ink)">no association (P = 0.79)</text><circle cx="${f1(X(1))}" cy="${by+11}" r="5" style="fill:none;stroke:var(--muted);stroke-width:2"/>`;
        else{const x1=X(r.v*e);s+=`<rect x="${f1(x0)}" y="${by}" width="${f1(Math.max(1,x1-x0))}" height="22" rx="4" style="fill:var(--good);opacity:.8"/>`;if(e>.1)s+=`<text x="${f1(x1+6)}" y="${by+16}" class="t-sm" style="fill:var(--ink);font-weight:700">OR ${r.v.toFixed(2)}</text>`}});
      CO_LA.forEach((r,j)=>{const by=(N?y0+j*rh+24:y0+j*rh+10);s+=`<line x1="${f1(X(1))}" x2="${f1(X(1))}" y1="${by-4}" y2="${by+26}" style="stroke:var(--ink);stroke-width:1.5"/>`});s+=`<text x="${f1(X(1)+4)}" y="${y0-8}" class="t-xs">1 = no better than stable weight</text>`;
      lread.innerHTML='Look AHEAD, 5145 adults with type 2 diabetes: compared with people whose weight stayed stable, those who lost 5 to under 10% at 1 year had higher odds of each improvement shown. The odds were even greater with 10 to 15% loss. LDL cholesterol did not track weight loss. <sup class="c" data-ref="Wing2011DiabetesCare" title="Source 606"><a href="/obesity/sources/#src-Wing2011DiabetesCare">606</a></sup> Odds ratios from an observational analysis within the trial: they describe groups, not what one person will see.'}
    else{const x0=N?20:300,w=N?320:360,y0=N?30:30,rh=N?76:50,X=v=>x0+w*v/100;
      [0,25,50,75,100].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${y0}" y2="${y0+rh*5}" class="grid"/><text x="${f1(X(v))}" y="${y0+rh*5+14}" class="t-xs t-mid">${v}%</text>`});
      CO_ORGW.forEach((r,j)=>{const y=y0+j*rh,ly=N?y+14:y+22,by=N?y+24:y+10,e=ease(clamp(g*1.4-j*.1)),x1=X(r.v*e);
        s+=`<text x="${N?x0:x0-12}" y="${ly}" class="t-lbl${N?'':' t-end'}" style="font-size:12.5px">${r.l}</text>`;
        s+=`<rect x="${f1(x0)}" y="${by}" width="${f1(Math.max(1,x1-x0))}" height="${r.c?13:22}" rx="4" style="fill:var(--good);opacity:.8"/>`;
        if(r.c){const xc=X(r.c*e);s+=`<rect x="${f1(x0)}" y="${by+15}" width="${f1(Math.max(1,xc-x0))}" height="9" rx="3" style="fill:var(--muted);opacity:.6"/>`;if(e>.1)s+=`<text x="${f1(xc+6)}" y="${by+24}" class="t-xs">control ${r.c}%</text>`}
        if(e>.1)s+=`<text x="${f1(x1+6)}" y="${by+(r.c?11:16)}" class="t-sm" style="fill:var(--ink);font-weight:700">${r.v}%</text>`});
      lread.innerHTML='Liver: in 293 people with biopsy-proven NASH, 90% of those who lost ≥10% had NASH resolution and 45% fibrosis regression; 58% resolved with ≥5%. <sup class="c" data-ref="VilarGomez2015" title="Source 565"><a href="/obesity/sources/#src-VilarGomez2015">565</a></sup> Bladder: in PRIDE, an 8% loss cut weekly incontinence episodes by 47% versus 28% in controls. <sup class="c" data-ref="Subak2009PRIDE" title="Source 529"><a href="/obesity/sources/#src-Subak2009PRIDE">529</a></sup> Sleep: a 10% loss predicted a 26% fall in AHI. <sup class="c" data-ref="Peppard2000" title="Source 421"><a href="/obesity/sources/#src-Peppard2000">421</a></sup> Different trials and measures, shown side by side only to compare direction; population averages.'}
    lsvg.innerHTML=s;
  }
  function runL(){stopL&&stopL();stopL=animate(1200,p=>drawL(p),()=>{stopL=null})}
  lb.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(!b)return;lv=+b.dataset.v;$$('[data-v]',lb).forEach(x=>x.setAttribute('aria-pressed',x===b));runL()});
  drawL(1);
  const prevR=redraws.complications;redraws.complications=()=>{prevR&&prevR();drawI(1);drawL(1)};
  const prevH=onHide.complications;onHide.complications=()=>{prevH&&prevH();stopI&&stopI();stopL&&stopL();stopI=stopL=null};
};
/* =============== 2.2 Obesity & type 2 diabetes =============== */
/* The main scene: fat stores fill, fat spills into the liver and pancreas, insulin works less well and the beta cells
   strain; then weight loss empties the liver and pancreas again (the Newcastle "twin cycle" model, labelled as a
   hypothesis), and the DiRECT trial's remission results build up. Organ fat, insulin and glucose in steps 1-3 are
   schematic levels; the only numbers drawn are published ones (Lim 2011, DiRECT). */
const DB_STEPS=[
 {from:0,at:.07,k:'Step 1',t:'Fat stores fill',
  txt:'In obesity, fat tissue releases more non-esterified fatty acids, glycerol, hormones and pro-inflammatory cytokines, and these drive insulin resistance. <sup class="c" data-ref="Kahn2006" title="Source 270"><a href="/obesity/sources/#src-Kahn2006">270</a></sup> Where fat is stored matters: in 3001 Framingham participants, visceral fat was more strongly linked to metabolic risk than fat under the skin (OR for metabolic syndrome per SD 4.7 vs 3.0 in women). <sup class="c" data-ref="Fox2007Framingham" title="Source 166"><a href="/obesity/sources/#src-Fox2007Framingham">166</a></sup>',
  pt:'When fat tissue under the skin is full, more fat circulates in the blood as fatty acids, and some of it ends up in places it should not be.',
  hook:'Visceral fat beat subcutaneous fat as a marker of metabolic risk, even after adjusting for BMI and waist. <sup class="c" data-ref="Fox2007Framingham" title="Source 166"><a href="/obesity/sources/#src-Fox2007Framingham">166</a></sup>'},
 {from:.17,at:.25,k:'Step 2',t:'Fat spills into the liver',
  txt:'Fat stored in the wrong places, such as the liver, goes with high triglycerides, more free fatty acids and insulin resistance in the liver. <sup class="c" data-ref="Tchernof2013" title="Source 544"><a href="/obesity/sources/#src-Tchernof2013">544</a></sup> Ectopic fat in the liver may add to cardiometabolic risk. <sup class="c" data-ref="Neeland2019" title="Source 396"><a href="/obesity/sources/#src-Neeland2019">396</a></sup> The insulin-resistant liver keeps making glucose, so blood glucose drifts up.',
  pt:'A liver full of fat stops listening to insulin. It keeps releasing sugar into the blood even when it should stop.',
  hook:'Insulin resistance alone is not diabetes: type 2 diabetes develops when beta-cell dysfunction is added on top. <sup class="c" data-ref="Kahn2006" title="Source 270"><a href="/obesity/sources/#src-Kahn2006">270</a></sup>'},
 {from:.33,at:.42,k:'Step 3',t:'Beta cells strain',
  txt:'Type 2 diabetes appears when the pancreas can no longer make enough insulin to overcome the resistance. <sup class="c" data-ref="Kahn2006" title="Source 270"><a href="/obesity/sources/#src-Kahn2006">270</a></sup> The Newcastle group\'s model links the two organs: fat in the liver and fat in the pancreas, which blunts the first burst of insulin after a meal (a "twin cycle"). <span class="ev hyp">Hypothesis</span> It was tested in the studies in the next step. <sup class="c" data-ref="Lim2011,Taylor2018CellMetab" title="Source 325,542"><a href="/obesity/sources/#src-Lim2011">325,542</a></sup> Each person may have a personal fat threshold, independent of BMI: in the UKPDS, one in three people had a BMI under 25 at diagnosis. <span class="ev hyp">Hypothesis</span> <sup class="c" data-ref="Taylor2015PFT" title="Source 541"><a href="/obesity/sources/#src-Taylor2015PFT">541</a></sup>',
  pt:'The insulin-making cells in the pancreas work harder and harder, then start to fall behind. That is when blood sugar reaches the diabetes range.',
  hook:'Type 2 diabetes = insulin resistance + beta-cell dysfunction. <sup class="c" data-ref="Kahn2006" title="Source 270"><a href="/obesity/sources/#src-Kahn2006">270</a></sup>'},
 {from:.5,at:.6,k:'Step 4',t:'Weight loss empties the organs',
  txt:'In 11 people with type 2 diabetes on a 600 kcal/day research diet, fasting glucose normalised within 1 week (9.2 to 5.9 mmol/L); by week 8 liver fat had fallen from 12.8% to 2.9% and pancreatic fat from 8.0% to 6.2%, and first-phase insulin secretion recovered toward normal. <sup class="c" data-ref="Lim2011" title="Source 325"><a href="/obesity/sources/#src-Lim2011">325</a></sup> In a DiRECT subgroup, liver fat fell from 16.0% to 3.1%. Return of first-phase insulin separated responders from non-responders, and responders had a shorter diabetes duration (2.7 vs 3.8 years). <sup class="c" data-ref="Taylor2018CellMetab" title="Source 542"><a href="/obesity/sources/#src-Taylor2018CellMetab">542</a></sup> These were research diets under medical supervision, not instructions.',
  pt:'When weight comes down, the liver empties of fat first, and in many people the pancreas starts making insulin properly again. This works best early in the illness.',
  hook:'Lim 2011: liver fat 12.8% to 2.9% in 8 weeks; fasting glucose normal within 1 week. <sup class="c" data-ref="Lim2011" title="Source 325"><a href="/obesity/sources/#src-Lim2011">325</a></sup>'},
 {from:.67,at:.76,k:'DiRECT',t:'Remission in DiRECT',
  txt:'DiRECT enrolled 306 people with type 2 diabetes for under 6 years and BMI 27–45, not on insulin. Diabetes and blood-pressure drugs were withdrawn, followed by 3–5 months of formula total diet replacement (825–853 kcal/day), stepped food reintroduction and maintenance support (published methods, not instructions). Remission (HbA1c under 6.5% after at least 2 months off all glucose-lowering drugs) was 46% versus 4% at 12 months <sup class="c" data-ref="Lean2018DiRECT" title="Source 313"><a href="/obesity/sources/#src-Lean2018DiRECT">313</a></sup> and 36% versus 3% at 24 months. <sup class="c" data-ref="Lean2019DiRECT" title="Source 314"><a href="/obesity/sources/#src-Lean2019DiRECT">314</a></sup> At 5 years, 13% of the extension group were in remission. <sup class="c" data-ref="Lean2024DiRECT" title="Source 315"><a href="/obesity/sources/#src-Lean2024DiRECT">315</a></sup>',
  pt:'For some people who have had type 2 diabetes for only a few years, a supported weight programme put diabetes into remission. Remission can wear off as weight returns, which is biology, so check-ups still matter.',
  hook:'DiRECT remission: 46% vs 4% at 12 months; 36% vs 3% at 24 months. <sup class="c" data-ref="Lean2018DiRECT,Lean2019DiRECT" title="Source 313,314"><a href="/obesity/sources/#src-Lean2018DiRECT">313,314</a></sup>'},
 {from:.83,at:.95,k:'DiRECT',t:'Remission by kilograms lost',
  txt:'Across the whole DiRECT study, remission at 12 months climbed with weight lost: 0% of 76 people who gained weight, 7% with 0–5 kg lost, 34% with 5–10 kg, 57% with 10–15 kg and 86% (31 of 36) with 15 kg or more. <sup class="c" data-ref="Lean2018DiRECT" title="Source 313"><a href="/obesity/sources/#src-Lean2018DiRECT">313</a></sup> Of those in remission at year 2, 26% were still in remission at 5 years, consistent with obesity and type 2 diabetes being chronic, relapsing conditions. <sup class="c" data-ref="Lean2024DiRECT" title="Source 315"><a href="/obesity/sources/#src-Lean2024DiRECT">315</a></sup>',
  pt:'The more weight people lost, the more often their diabetes went into remission. These are averages for groups; nobody can be promised a result.',
  hook:'DiRECT: 86% remission with 15 kg or more lost. <sup class="c" data-ref="Lean2018DiRECT" title="Source 313"><a href="/obesity/sources/#src-Lean2018DiRECT">313</a></sup>'}
];
const DB_DR=[{l:'12 months',a:46,c:4},{l:'24 months',a:36,c:3},{l:'5 years',a:13,c:5}];
const DB_KG=[{l:'gained',v:0},{l:'0–5 kg',v:7},{l:'5–10 kg',v:34},{l:'10–15 kg',v:57},{l:'≥15 kg',v:86}];
/* DPP: published incidence rates (per 100 person-years) over a mean 2.8 years, and 15-year cumulative incidence */
const DB_ARMS=[{id:'pl',n:'Placebo',r:11.0,c15:62,col:'var(--muted)',dash:''},{id:'mf',n:'Metformin',r:7.8,c15:56,col:'var(--tx)',dash:'8 4'},{id:'ls',n:'Lifestyle',r:4.8,c15:55,col:'var(--hl)',dash:''}];

inits.diabetes=()=>{
  const svg=$('#dbSvg'),rg=$('#dbT'),note=$('#dbNote');
  function pancreas(x,y,s,fat,ins){/* a pancreas lying across, head on the viewer's left, with islets of beta cells */
    const T=p=>[x+p[0]*s,y+p[1]*s],P=[[0,22],[10,8],[34,6],[62,12],[96,10],[128,4],[142,10],[136,22],[104,28],[70,30],[40,34],[14,38]];
    let g=`<path d="${smoothPath(P.map(T))}" style="fill:var(--cyto);stroke:var(--gut-line);stroke-width:1.4"/>`;const rr=rng(3);
    for(let i=0;i<Math.round(fat*16);i++){const q=T([18+rr()*110,12+rr()*16]);g+=`<circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="${f1((1.6+rr()*1.8)*s)}" style="fill:var(--fat);stroke:var(--fat-line);stroke-width:.6"/>`}
    [[34,20],[72,19],[110,15]].forEach(c=>{const q=T(c);g+=`<circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="${f1(7*s)}" style="fill:var(--insulin);fill-opacity:${f1(.12+.4*ins)};stroke:var(--insulin);stroke-width:1.2"/>`;
      for(let k=0;k<4;k++){const a=k*1.57+.6;g+=`<circle cx="${f1(q[0]+Math.cos(a)*3.4*s)}" cy="${f1(q[1]+Math.sin(a)*3.4*s)}" r="${f1(1.4*s)}" style="fill:var(--nucleus)"/>`}});
    return {svg:g,at:{c:T([70,20]),out:T([70,34])}}}
  const flow=(a,b,bend,n,ph,kind)=>{let s='';const c=[(a[0]+b[0])/2+bend[0],(a[1]+b[1])/2+bend[1]];
    s+=`<path d="M${f1(a[0])} ${f1(a[1])}Q${f1(c[0])} ${f1(c[1])} ${f1(b[0])} ${f1(b[1])}" style="fill:none;stroke:var(--line);stroke-width:1.2;stroke-dasharray:3 4"/>`;
    for(let i=0;i<n;i++){const u=((i/n)+ph)%1,q=1-u,x=q*q*a[0]+2*q*u*c[0]+u*u*b[0],y=q*q*a[1]+2*q*u*c[1]+u*u*b[1];
      s+=kind==='ffa'?`<circle cx="${f1(x)}" cy="${f1(y)}" r="3.4" style="fill:var(--fat);stroke:var(--fat-line);stroke-width:1"/>`:hormoneDot(x,y,'insulin',{r:4})}
    return s};
  function bars(x,y,w,h,data,g,N,kg){/* grouped or single bars, growing with g */
    let s=`<line x1="${x}" x2="${x+w}" y1="${y+h}" y2="${y+h}" class="axis"/>`;[0,25,50,75,100].forEach(v=>{const yy=y+h-h*v/100;s+=`<line x1="${x}" x2="${x+w}" y1="${f1(yy)}" y2="${f1(yy)}" class="grid"/><text x="${x-5}" y="${f1(yy+3)}" class="t-xs t-end">${v}%</text>`});
    const n=data.length,bw=w/n;
    data.forEach((d,i)=>{const cx=x+bw*i+bw/2,e=ease(clamp(g*n-i));
      if(kg){const hh=h*d.v/100*e,bx=cx-bw*.32;s+=`<rect x="${f1(bx)}" y="${f1(y+h-hh)}" width="${f1(bw*.64)}" height="${f1(Math.max(hh,1))}" rx="3" style="fill:var(--good);opacity:${f1(.4+.5*e)}"/>`;
        if(e>.05)s+=`<text x="${f1(cx)}" y="${f1(y+h-hh-5)}" class="t-sm t-mid" style="fill:var(--ink);font-weight:700">${Math.round(d.v*e)}%</text>`}
      else{const ha=h*d.a/100*e,hc=h*d.c/100*e,b=bw*.3;s+=`<rect x="${f1(cx-b-2)}" y="${f1(y+h-ha)}" width="${f1(b)}" height="${f1(Math.max(ha,1))}" rx="3" style="fill:var(--hl)"/><rect x="${f1(cx+2)}" y="${f1(y+h-hc)}" width="${f1(b)}" height="${f1(Math.max(hc,1))}" rx="3" style="fill:var(--muted);opacity:.7"/>`;
        if(e>.05)s+=`<text x="${f1(cx-b/2-2)}" y="${f1(y+h-ha-5)}" class="t-sm t-mid" style="fill:var(--ink);font-weight:700">${Math.round(d.a*e)}%</text><text x="${f1(cx+b/2+2)}" y="${f1(y+h-hc-5)}" class="t-xs t-mid">${Math.round(d.c*e)}%</text>`}
      s+=`<text x="${f1(cx)}" y="${y+h+15}" class="t-xs t-mid" style="fill:var(--ink)">${d.l}</text>`});
    return s}
  function draw(t){
    const N=vb(svg,'720 380','400 600'),p=phaseOf(DB_STEPS,t);let s='';
    const sz=lerp(.25,1,ramp(t,0,.15))*(1-.45*ramp(t,.52,.62)),lf=ramp(t,.12,.3)*(1-.85*ramp(t,.52,.62)),pf=ramp(t,.3,.42)*(1-.6*ramp(t,.54,.64)),
      ins=clamp(1-.7*ramp(t,.34,.46)+.6*ramp(t,.56,.66)),glu=clamp(.18+.32*ramp(t,.18,.32)+.42*ramp(t,.34,.46)-.68*ramp(t,.5,.56)),
      ffa=Math.round(2+8*ramp(t,.04,.2)-7*ramp(t,.5,.58)),o1=1-ramp(t,.64,.69),ph=t*9;
    if(o1>0){
      const A=N?{x:16,y:62,w:150,h:104}:{x:24,y:72,w:170,h:120},L=N?[192,68,1.2]:[290,68,1.25],Pn=N?[30,262,1.5]:[478,108,1.12],V=N?{x:16,y:478,w:300}:{x:24,y:286,w:560},Gg=N?{x:356,y:250,h:220}:{x:672,y:60,h:250};
      s+=`<g style="opacity:${f1(o1)}">`;
      s+=`<text x="${A.x}" y="${A.y-12}" class="t-lbl">fat under the skin</text>`+adiposeTissue(A.x,A.y,A.w,A.h,{size:sz,inflamed:ramp(t,.1,.3)*.5*(1-ramp(t,.52,.62)),seed:4,frame:true}).svg;
      const lv=liver(L[0],L[1],L[2],{fat:lf,seed:8});s+=`<text x="${L[0]}" y="${L[1]-12}" class="t-lbl">liver</text>`+lv.svg;
      const pn=pancreas(Pn[0],Pn[1],Pn[2],pf,ins);s+=`<text x="${Pn[0]}" y="${Pn[1]-14}" class="t-lbl">pancreas: islets make insulin</text>`+pn.svg;
      /* fatty acids leave the full fat store for the liver and the pancreas */
      const src=[A.x+A.w,A.y+A.h*.4];
      if(ffa>0){s+=flow(src,lv.at.c,[0,-30],ffa,ph%1,'ffa');if(t>.28)s+=flow([A.x+A.w*.7,A.y+A.h],pn.at.c,N?[-20,10]:[0,50],Math.max(1,Math.round(ffa*.6)),(ph*1.1)%1,'ffa')}
      /* insulin from the islets into the blood */
      const ni=Math.round(1+5*ins);s+=flow(pn.at.out,[N?V.x+V.w*.62:V.x+V.w*.78,V.y],[N?20:30,10],ni,(ph*.8)%1,'ins');
      /* blood vessel with glucose */
      s+=`<rect x="${V.x}" y="${V.y}" width="${V.w}" height="34" rx="17" style="fill:var(--vessel);fill-opacity:.12;stroke:var(--vessel);stroke-width:1.4"/><text x="${V.x}" y="${V.y+50}" class="t-xs">blood: glucose (squares hollow), insulin (filled)</text>`;
      const ng=Math.round(4+22*glu),rr=rng(9);for(let i=0;i<ng;i++){const u=(rr()+ph*.25)%1,yy=V.y+8+rr()*18;s+=`<rect x="${f1(V.x+10+u*(V.w-20))}" y="${f1(yy-3)}" width="6" height="6" rx="1" style="fill:none;stroke:var(--gold);stroke-width:1.6"/>`}
      /* glucose gauge, schematic */
      const gy=Gg.y+Gg.h-Gg.h*glu,th=Gg.y+Gg.h*.42;
      s+=`<text x="${Gg.x+12}" y="${Gg.y-12}" class="t-xs t-mid">glucose</text><rect x="${Gg.x}" y="${Gg.y}" width="24" height="${Gg.h}" rx="12" style="fill:var(--field);stroke:var(--line)"/><rect x="${Gg.x+4}" y="${f1(gy)}" width="16" height="${f1(Gg.y+Gg.h-gy-4)}" rx="8" style="fill:${glu>.58?'var(--risk)':'var(--gold)'};opacity:.85"/>`;
      s+=`<line x1="${Gg.x-6}" x2="${Gg.x+30}" y1="${f1(th)}" y2="${f1(th)}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/><text x="${Gg.x-8}" y="${f1(th-4)}" class="t-xs t-end">diabetes</text><text x="${Gg.x-8}" y="${f1(th+9)}" class="t-xs t-end">range</text>`;
      /* labels and published numbers by step */
      const lab=(x,y,txt,a)=>kitLabel(x,y,txt,{a});
      if(p===0)s+=lab(A.x+A.w/2,A.y+A.h+18,'cells enlarge as stores fill','m');
      if(p>=1&&p<=2)s+=lab(L[0]+80*L[2],L[1]+108*L[2],'fat in the liver: insulin resistance','m');
      if(p===2){s+=lab(Pn[0]+70*Pn[2],Pn[1]+56*Pn[2],'fat in the pancreas: less insulin','m');s+=`<text x="${N?200:380}" y="${N?20:28}" class="t-big t-mid" style="fill:var(--risk)">type 2 diabetes</text><text x="${N?200:380}" y="${N?34:42}" class="t-xs t-mid">liver + pancreas: the "twin cycle" (hypothesis)</text>`}
      if(p===3){const w=ramp(t,.52,.62),wg=ramp(t,.5,.54);
        s+=lab(L[0]+80*L[2],L[1]+108*L[2],`liver fat ${f1(lerp(12.8,2.9,w))}%`,'m')+lab(Pn[0]+70*Pn[2],Pn[1]+56*Pn[2],`pancreatic fat ${f1(lerp(8.0,6.2,ramp(t,.54,.64)))}%`,'m');
        s+=`<text x="${Gg.x+12}" y="${Gg.y+Gg.h+16}" class="t-sm t-mid" style="fill:var(--ink);font-weight:700">${f1(lerp(9.2,5.9,wg))}</text><text x="${Gg.x+12}" y="${Gg.y+Gg.h+28}" class="t-xs t-mid">mmol/L</text>`;
        s+=`<text x="${N?200:380}" y="${N?20:28}" class="t-big t-mid" style="fill:var(--good)">${N?'weight loss (Lim 2011, n = 11)':'weight loss: 11 people, 8 weeks (Lim 2011)'}</text>`}
      s+='</g>'}
    const o2=ramp(t,.66,.71);
    if(o2>0){s+=`<g style="opacity:${f1(o2)}">`;
      const C1=N?{x:50,y:60,w:330,h:200}:{x:60,y:70,w:270,h:240},C2=N?{x:50,y:360,w:330,h:190}:{x:420,y:70,w:270,h:240};
      s+=`<text x="${C1.x-40}" y="${C1.y-34}" class="t-big">DiRECT: in remission</text><text x="${C1.x-40}" y="${C1.y-18}" class="t-xs">pink: intervention · grey: control</text>`;
      s+=bars(C1.x,C1.y,C1.w,C1.h,DB_DR,ramp(t,.68,.8),N,false);
      const g2=ramp(t,.84,.93);
      s+=`<g style="opacity:${f1(.25+.75*ramp(t,.82,.86))}"><text x="${C2.x-40}" y="${C2.y-34}" class="t-big">Remission at 12 months by weight lost</text><text x="${C2.x-40}" y="${C2.y-18}" class="t-xs">whole DiRECT study; 31 of 36 with ≥15 kg</text>`;
      s+=bars(C2.x,C2.y,C2.w,C2.h,DB_KG,g2,N,true)+`</g>`;
      s+='</g>'}
    svg.innerHTML=s;note.innerHTML=noteHTML(DB_STEPS[p]);setA(p);
  }
  const stop=playWire(rg,$('#dbPlay'),draw,26000,'Replay','diabetes');
  const setA=stepWire($('#dbSteps'),DB_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- DPP curves ---- */
  const dsvg=$('#dpSvg'),dr=$('#dpT'),db=$('#dpBtns'),dread=$('#dpRead');const on={pl:true,mf:true,ls:true};
  const cum=(a,y)=>{const c28=100*(1-Math.exp(-a.r/100*2.8));if(y<=2.8)return 100*(1-Math.exp(-a.r/100*y));return lerp(c28,a.c15,ease(clamp((y-2.8)/12.2)))};
  function drawD(){
    const y=+dr.value,N=vb(dsvg,'720 320','400 420'),ax=N?curveAxes(46,30,330,300,{x0:0,x1:15,y0:0,y1:70,xt:[0,3,6,9,12,15],yt:[0,20,40,60],yfmt:v=>v+'%',xlabel:'years since randomisation',ylabel:'developed diabetes (cumulative)'})
      :curveAxes(60,30,600,240,{x0:0,x1:15,y0:0,y1:70,xt:[0,2.8,5,10,15],xfmt:v=>v===2.8?'2.8':v,yt:[0,20,40,60],yfmt:v=>v+'%',xlabel:'years since randomisation',ylabel:'developed diabetes (cumulative)'});
    let s=ax.svg;
    s+=`<rect x="${f1(ax.X(0))}" y="30" width="${f1(ax.X(2.8)-ax.X(0))}" height="${N?300:240}" style="fill:var(--hl-soft);opacity:.5"/><text x="${f1(ax.X(1.4))}" y="44" class="t-xs t-mid" style="fill:var(--ink)">trial phase</text>`;
    let txt=[],labs=[];
    DB_ARMS.forEach(a=>{if(!on[a.id])return;const P1=[],P2=[];for(let i=0;i<=28;i++){const v=i/10;P1.push([v,cum(a,v)])}for(let i=0;i<=40;i++){const v=2.8+12.2*i/40;P2.push([v,cum(a,v)])}
      s+=plotLine(P1,ax.X,ax.Y,{col:a.col,upto:y,dash:a.dash}).svg+plotLine(P2,ax.X,ax.Y,{col:a.col,upto:y,lw:1.6,dash:'2 4'}).svg;
      if(y>=15)s+=`<circle cx="${f1(ax.X(15))}" cy="${f1(ax.Y(a.c15))}" r="5" style="fill:${a.col};stroke:var(--panel);stroke-width:2"/>`;
      const v=cum(a,Math.min(y,15)),py=ax.Y(v);s+=`<circle cx="${f1(ax.X(Math.min(y,15)))}" cy="${f1(py)}" r="4" style="fill:${a.col}"/>`;labs.push({y:py,t:`${a.n} ${Math.round(v)}%`,col:a.col});
      txt.push(`${a.n} ${Math.round(v)}%`)});
    labs.sort((p,q)=>p.y-q.y);for(let i=1;i<labs.length;i++)labs[i].y=Math.max(labs[i].y,labs[i-1].y+15);
    const lx=Math.min(ax.X(Math.min(y,15))+10,N?300:600);labs.forEach(l=>{s+=`<text x="${f1(lx)}" y="${f1(l.y+4)}" class="t-sm" style="fill:var(--ink);font-weight:700">${l.t}</text>`});
    dsvg.innerHTML=s;
    const ph=y<=2.8?`Trial phase, year ${f1(y)}: ${txt.join(', ')||'no arm selected'} (computed from the published incidence rates of 11.0, 7.8 and 4.8 cases per 100 person-years, assuming a constant rate). Lifestyle cut incidence by 58% and metformin by 31%; 6.9 people would need the lifestyle programme and 13.9 metformin to prevent one case over three years. <sup class="c" data-ref="Knowler2002DPP" title="Source 293"><a href="/obesity/sources/#src-Knowler2002DPP">293</a></sup>`
      :y<15?`After the trial, year ${f1(y)}: dashed lines are schematic joins to the 15-year values. All groups were then offered group lifestyle sessions, and yearly rates converged (5.9, 4.9 and 5.6 per 100 person-years); at 10 years incidence was still 34% lower with lifestyle and 18% with metformin. <sup class="c" data-ref="DPPRG2009" title="Source 127"><a href="/obesity/sources/#src-DPPRG2009">127</a></sup>`
      :`At 15 years cumulative incidence was 55% (lifestyle), 56% (metformin) and 62% (placebo), a 27% reduction with lifestyle (HR 0.73). <sup class="c" data-ref="DPPRG2015" title="Source 128"><a href="/obesity/sources/#src-DPPRG2015">128</a></sup> Over about 21 years the benefit persisted (HR 0.76 lifestyle, 0.83 metformin). <sup class="c" data-ref="Knowler2025DPPOS" title="Source 294"><a href="/obesity/sources/#src-Knowler2025DPPOS">294</a></sup>`;
    dread.innerHTML=ph+' Population averages from one trial.';
  }
  dr.addEventListener('input',drawD);
  db.addEventListener('click',e=>{const b=e.target.closest('[data-arm]');if(!b)return;on[b.dataset.arm]=!on[b.dataset.arm];b.setAttribute('aria-pressed',on[b.dataset.arm]);drawD()});
  drawD();
  /* ---- 16% per kilogram ---- */
  const kr=$('#dbKg'),ko=$('#dbKgOut');
  function drawK(){const kg=+kr.value,hr=Math.pow(.84,kg);ko.innerHTML=`<span class="big-num">${kg===0?'1.00':hr.toFixed(2)}</span> <span>relative hazard after ${kg} kg lost${kg===5?' (published: HR 0.42 per 5 kg)':''}, about ${Math.round((1-hr)*100)}% lower than with no weight lost. Each kilogram meant 16% lower risk in the DPP lifestyle arm, after adjusting for diet and activity. <sup class="c" data-ref="Hamman2006" title="Source 214"><a href="/obesity/sources/#src-Hamman2006">214</a></sup></span>`}
  kr.addEventListener('input',drawK);drawK();
  const prevR=redraws.diabetes;redraws.diabetes=()=>{prevR&&prevR();drawD()};
};
/* =============== 2.3 Assessment & staging =============== */
/* A clinical encounter drawn as six stations on a path: ask permission, history, measure, tests, stage, shared plan.
   Each station has its own small scene. The weight-history curve is schematic; cuff sizes, test lists and EOSS
   hazard ratios are as published. Everything here is a teaching tool, never a diagnosis. */
const AS_STEPS=[
 {from:0,at:.07,k:'5As · Ask',t:'Ask permission',
  txt:'The modified 5As for obesity counselling are Ask, Assess, Advise, Agree and Assist. Ask means asking permission to discuss weight, without judgement, and exploring whether the person is ready. <sup class="c" data-ref="Vallis2013" title="Source 561"><a href="/obesity/sources/#src-Vallis2013">561</a></sup> Weight stigma causes physical and psychological harm and leads to poorer care. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> <a href="#" data-go="stigma">Module 2.4</a> covers language that helps.',
  pt:'A good check-up asks your permission before talking about weight. You can say "not today", and the rest of your care should not change.',
  hook:'The 5As: Ask (permission), Assess, Advise, Agree, Assist. <sup class="c" data-ref="Vallis2013" title="Source 561"><a href="/obesity/sources/#src-Vallis2013">561</a></sup>'},
 {from:1/6,at:1/6+.08,k:'5As · Assess',t:'History: the whole story',
  txt:'Assess covers the drivers and complications of excess weight. <sup class="c" data-ref="Vallis2013" title="Source 561"><a href="/obesity/sources/#src-Vallis2013">561</a></sup> A medicine review matters: in 257 RCTs, olanzapine (2.4 kg), gabapentin (2.2 kg), pioglitazone (2.6 kg), glyburide (2.6 kg), amitriptyline (1.8 kg) and mirtazapine (1.5 kg) were linked to weight gain versus placebo. <sup class="c" data-ref="Domecq2015" title="Source 123"><a href="/obesity/sources/#src-Domecq2015">123</a></sup> Secondary causes include Cushing\'s syndrome, hypothyroidism and medicines such as steroids, antidepressants and antipsychotics. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup> Ask about sleep and mood, and about eating problems: binge eating disorder and night eating syndrome are common in people living with obesity. <sup class="c" data-ref="Rubino2025Commission,Kessler2013BED" title="Source 279,480"><a href="/obesity/sources/#src-Rubino2025Commission">279,480</a></sup>',
  pt:'The clinician asks how your weight has changed over your life, which medicines you take, and how you sleep, feel and eat. Some medicines cause weight gain. Never stop or change one on your own: ask whether there is another option.',
  hook:'Weight-gain medicines (257 RCTs): pioglitazone and glyburide 2.6 kg, olanzapine 2.4 kg, gabapentin 2.2 kg. Population averages. <sup class="c" data-ref="Domecq2015" title="Source 123"><a href="/obesity/sources/#src-Domecq2015">123</a></sup>'},
 {from:2/6,at:2/6+.1,k:'5As · Assess',t:'Measure: BMI, waist and the right cuff',
  txt:'The Lancet Commission says BMI is a population and screening measure; excess adiposity should be confirmed by direct fat measurement or at least one of waist, waist-to-hip or waist-to-height, except above BMI 40, where it can be assumed. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup> The IAS/ICCR consensus calls waist circumference a "vital sign". <sup class="c" data-ref="Ross2020IASICCR" title="Source 474"><a href="/obesity/sources/#src-Ross2020IASICCR">474</a></sup> A cuff that is too small reads falsely high: the bladder should be 75–100% of the arm circumference, measured midway between acromion and olecranon. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup> Acanthosis nigricans, found in 74% of one obesity clinic sample, marks high insulin. <sup class="c" data-ref="Hud1992" title="Source 236"><a href="/obesity/sources/#src-Hud1992">236</a></sup>',
  pt:'Your blood pressure should be measured with a cuff that fits your arm. A cuff that is too small can show a falsely high reading.',
  hook:'AHA cuff sizes by arm circumference: 22–26 small adult, 27–34 adult, 35–44 large adult, 45–52 cm extra-large adult. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup>'},
 {from:3/6,at:3/6+.1,k:'5As · Assess',t:'Tests, as published',
  txt:'The Lancet Commission (98% consensus): laboratory tests for people with confirmed excess adiposity "should include at least" a full blood count, glycaemia, lipid profile, and renal and liver function tests. Specific tests may be needed "if clinically indicated" to rule out secondary obesity, and people with preclinical or clinical obesity should be regularly screened for type 2 diabetes. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup> AASLD: people with steatosis and metabolic risk factors should have a FIB-4 risk assessment (age, ALT, AST, platelets); under 1.3 rules out advanced fibrosis and 2.67 or more rules it in. <sup class="c" data-ref="Rinella2023AASLD" title="Source 462"><a href="/obesity/sources/#src-Rinella2023AASLD">462</a></sup>',
  pt:'Blood tests look at blood sugar, cholesterol, the kidneys, the liver and a blood count. A normal liver test does not always mean the liver is free of fat.',
  hook:'FIB-4 under 1.3 rules out advanced fibrosis; 2.67 or more rules it in (AASLD). <sup class="c" data-ref="Rinella2023AASLD" title="Source 462"><a href="/obesity/sources/#src-Rinella2023AASLD">462</a></sup>'},
 {from:4/6,at:4/6+.1,k:'Staging',t:'Stage: how is health affected?',
  txt:'The Edmonton Obesity Staging System (EOSS) is a clinical and functional staging system used alongside BMI: a 5-point scale (0–4) for the comorbidity and functional limitation linked to excess weight. <sup class="c" data-ref="Sharma2009EOSS,Padwal2011EOSS" title="Source 416,504"><a href="/obesity/sources/#src-Sharma2009EOSS">416,504</a></sup> In NHANES, over 75% of adults with overweight or obesity scored 1 or 2. Stage 2 (HR 1.57) and stage 3 (HR 2.69) predicted higher mortality than stages 0–1, even after adjusting for BMI, and survival separated by EOSS stage but not by obesity class. <sup class="c" data-ref="Padwal2011EOSS" title="Source 416"><a href="/obesity/sources/#src-Padwal2011EOSS">416</a></sup> The King\'s system scores nine domains from Airways to body Image. <sup class="c" data-ref="Aasheim2011" title="Source 1"><a href="/obesity/sources/#src-Aasheim2011">1</a></sup>',
  pt:'Staging asks how weight is affecting health and daily life, not how big someone is. Two people with the same BMI can be at very different stages.',
  hook:'EOSS predicted mortality where BMI class did not: stage 2 HR 1.57, stage 3 HR 2.69 vs 0–1. <sup class="c" data-ref="Padwal2011EOSS" title="Source 416"><a href="/obesity/sources/#src-Padwal2011EOSS">416</a></sup>'},
 {from:5/6,at:5/6+.11,k:'5As · Advise, Agree, Assist',t:'A shared plan',
  txt:'Advise covers health risks, the benefits of modest weight loss, the need for a long-term strategy and the treatment options. Agree covers realistic expectations and the plan. Assist covers barriers, resources, referrals and regular follow-up. <sup class="c" data-ref="Vallis2013" title="Source 561"><a href="/obesity/sources/#src-Vallis2013">561</a></sup> USPSTF (grade B): clinicians should offer or refer adults with a BMI of 30 or more to intensive, multicomponent behavioural interventions. <sup class="c" data-ref="Curry2018USPSTF" title="Source 107"><a href="/obesity/sources/#src-Curry2018USPSTF">107</a></sup> AACE frames obesity as an "adiposity-based chronic disease" and says care should target its complications as well as adiposity. <sup class="c" data-ref="Garvey2016AACE" title="Source 180"><a href="/obesity/sources/#src-Garvey2016AACE">180</a></sup>',
  pt:'The plan is made together and is about health, not a number. It includes follow-up, because obesity is long-term and the plan may change.',
  hook:'USPSTF B: offer or refer adults with BMI ≥30 to intensive multicomponent behavioural interventions. <sup class="c" data-ref="Curry2018USPSTF" title="Source 107"><a href="/obesity/sources/#src-Curry2018USPSTF">107</a></sup>'}
];
const AS_NODES=['Ask','History','Measure','Tests','Stage','Plan'];
const AS_CUFF=[{n:'small adult',a:22,b:26},{n:'adult',a:27,b:34},{n:'large adult',a:35,b:44},{n:'extra-large adult',a:45,b:52}];
const AS_TESTS=['blood count','glycaemia','lipids','kidney','liver'];
const AS_HIST=['weight over the years','medicines','sleep','mood','eating patterns'];
/* EOSS teaching tool */
const AS_LV=['none','mild','moderate','severe','end-stage'];
const AS_DOM=[{id:'asMed',n:'Medical: risk factors and comorbidities'},{id:'asPsy',n:'Mental health'},{id:'asFun',n:'Daily function'}];
/* Lancet Commission adult criteria for clinical obesity (Table 2), as listed */
const AS_LC=['Raised intracranial pressure','Sleep apnoeas or hypopnoeas','Hypoventilation or breathlessness','Heart failure with reduced ejection fraction','Heart failure with preserved ejection fraction','Chronic or recurrent atrial fibrillation','Pulmonary hypertension','Recurrent deep-vein thrombosis or pulmonary embolism','Raised blood pressure','Hyperglycaemia with high triglycerides and low HDL','Fatty liver disease with liver fibrosis','Microalbuminuria with reduced eGFR','Recurrent or chronic urinary incontinence','Anovulation, oligomenorrhoea and PCOS','Male hypogonadism','Chronic severe knee or hip pain with stiffness','Lower-limb lymphoedema','Significant limitation of daily activities'];
const AS_SB=[['S','Snoring loudly'],['T','Tired or sleepy in the daytime'],['O','Observed to stop breathing in sleep'],['P','High blood pressure'],['B','BMI over 35'],['A','Age above the tool\'s cut-off'],['N','Neck circumference above the tool\'s cut-off'],['G','Male gender']];

inits.assessment=()=>{
  const svg=$('#asSvg'),rg=$('#asT'),note=$('#asNote');
  const bubble=(x,y,w,h,txt,tail,col)=>`<rect x="${f1(x)}" y="${f1(y)}" width="${w}" height="${h}" rx="12" style="fill:var(--panel);stroke:${col};stroke-width:1.4"/><path d="M${f1(tail[0])} ${f1(y+h)}L${f1(tail[1])} ${f1(y+h+12)}L${f1(tail[0]+12)} ${f1(y+h)}Z" style="fill:var(--panel);stroke:${col};stroke-width:1.4"/><rect x="${f1(tail[0]+1)}" y="${f1(y+h-2)}" width="10" height="3" style="fill:var(--panel)"/>`+txt;
  const typed=(s,u)=>s.slice(0,Math.round(s.length*clamp(u)));
  function scene(p,u,x,y,w,h,N){let s='';
    if(p===0){/* two people, one asks */
      const py=N?y+140:y+h-222,ps=N?280:190,a=person(x+w*.24,py,ps,{size:.25}),b=person(x+w*.62,py,ps,{size:.75});s+=a.svg+b.svg;
      const q='May we talk about weight today?',r='Yes, I\'d like that.',bw=N?190:230;
      s+=bubble(x+(N?4:w*.02),y+(N?6:10),bw,44,`<text x="${f1(x+(N?14:w*.02+12))}" y="${f1(y+(N?33:37))}" class="t-lbl" style="font-size:12.5px">${typed(q,ramp(u,.05,.45))}</text>`,[x+w*.24-6,x+w*.24],'var(--hl)');
      if(u>.5)s+=bubble(x+w*(N?.42:.52),y+(N?62:66),N?178:200,44,`<text x="${f1(x+w*(N?.42:.52)+12)}" y="${f1(y+(N?89:93))}" class="t-lbl" style="font-size:12.5px">${typed(r,ramp(u,.55,.85))}</text>`,[x+w*.62-6,x+w*.62],'var(--brand)');
      s+=`<text x="${f1(x+w/2)}" y="${f1(N?py+ps+22:y+h-2)}" class="t-xs t-mid">ask first, without judgement · "not today" is an answer too</text>`}
    else if(p===1){/* weight history curve and a checklist */
      const cw=N?w:w*.55,ch=N?150:h-60,ax=curveAxes(x+30,y+20,cw-40,ch,{x0:20,x1:60,y0:0,y1:1,xt:[20,30,40,50,60],xlabel:'age (schematic)',ylabel:'weight'});
      s+=ax.svg;const P=[[20,.22],[26,.3],[31,.48],[34,.4],[38,.58],[43,.52],[47,.72],[52,.66],[57,.8]];
      s+=plotLine(P,ax.X,ax.Y,{col:'var(--hl)',upto:lerp(20,57,ease(ramp(u,0,.6))),smooth:true,dot:true}).svg;
      if(u>.35)s+=kitLabel(ax.X(34),ax.Y(.4)+16,'changes around life events','m');
      const lx=N?x+10:x+w*.62,ly=N?y+ch+70:y+30;
      AS_HIST.forEach((t,i)=>{const a=clamp(ramp(u,.15+.13*i,.25+.13*i));const yy=ly+i*(N?28:44);
        s+=`<g style="opacity:${f1(.25+.75*a)}"><rect x="${f1(lx)}" y="${f1(yy)}" width="20" height="20" rx="5" style="fill:${a>.9?'var(--hl)':'var(--panel)'};stroke:var(--hl);stroke-width:1.4"/>${a>.9?`<path d="M${f1(lx+5)} ${f1(yy+10)}L${f1(lx+9)} ${f1(yy+14)}L${f1(lx+15)} ${f1(yy+6)}" style="fill:none;stroke:var(--panel);stroke-width:2.2"/>`:''}<text x="${f1(lx+30)}" y="${f1(yy+15)}" class="t-lbl" style="font-size:13px">${t}</text></g>`})}
    else if(p===2){/* a person with a waist tape and a cuff; the arm circumference sweeps the AHA cuff table */
      const px=x+(N?60:w*.16),pr=person(px,y+10,N?250:h-30,{size:.6}),k=(N?250:h-30)/100;s+=pr.svg;
      const bl=pr.at.belly,ww=(14.6+7.4*.6)*k;
      s+=`<ellipse cx="${f1(bl[0])}" cy="${f1(bl[1]+3*k)}" rx="${f1(ww*.78)}" ry="${f1(2.2*k)}" style="fill:none;stroke:var(--gold);stroke-width:3;stroke-dasharray:${f1(lerp(0,200,ramp(u,0,.3)))} 400"/>`;
      if(u>.2)s+=kitLabel(bl[0]+ww+8,bl[1]+3*k+16,'waist, a "vital sign"',{});
      const cy=pr.at.chest[1]+6*k,cx=px+(13.8+6*.6)*k;
      s+=`<rect x="${f1(cx-5*k*.9)}" y="${f1(cy)}" width="${f1(10*k*.9)}" height="${f1(9*k)}" rx="4" style="fill:var(--device);opacity:${f1(.4+.5*ramp(u,.25,.4))}"/>`;
      if(u>.3)s+=kitLabel(cx+8*k,cy-4,'BP cuff on the upper arm',{});
      const arm=Math.round(lerp(23,50,ease(ramp(u,.35,.95)))),tx=N?x+20:x+w*.52,ty=N?y+290:y+40;
      s+=`<text x="${f1(tx)}" y="${f1(ty)}" class="t-lbl">arm circumference</text><text x="${f1(tx)}" y="${f1(ty+32)}" class="t-big" style="font-size:28px;fill:var(--hl)">${arm} cm</text>`;
      AS_CUFF.forEach((c,i)=>{const yy=ty+50+i*(N?32:38),hit=arm>=c.a&&arm<=c.b;
        s+=`<rect x="${f1(tx)}" y="${f1(yy)}" width="${N?330:300}" height="${N?26:30}" rx="8" style="fill:${hit?'var(--hl-soft)':'var(--panel)'};stroke:${hit?'var(--hl)':'var(--line)'};stroke-width:${hit?2:1}"/><text x="${f1(tx+12)}" y="${f1(yy+(N?17:20))}" class="t-lbl" style="font-size:13px">${c.n}</text><text x="${f1(tx+(N?318:288))}" y="${f1(yy+(N?17:20))}" class="t-sm t-end">${c.a}–${c.b} cm</text>`});
      s+=`<text x="${f1(tx)}" y="${f1(ty+50+4*(N?32:38)+12)}" class="t-xs">AHA illustrative sizes; bladder length 75–100% of the arm</text>`}
    else if(p===3){/* test tubes fill one by one */
      const n=AS_TESTS.length,gap=N?72:96,x0=x+(w-gap*(n-1))/2;
      AS_TESTS.forEach((t,i)=>{const a=ease(clamp(ramp(u,.05+.12*i,.2+.12*i))),tx=x0+i*gap,ty=y+40,th=N?120:150,lv=th*.78*a;
        s+=`<rect x="${f1(tx-12)}" y="${f1(ty+th-lv-4)}" width="24" height="${f1(lv)}" rx="10" style="fill:var(--vessel);opacity:.75"/><path d="M${f1(tx-14)} ${f1(ty)}V${f1(ty+th-12)}A14 14 0 0 0 ${f1(tx+14)} ${f1(ty+th-12)}V${f1(ty)}" style="fill:none;stroke:var(--ink);stroke-width:1.6"/><rect x="${f1(tx-17)}" y="${f1(ty-10)}" width="34" height="12" rx="3" style="fill:var(--device)"/>`;
        s+=`<text x="${f1(tx)}" y="${f1(ty+th+20)}" class="t-lbl t-mid" style="font-size:12.5px">${t}</text>`});
      const by=y+(N?230:240);
      if(u>.65)s+=`<g style="opacity:${f1(ramp(u,.65,.8))}">${kitLabel(x+w/2,by,'+ FIB-4 if fat in the liver and metabolic risk (AASLD)',{a:'m'})}${kitLabel(x+w/2,by+22,'+ tests for secondary causes "if clinically indicated"',{a:'m'})}${kitLabel(x+w/2,by+44,'+ regular screening for type 2 diabetes',{a:'m'})}</g>`}
    else if(p===4){/* EOSS staircase */
      const sw=N?66:96,sh=N?44:46,x0=x+(w-sw*5)/2,base=y+h-30,cur=Math.min(4,Math.floor(ease(ramp(u,.05,.85))*5));
      for(let i=0;i<5;i++){const hh=sh*(i+1),on=i===cur;
        s+=`<rect x="${f1(x0+i*sw)}" y="${f1(base-hh)}" width="${sw-6}" height="${hh}" rx="6" style="fill:${on?'var(--hl)':'var(--panel-2)'};stroke:var(--hl);stroke-width:${on?2:1};opacity:${on?.9:.8}"/><text x="${f1(x0+i*sw+(sw-6)/2)}" y="${f1(base-hh+24)}" class="t-big t-mid" style="fill:${on?'var(--panel)':'var(--ink)'}">${i}</text>`;
        const hr=i<2?'HR 1 (ref)':i===2?'HR 1.57':i===3?'HR 2.69':'';if(hr)s+=`<text x="${f1(x0+i*sw+(sw-6)/2)}" y="${f1(base+16)}" class="t-xs t-mid">${hr}</text>`}
      s+=`<text x="${f1(x+w/2)}" y="${f1(y+14)}" class="t-lbl t-mid">EOSS stage 0–4: comorbidity and function, not size</text><text x="${f1(x+w/2)}" y="${f1(y+30)}" class="t-xs t-mid">mortality vs stages 0–1, NHANES (Padwal 2011)</text>`}
    else{/* Advise, Agree, Assist and back to follow-up */
      const L=['Advise','Agree','Assist'],D=['risks, benefits, options','expectations and plan','barriers and referrals'],cw=N?300:190,ch=N?62:110;
      L.forEach((l,i)=>{const a=ease(clamp(ramp(u,.05+.18*i,.25+.18*i))),cx=N?x+(w-cw)/2:x+18+i*(cw+40),cy=N?y+20+i*(ch+26):y+60;
        s+=`<g style="opacity:${f1(.15+.85*a)}"><rect x="${f1(cx)}" y="${f1(cy)}" width="${cw}" height="${ch}" rx="14" style="fill:var(--hl-soft);stroke:var(--hl);stroke-width:1.4"/><text x="${f1(cx+16)}" y="${f1(cy+28)}" class="t-big" style="fill:var(--hl)">${l}</text><text x="${f1(cx+16)}" y="${f1(cy+50)}" class="t-sm" style="fill:var(--ink)">${D[i]}</text></g>`;
        if(i<2&&a>.9)s+=N?`<path d="M${f1(x+w/2)} ${f1(cy+ch+3)}V${f1(cy+ch+22)}" class="arrow" marker-end="url(#asArr)"/>`:`<path d="M${f1(cx+cw+4)} ${f1(cy+ch/2)}H${f1(cx+cw+34)}" class="arrow" marker-end="url(#asArr)"/>`});
      if(u>.7){const fy=N?y+20+3*(ch+26)+10:y+210;s+=`<g style="opacity:${f1(ramp(u,.7,.85))}"><path d="M${f1(N?x+w-30:x+w-60)} ${f1(fy-10)}C${f1(N?x+w-30:x+w-60)} ${f1(fy+30)} ${f1(x+60)} ${f1(fy+30)} ${f1(x+60)} ${f1(fy-6)}" class="arrow" marker-end="url(#asArr)"/><text x="${f1(x+w/2)}" y="${f1(fy+44)}" class="t-lbl t-mid">regular follow-up: a long-term, changing plan</text></g>`}}
    return s}
  function draw(t){
    const N=vb(svg,'720 380','400 560'),p=phaseOf(AS_STEPS,t),u=clamp((t-AS_STEPS[p].from)*6);
    let s=`<defs>${marker('asArr','var(--muted)')}</defs>`;
    const nx=i=>N?30+i*68:70+i*116,ny=30;
    s+=`<line x1="${nx(0)}" x2="${nx(5)}" y1="${ny}" y2="${ny}" style="stroke:var(--line);stroke-width:3"/><line x1="${nx(0)}" x2="${f1(lerp(nx(0),nx(5),clamp(t*1.08)))}" y1="${ny}" y2="${ny}" style="stroke:var(--hl);stroke-width:3"/>`;
    AS_NODES.forEach((n,i)=>{const on=i===p,done=i<p;s+=`<circle cx="${nx(i)}" cy="${ny}" r="${on?12:9}" style="fill:${on||done?'var(--hl)':'var(--panel)'};stroke:var(--hl);stroke-width:2"/><text x="${nx(i)}" y="${ny+4}" class="t-xs t-mid" style="fill:${on||done?'var(--panel)':'var(--ink)'};font-weight:700">${i+1}</text><text x="${nx(i)}" y="${ny+(on?28:25)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:${on?700:500}">${n}</text>`});
    s+=scene(p,u,N?10:20,72,N?380:680,N?480:300,N);
    svg.innerHTML=s;note.innerHTML=noteHTML(AS_STEPS[p]);setA(p);
  }
  const stop=playWire(rg,$('#asPlay'),draw,30000,'Replay','assessment');
  const setA=stepWire($('#asSteps'),AS_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- EOSS teaching tool ---- */
  const esvg=$('#asEossSvg'),eout=$('#asEossOut');
  AS_DOM.forEach(d=>{const el=$('#'+d.id);el.innerHTML=AS_LV.map((l,i)=>`<option value="${i}">${i} · ${l}</option>`).join('');el.addEventListener('change',drawE)});
  function drawE(){
    const v=AS_DOM.map(d=>+$('#'+d.id).value),st=Math.max(...v),N=vb(esvg,'720 240','400 300');
    const x0=N?40:200,w=N?320:440,X=h=>x0+w*h/3,rows=[{l:'Stages 0–1',h:1,st:[0,1]},{l:'Stage 2',h:1.57,st:[2]},{l:'Stage 3',h:2.69,st:[3]},{l:'Stage 4',h:null,st:[4]}];
    let s='';[0,1,2,3].forEach(h=>{s+=`<line x1="${f1(X(h))}" x2="${f1(X(h))}" y1="20" y2="${N?250:200}" class="grid"/><text x="${f1(X(h))}" y="${N?266:216}" class="t-xs t-mid">${h}</text>`});
    s+=`<text x="${f1(X(3))}" y="${N?284:232}" class="t-xs t-end">mortality hazard ratio vs stages 0–1 (NHANES)</text>`;
    rows.forEach((r,i)=>{const y=N?24+i*58:26+i*44,on=r.st.includes(st);
      s+=`<text x="${N?x0:x0-12}" y="${y+(N?12:18)}" class="t-lbl${N?'':' t-end'}" style="font-size:13px;fill:${on?'var(--hl)':'var(--ink)'}">${r.l}${on?' ◀ this sketch':''}</text>`;
      const by=N?y+18:y+4;
      if(r.h)s+=`<rect x="${x0}" y="${by}" width="${f1(X(r.h)-x0)}" height="22" rx="4" style="fill:var(--hl);opacity:${on?.95:.35}"/><text x="${f1(X(r.h)+6)}" y="${by+16}" class="t-sm" style="fill:var(--ink);font-weight:700">${r.h===1?'1 (reference)':r.h}</text>`;
      else s+=`<text x="${x0}" y="${by+16}" class="t-sm">no separate figure published in these cohorts</text>`});
    rows.forEach((r,i)=>{if(!r.h)return;const by=N?24+i*58+18:26+i*44+4;s+=`<line x1="${f1(X(1))}" x2="${f1(X(1))}" y1="${by-4}" y2="${by+26}" style="stroke:var(--ink);stroke-width:1.4"/>`});
    esvg.innerHTML=s;
    const why=AS_DOM.filter((d,i)=>v[i]===st&&st>0).map(d=>d.n.toLowerCase().split(':')[0]).join(' and ');
    eout.innerHTML=`<div class="verdict ${st<=1?'yes':'maybe'}">Teaching sketch: EOSS stage ${st}${why?` (set by ${why})`:''}</div><p>${st<=1?'In the Aerobics Center cohort, stage 0/1 obesity was not associated with higher mortality than normal weight. <sup class="c" data-ref="Kuk2011EOSS" title="Source 303"><a href="/obesity/sources/#src-Kuk2011EOSS">303</a></sup>':st===2?'Stage 2 carried a mortality HR of 1.57 vs stages 0–1 in NHANES <sup class="c" data-ref="Padwal2011EOSS" title="Source 416"><a href="/obesity/sources/#src-Padwal2011EOSS">416</a></sup>, and 1.6 vs normal weight in the Aerobics Center cohort. <sup class="c" data-ref="Kuk2011EOSS" title="Source 303"><a href="/obesity/sources/#src-Kuk2011EOSS">303</a></sup>':st===3?'Stage 3 carried a mortality HR of 2.69 vs stages 0–1 in NHANES <sup class="c" data-ref="Padwal2011EOSS" title="Source 416"><a href="/obesity/sources/#src-Padwal2011EOSS">416</a></sup>, and 1.7 vs normal weight in the Aerobics Center cohort. <sup class="c" data-ref="Kuk2011EOSS" title="Source 303"><a href="/obesity/sources/#src-Kuk2011EOSS">303</a></sup>':'Stage 4 is the most severe point of the 5-point scale. <sup class="c" data-ref="Padwal2011EOSS" title="Source 416"><a href="/obesity/sources/#src-Padwal2011EOSS">416</a></sup> The cohorts here report no separate mortality figure for it.'} Population statistics, not a prognosis.</p>`;
  }
  drawE();

  /* ---- Lancet Commission checklist ---- */
  const lc=$('#asLc'),lout=$('#asLcOut'),adi=$('#asAdi');
  lc.innerHTML=AS_LC.map((c,i)=>`<label><input type="checkbox" data-lc="${i}"> ${c}</label>`).join('');
  function drawC(){const n=$$('[data-lc]:checked',lc).length,a=adi.checked;
    lout.innerHTML=!a?`<div class="verdict maybe">Excess adiposity not confirmed</div><p>In the Commission's framework, BMI alone does not confirm excess adiposity: it needs a direct fat measurement or at least one of waist, waist-to-hip or waist-to-height, unless BMI is over 40. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup></p>`
      :n===0?`<div class="verdict yes">Pattern described: preclinical obesity</div><p>Excess adiposity with organ function preserved. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup></p>`
      :`<div class="verdict no">Pattern described: clinical obesity (${n} of 18 criteria ticked)</div><p>A chronic, systemic illness in which excess adiposity alters organ or tissue function, or limits daily activities. <sup class="c" data-ref="Rubino2025Commission" title="Source 480"><a href="/obesity/sources/#src-Rubino2025Commission">480</a></sup> A clinician must judge that the problem is caused by excess adiposity and not by something else.</p>`}
  lc.addEventListener('change',drawC);adi.addEventListener('change',drawC);drawC();

  /* ---- STOP-Bang ---- */
  const sb=$('#asSb'),sout=$('#asSbOut');
  sb.innerHTML=AS_SB.map((q,i)=>`<label><input type="checkbox" data-sb="${i}"> <b>${q[0]}</b> ${q[1]}</label>`).join('');
  function drawS(){const on=$$('[data-sb]',sb).map(b=>b.checked),sc=on.filter(Boolean).length,stop=on.slice(0,4).filter(Boolean).length,hiMid=sc>=3&&sc<=4&&stop>=2&&on[4];
    const band=sc<=2?'low':sc>=5||hiMid?'high':'intermediate';
    sout.innerHTML=`<div class="verdict ${band==='low'?'yes':band==='high'?'no':'maybe'}">Score ${sc} of 8: ${band} risk band</div><p>${band==='low'?'Scores 0–2: low risk; in the validation data, 18% had moderate-to-severe and 4% severe OSA. <sup class="c" data-ref="Chung2016STOPBang" title="Source 81"><a href="/obesity/sources/#src-Chung2016STOPBang">81</a></sup>':band==='high'?`${hiMid?'In the mid-range (3–4), a STOP score of 2 or more plus BMI over 35 classifies as high risk. ':''}Scores 5–8: high risk; at 7–8, 60% had moderate-to-severe and 38% severe OSA. <sup class="c" data-ref="Chung2016STOPBang" title="Source 81"><a href="/obesity/sources/#src-Chung2016STOPBang">81</a></sup>`:'Scores 3–4: intermediate. A score of 3 or more had 93% sensitivity for moderate-to-severe OSA. <sup class="c" data-ref="Chung2016STOPBang" title="Source 81"><a href="/obesity/sources/#src-Chung2016STOPBang">81</a></sup>'} A screening questionnaire, not a diagnosis: only a sleep study can confirm sleep apnoea.</p>`}
  sb.addEventListener('change',drawS);drawS();
  const prevR=redraws.assessment;redraws.assessment=()=>{prevR&&prevR();drawE()};
};
/* =============== 2.4 Weight stigma & bias =============== */
/* SVG text helper shared by this module: wraps words into tspans of at most n characters. */
function stWrap(x,y,str,n,cls,lh=13,style=''){
  const W=String(str).split(' '),L=[];let cur='';
  W.forEach(w=>{if(cur&&(cur+' '+w).length>n){L.push(cur);cur=w}else cur=cur?cur+' '+w:w});if(cur)L.push(cur);
  return {svg:`<text x="${f1(x)}" y="${f1(y)}" class="${cls}"${style?` style="${style}"`:''}>${L.map((l,i)=>`<tspan x="${f1(x)}" dy="${i?lh:0}">${l}</tspan>`).join('')}</text>`,h:L.length*lh};
}
inits.stigma=()=>{
  /* ---------- the loop ---------- */
  const svg=$('#stSvg'),rg=$('#stT'),note=$('#stNote');
  const STEPS=[
   {from:0,at:.06,k:'How common',t:'Stigma is common',
    txt:'Among adults with obesity, 19–42% report weight discrimination, more at higher BMI and in women. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> In 13,996 adults in weight-management programmes across six countries, 56–61% had experienced weight stigma, and two-thirds of them reported it from doctors. <sup class="c" data-ref="Puhl2021SixCountries" title="Source 448"><a href="/obesity/sources/#src-Puhl2021SixCountries">448</a></sup> Common stereotypes cast people as lazy, gluttonous, lacking willpower, unmotivated, non-compliant and personally to blame. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>',
    pt:'Many people living with obesity are treated unfairly because of their weight, including by health workers. It is common, and it is not their fault.',
    hook:'Six-country survey: 56–61% experienced weight stigma; two-thirds of them from doctors. <sup class="c" data-ref="Puhl2021SixCountries" title="Source 448"><a href="/obesity/sources/#src-Puhl2021SixCountries">448</a></sup>'},
   {from:.16,at:.22,k:'In the clinic',t:'Bias in care',
    txt:'Among 2284 doctors who took the Weight Implicit Association Test, implicit anti-fat bias was strong (Cohen\'s d = 0.93), about the same as in the general public (d = 1.0). <sup class="c" data-ref="Sabin2012" title="Source 483"><a href="/obesity/sources/#src-Sabin2012">483</a></sup> Many clinicians hold negative attitudes toward people with obesity; these affect judgement, behaviour and decisions, and can lower the quality of care despite good intentions. <sup class="c" data-ref="Phelan2015" title="Source 426"><a href="/obesity/sources/#src-Phelan2015">426</a></sup>',
    pt:'Health workers grow up in the same culture as everyone else, so many carry the same hidden bias. Noticing it is the first step.',
    hook:'Doctors\' implicit anti-fat bias d = 0.93 vs public d = 1.0 (Weight IAT, n = 2284 doctors). <sup class="c" data-ref="Sabin2012" title="Source 483"><a href="/obesity/sources/#src-Sabin2012">483</a></sup>'},
   {from:.32,at:.38,k:'Staying away',t:'Avoiding care',
    txt:'Expecting poor treatment leads to stress, avoiding care, mistrust and poorer adherence. <sup class="c" data-ref="Phelan2015" title="Source 426"><a href="/obesity/sources/#src-Phelan2015">426</a></sup> In a US survey of 1064 adults, 19% would avoid future appointments and 21% would seek a new doctor if they felt stigmatised about their weight by their doctor. <sup class="c" data-ref="Puhl2013Language" title="Source 445"><a href="/obesity/sources/#src-Puhl2013Language">445</a></sup> Higher internalised weight bias went with more avoidance of care, fewer routine check-ups and lower perceived quality of care, independent of BMI. <sup class="c" data-ref="Puhl2021SixCountries" title="Source 448"><a href="/obesity/sources/#src-Puhl2021SixCountries">448</a></sup>',
    pt:'If a visit feels shaming, people put off the next one. Missed check-ups mean problems are found later.',
    hook:'Felt stigmatised by their doctor: 19% would avoid future appointments, 21% would change doctor. <sup class="c" data-ref="Puhl2013Language" title="Source 445"><a href="/obesity/sources/#src-Puhl2013Language">445</a></sup>'},
   {from:.48,at:.54,k:'In the body',t:'Stress in the body',
    txt:'In 33 studies of adults, weight stigma was associated with higher cortisol, oxidative stress and CRP, and with higher obesity and diabetes risk. <sup class="c" data-ref="Wu2018" title="Source 610"><a href="/obesity/sources/#src-Wu2018">610</a></sup> Weight discrimination was associated with nearly 60% higher mortality: HR 1.57 in the Health and Retirement Study (n = 13,692) and HR 1.59 in MIDUS (n = 5079), not explained by common physical or psychological risk factors. <sup class="c" data-ref="Sutin2015" title="Source 532"><a href="/obesity/sources/#src-Sutin2015">532</a></sup>',
    pt:'Being treated badly again and again is a real stress on the body, not just on feelings.',
    hook:'Weight discrimination: HR 1.57–1.59 for death in two US cohorts. <sup class="c" data-ref="Sutin2015" title="Source 532"><a href="/obesity/sources/#src-Sutin2015">532</a></sup>'},
   {from:.64,at:.7,k:'Eating, mood, moving',t:'Turned inwards',
    txt:'Weight stigma is associated with more disordered eating, depression and anxiety, and lower self-esteem. <sup class="c" data-ref="Wu2018" title="Source 610"><a href="/obesity/sources/#src-Wu2018">610</a></sup> About 40–50% of US adults with overweight or obesity internalise weight bias, about 20% at high levels. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> Across 74 studies, internalised weight bias had strong negative links with mental health; links with physical health were less consistent. <sup class="c" data-ref="Pearl2018WBI" title="Source 420"><a href="/obesity/sources/#src-Pearl2018WBI">420</a></sup> In young people, stigma contributes to binge eating, social isolation and less physical activity. <sup class="c" data-ref="Pont2017AAP" title="Source 433"><a href="/obesity/sources/#src-Pont2017AAP">433</a></sup>',
    pt:'Hearing hurtful messages for years can lead people to believe them. That can affect eating, mood and how comfortable someone feels being active in public.',
    hook:'Internalised weight bias: about 40–50% of US adults with overweight or obesity, 20% at high levels. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>'},
   {from:.8,at:.97,k:'The loop',t:'The loop closes, and can be broken',
    txt:'Weight stigma raises the risk of obesity through several pathways and harms health over and above BMI <span class="ev early">Early evidence</span>, <sup class="c" data-ref="Tomiyama2018" title="Source 549"><a href="/obesity/sources/#src-Tomiyama2018">549</a></sup> so stigma is not a useful public-health tool: it threatens health, creates disparities and interferes with treatment. <span class="ev est">Established</span> <sup class="c" data-ref="Puhl2010AJPH,Rubino2020Stigma" title="Source 442,477"><a href="/obesity/sources/#src-Puhl2010AJPH">442,477</a></sup> The consensus agreed (above 90%) that the belief that obesity is a choice, reversible by eating less and moving more, misleads policy and undermines access to treatment, and all signatories agreed that weight stigma should not be tolerated in education, health care or public policy. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>',
    pt:'Shame does not help anyone get healthier. Respect does more: fair words, fitting equipment and care that treats obesity as the chronic disease it is.',
    hook:'Stigma reduction targets those who stigmatise, starting in health-professional training, not the people who experience it. <sup class="c" data-ref="Tomiyama2018,Rubino2020Stigma" title="Source 477,549"><a href="/obesity/sources/#src-Tomiyama2018">477,549</a></sup>'}
  ];
  /* nodes: reveal time, label lines */
  const NODES={stig:{r:0,l:['Weight','stigma']},avoid:{r:.32,l:['Avoiding','care']},stress:{r:.48,l:['Stress in','the body']},
    eat:{r:.64,l:['Disordered eating,','low mood']},move:{r:.64,l:['Less','activity']},out:{r:.8,l:['Weight gain,','worse health']}};
  const MED=['stress','avoid','eat','move'];
  const ACT=[['stig'],['stig','avoid'],['avoid'],['stress'],['eat','move'],['out','stig']];
  /* the stat panel for each step */
  const STAT=[
   {big:'56–61%',cap:'of 13,996 adults in weight-management programmes in six countries had experienced weight stigma',vis:'icons',g:[[56,'var(--hl)'],[5,'var(--hl-soft)']]},
   {big:'d = 0.93',cap:'implicit anti-fat bias in 2284 doctors, close to the general public',vis:'bars',max:1.2,b:[['Doctors',.93,'var(--hl)'],['General public',1.0,'var(--muted)']],fmt:v=>v.toFixed(2)},
   {big:'19%',cap:'would avoid future appointments, and 21% would change doctor, after feeling stigmatised about weight',vis:'icons',g:[[19,'var(--hl)'],[21,'var(--hl-soft)']]},
   {big:'≈ 60%',cap:'higher mortality with weight discrimination (hazard ratios 1.57 and 1.59)',vis:'bars',max:1.8,b:[['No discrimination',1.0,'var(--muted)'],['HRS cohort',1.57,'var(--hl)'],['MIDUS cohort',1.59,'var(--hl)']],fmt:v=>v.toFixed(2)},
   {big:'40–50%',cap:'of US adults with overweight or obesity internalise weight bias; about 20% at high levels',vis:'icons',g:[[20,'var(--hl)'],[30,'var(--hl-soft)']]},
   {big:'Unanimous',cap:'2020 international consensus: weight stigma causes harm and should not be tolerated',vis:'list',items:['Causes physical and psychological harm','Keeps people from seeking good care','Not tolerated in schools, care or policy','Obesity is not simply a choice (over 90%)']}
  ];
  const stopP=playWire(rg,$('#stPlay'),draw,22000,'Replay','stigma');
  const setStep=stepWire($('#stSteps'),STEPS,rg,draw,stopP);
  function box(cx,cy,w,h,lines,state){
    const on=state==='on',vis=state!=='hidden';
    let s=`<g style="opacity:${vis?1:.4}"><rect x="${f1(cx-w/2)}" y="${f1(cy-h/2)}" width="${w}" height="${h}" rx="12" style="fill:${on?'var(--hl-soft)':'var(--panel-2)'};stroke:${on?'var(--hl)':'var(--line)'};stroke-width:${on?2.4:1.2}"/>`;
    const lh=14,y0=cy-(lines.length-1)*lh/2+4.5;
    lines.forEach((l,i)=>{s+=`<text x="${f1(cx)}" y="${f1(y0+i*lh)}" class="t-lbl t-mid" style="font-size:12.5px${on?';fill:var(--hl)':''}">${l}</text>`});
    return s+'</g>';
  }
  function edge(P,live,t,col,dash){
    /* P: points of a polyline; live: dots travel along it */
    let s=`<path d="${ptsD(P)}" style="fill:none;stroke:${live?col:'var(--line)'};stroke-width:${live?2:1.4};${dash?'stroke-dasharray:5 4;':''}" marker-end="url(#stArr${live?'On':'Off'})"/>`;
    if(live&&!RM){const f=polyAt(P);for(let i=0;i<3;i++){const u=((t*9+i/3)%1+1)%1,p=f(u);s+=`<circle cx="${f1(p[0])}" cy="${f1(p[1])}" r="3.2" style="fill:${col}"/>`}}
    return s;
  }
  function stat(S,x,y,w,h,u){
    /* u 0..1: build-up within the step */
    let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" style="fill:var(--panel-2)"/>`;
    const N=NARROW();
    const bx=x+14,bw=N?w-28:Math.min(240,w*.4);
    s+=`<text x="${bx}" y="${y+(N?36:38)}" class="t-big" style="font-size:${N?28:30}px;fill:var(--hl)">${S.big}</text>`;
    s+=stWrap(bx,y+(N?58:62),S.cap,N?46:30,'t-lbl',15,'font-weight:500;font-size:13px').svg;
    const vx=N?x+14:x+bw+30,vy=N?y+120:y+16,vw=N?w-28:w-bw-44;
    if(S.vis==='icons'){
      let acc=0;const groups=S.g.map(([k,col])=>{const kk=Math.round(clamp(u*(acc+k)-acc,0,k));acc+=k;return {k:kk,col}});
      const sz=N?11:12,ia=iconArray(vx,vy,{n:100,cols:20,size:sz,gap:N?4:3.4,groups,shape:'person',base:'var(--line)'});
      s+=ia.svg+`<text x="${vx}" y="${f1(vy+ia.h+12)}" class="t-xs">each figure = 1 in 100</text>`;
    }else if(S.vis==='bars'){
      const rows=S.b.length,rh=N?26:Math.min(24,(h-30)/rows-6),lw=N?118:110;
      S.b.forEach((b,i)=>{const yy=vy+(N?8:2)+i*(rh+6),ww=(vw-lw-50)*b[1]/S.max*ease(clamp(u*1.15));
        s+=`<text x="${vx+lw-6}" y="${f1(yy+rh/2+4)}" class="t-xs t-end" style="fill:var(--ink)">${b[0]}</text>`;
        s+=`<rect x="${vx+lw}" y="${f1(yy)}" width="${f1(Math.max(1,ww))}" height="${f1(rh)}" rx="4" style="fill:${b[2]}"/>`;
        s+=`<text x="${f1(vx+lw+ww+6)}" y="${f1(yy+rh/2+4)}" class="t-xs" style="fill:var(--ink);font-weight:700">${S.fmt(b[1]*clamp(u*1.15))}</text>`});
    }else{
      S.items.forEach((it,i)=>{const show=clamp(u*S.items.length*1.2-i),yy=vy+14+i*(N?24:26);
        s+=`<g style="opacity:${f1(show)}"><path d="M${vx} ${yy-4}l4 4 8-9" style="fill:none;stroke:var(--life);stroke-width:2.2;stroke-linecap:round"/><text x="${vx+18}" y="${yy}" class="t-lbl" style="font-weight:500">${it}</text></g>`});
    }
    return s;
  }
  function draw(t){
    vb(svg,'720 380','400 560');const N=NARROW(),p=phaseOf(STEPS,t),S=STEPS[p];setStep(p);
    const act=ACT[p];
    const st=id=>t<NODES[id].r?'hidden':act.includes(id)?'on':'seen';
    let s=`<defs>${marker('stArrOn','var(--hl)',7)}${marker('stArrOff','var(--line)',7)}</defs>`;
    /* geometry */
    let P,bw,bh,mw;
    if(!N){P={stig:[92,126],out:[620,126],stress:[352,46],avoid:[352,98],eat:[352,152],move:[352,204]};bw=128;bh=50;mw=164}
    else{P={stig:[200,48],stress:[112,134],avoid:[288,134],eat:[112,196],move:[288,196],out:[200,278]};bw=150;bh=46;mw=156}
    const mh=N?44:42;
    /* edges */
    MED.forEach(m=>{
      const a=P.stig,b=P[m],live=t>=NODES[m].r;
      const e1=N?[[a[0]+(b[0]<200?-30:30),a[1]+bh/2],[b[0],b[1]-mh/2-2]]:[[a[0]+bw/2,a[1]],[b[0]-mw/2-2,b[1]]];
      s+=edge(e1,live,t,'var(--hl)');
      const o=P.out,live2=t>=NODES.out.r;
      const e2=N?[[b[0],b[1]+mh/2],[o[0]+(b[0]<200?-30:30),o[1]-bh/2-2]]:[[b[0]+mw/2,b[1]],[o[0]-bw/2-2,o[1]]];
      s+=edge(e2,live2,t,'var(--hl)');
    });
    /* the return arc: worse health draws more stigma */
    const ret=N?[[P.out[0]-bw/2,P.out[1]],[18,P.out[1]],[18,P.stig[1]],[P.stig[0]-bw/2-2,P.stig[1]]]
               :[[P.out[0],P.out[1]-bh/2],[P.out[0],13],[P.stig[0],13],[P.stig[0],P.stig[1]-bh/2-2]];
    const retLive=t>=NODES.out.r;
    s+=edge(ret,retLive,t,'var(--hl)',true);
    if(retLive){const lp=N?[24,(P.out[1]+P.stig[1])/2]:[(P.out[0]+P.stig[0])/2,10];
      s+=N?`<text x="30" y="${lp[1]}" class="t-xs" transform="rotate(-90 30 ${lp[1]})" style="text-anchor:middle;fill:var(--ink);font-weight:700;paint-order:stroke;stroke:var(--panel);stroke-width:3px">more stigma</text>`
          :kitLabel(lp[0],lp[1]+3,'and round again: more stigma',{a:'m'})}
    /* breaking the loop: a shield on the return path late in the last step */
    const brk=ramp(t,.9,.97);
    if(brk>0){const c=N?[66,P.out[1]]:[(P.out[0]+P.stig[0])/2+120,13];
      s+=`<g style="opacity:${f1(brk)}"><circle cx="${c[0]}" cy="${c[1]}" r="${f1(9+4*brk)}" style="fill:var(--life-soft);stroke:var(--life);stroke-width:2.4"/><path d="M${c[0]-6} ${c[1]}l4 4 8-9" style="fill:none;stroke:var(--life);stroke-width:2.4;stroke-linecap:round"/></g>`;
      const lx=N?16:c[0]+18,ly=N?c[1]+30:c[1]+4;
      s+=`<text x="${lx}" y="${ly}" class="t-xs" style="fill:var(--life);font-weight:700;opacity:${f1(brk)};paint-order:stroke;stroke:var(--panel);stroke-width:3px">respect breaks the loop</text>`}
    /* nodes */
    s+=box(P.stig[0],P.stig[1],bw,bh,NODES.stig.l,st('stig'));
    MED.forEach(m=>{s+=box(P[m][0],P[m][1],mw,mh,NODES[m].l,st(m))});
    s+=box(P.out[0],P.out[1],bw+(N?0:10),bh,NODES.out.l,st('out'));
    /* stat panel */
    const u=ramp(t,S.from,Math.min(S.at+.04,S.from+.1));
    s+=N?stat(STAT[p],12,322,376,232,u):stat(STAT[p],12,238,696,138,u);
    svg.innerHTML=s;
    note.innerHTML=noteHTML(S);
  }
  draw(+rg.value);

  /* ---------- words matter ---------- */
  const WORDS=[
   {no:'"obese people"',yes:'"people with obesity"',why:'People-first language keeps the disease from defining the person. <sup class="c" data-ref="Kyle2014,Puhl2020Words" title="Source 304,447"><a href="/obesity/sources/#src-Kyle2014">304,447</a></sup>'},
   {no:'"morbidly obese"',yes:'"higher weight", or talk about "weight"',why:'In a US national survey, "weight" and "unhealthy weight" were the most desirable terms; "morbidly obese", "fat" and "obese" the most undesirable, stigmatising and blaming for providers to use. <sup class="c" data-ref="Puhl2013Language" title="Source 445"><a href="/obesity/sources/#src-Puhl2013Language">445</a></sup>'},
   {no:'"fat" (to a child)',yes:'"healthy weight", and talk about habits',why:'Young people preferred "healthy weight"; "obese", "fat" and "large" made them feel sad, ashamed and embarrassed. <sup class="c" data-ref="Puhl2022Terms" title="Source 449"><a href="/obesity/sources/#src-Puhl2022Terms">449</a></sup>'},
   {no:'"lazy, no willpower"',yes:'"a chronic disease with many causes"',why:'The consensus lists lazy, lacking willpower, unmotivated and personally to blame as stereotypes, not facts. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> Genes, biology, surroundings and life circumstances all play a part; see <a href="#causes" data-go="causes">Causes</a>.'},
   {no:'"just eat less and move more"',yes:'"let\'s look at what is driving this, and the options"',why:'Over 90% of the consensus agreed that the belief that obesity is a choice, reversible by eating less and exercising more, misleads policy and undermines access to treatment. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>'},
   {no:'"non-compliant"',yes:'"what has made this hard?"',why:'Expecting poor treatment brings stress, avoided care, mistrust and poorer adherence; a respectful question opens the problem up. <sup class="c" data-ref="Phelan2015" title="Source 426"><a href="/obesity/sources/#src-Phelan2015">426</a></sup>'}
  ];
  const wd=$('#stWords');
  wd.innerHTML=WORDS.map((w,i)=>`<button class="st-fc" data-w="${i}" aria-pressed="false"><span class="st-front"><small>Instead of</small><span class="st-say">${w.no}</span><span class="st-hint">Tap for a person-first alternative</span></span><span class="st-back"><small>Try</small><span class="st-say">${w.yes}</span><span class="st-why">${w.why}</span></span></button>`).join('');
  wd.addEventListener('click',e=>{if(e.target.closest('a'))return;const b=e.target.closest('[data-w]');if(!b)return;b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true')});
  const fa=$('#stFlipAll');
  fa.addEventListener('click',()=>{const on=fa.getAttribute('aria-pressed')!=='true';fa.setAttribute('aria-pressed',on);fa.textContent=on?'Hide all alternatives':'Show all alternatives';$$('[data-w]',wd).forEach(b=>b.setAttribute('aria-pressed',on))});

  /* ---------- pictures matter: a camera over a park scene ---------- */
  const img=$('#stImg'),inote=$('#stImgNote'),fb=$('#stFrBtns');
  const AR=360/250;
  const FR=[
   {b:'Headless crop',c:[150,115,96],k:'Stigmatising framing',t:'Headless',txt:'The camera cuts the head off and keeps the body. In the news-video study this was one of the most common framings; with rear views and isolated body parts it was used to show 65% of adults with higher weight in a negative way. <sup class="c" data-ref="Puhl2013Headless" title="Source 444"><a href="/obesity/sources/#src-Puhl2013Headless">444</a></sup>',bad:true,tips:['Removes the person and keeps the body','A common framing in news videos about obesity','65% of adults and 77% of young people with higher weight were shown negatively']},
   {b:'Isolated body part',c:[150,118,54],k:'Stigmatising framing',t:'A body part, not a person',txt:'A close crop on one part of the body turns a person into a symbol. In three experiments (n = 1251), stereotyped images like these in news stories increased anti-fat attitudes and the wish for social distance. <sup class="c" data-ref="Puhl2013Media" title="Source 446"><a href="/obesity/sources/#src-Puhl2013Media">446</a></sup>',bad:true,tips:['Body parts, rear views and ill-fitting clothes','Stereotyped images raised anti-fat attitudes','and the wish for social distance (3 experiments)']},
   {b:'Whole person, everyday life',c:[150,104,206],k:'Respectful framing',t:'The whole person, living their life',txt:'Show the whole person, head and all, doing ordinary things. In the same experiments, positive, non-stereotyped images improved attitudes. <sup class="c" data-ref="Puhl2013Media" title="Source 446"><a href="/obesity/sources/#src-Puhl2013Media">446</a></sup> The consensus calls for "fair, accurate, and non-stigmatizing portrayals of obesity". <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>',bad:false,tips:['The whole person, in an ordinary setting','Positive, non-stereotyped images','improved attitudes in the same experiments']}
  ];
  fb.innerHTML=FR.map((f,i)=>`<button class="btn" data-fr="${i}" aria-pressed="${i===0}">${f.b}</button>`).join('');
  let fi=0,cam=FR[0].c.slice(),stopC=null;
  /* the scene in world units (300 x 210), drawn once */
  const ID=kid('stc');
  function scene(){
    let s=`<rect x="-200" y="-200" width="700" height="600" style="fill:var(--field)"/>`;
    s+=`<rect x="-200" y="185" width="700" height="300" style="fill:var(--life-soft)"/><path d="M-200 196 Q150 178 500 200" style="fill:none;stroke:var(--line);stroke-width:10;stroke-linecap:round"/>`;
    /* tree */
    s+=`<rect x="36" y="110" width="9" height="78" rx="3" style="fill:var(--figure-line);opacity:.6"/><path d="${blob(40,92,34,4,{rough:.12})}" style="fill:var(--life);opacity:.35"/>`;
    /* bench */
    s+=`<rect x="214" y="158" width="64" height="6" rx="2" style="fill:var(--device)"/><rect x="214" y="146" width="64" height="5" rx="2" style="fill:var(--device)"/><rect x="220" y="164" width="4" height="22" style="fill:var(--device)"/><rect x="268" y="164" width="4" height="22" style="fill:var(--device)"/>`;
    /* a friend further back, and the main person, holding a bag */
    s+=person(250,108,78,{size:.25,op:.85}).svg;
    s+=person(150,40,146,{size:.85}).svg;
    s+=`<path d="M176 128 q8 -2 10 8 l3 22 h-20 l1 -22 q-1 -8 6 -8z" style="fill:var(--accent);opacity:.75"/>`;
    return s;
  }
  const SCN=scene();
  function drawImg(){
    vb(img,'720 300','400 430');const N=NARROW(),F=FR[fi];
    const fx=N?20:20,fy=20,fw=360,fh=250;
    const w=cam[2]*AR,h=cam[2];
    let s=`<defs><clipPath id="${ID}"><rect x="${fx}" y="${fy}" width="${fw}" height="${fh}" rx="10"/></clipPath></defs>`;
    s+=`<g clip-path="url(#${ID})"><svg x="${fx}" y="${fy}" width="${fw}" height="${fh}" viewBox="${f1(cam[0]-w/2)} ${f1(cam[1]-h/2)} ${f1(w)} ${f1(h)}" preserveAspectRatio="xMidYMid slice">${SCN}</svg></g>`;
    /* viewfinder corners */
    const C=(x,y,dx,dy)=>`<path d="M${x} ${y+dy*22}V${y}H${x+dx*22}" style="fill:none;stroke:${F.bad?'var(--bad)':'var(--life)'};stroke-width:3"/>`;
    s+=C(fx+8,fy+8,1,1)+C(fx+fw-8,fy+8,-1,1)+C(fx+8,fy+fh-8,1,-1)+C(fx+fw-8,fy+fh-8,-1,-1);
    s+=`<rect x="${fx}" y="${fy}" width="${fw}" height="${fh}" rx="10" style="fill:none;stroke:var(--line)"/>`;
    const tx=N?20:410,ty=N?300:44;
    s+=`<text x="${tx}" y="${ty}" class="t-sm" style="fill:${F.bad?'var(--bad)':'var(--life)'};font-weight:700;letter-spacing:.08em">${F.k.toUpperCase()}</text>`;
    s+=`<text x="${tx}" y="${ty+26}" class="t-big">${F.t}</text>`;
    const tips=F.tips;
    let ny=ty+52;tips.forEach(tp=>{const w=stWrap(tx,ny,'• '+tp,N?58:42,'t-sm',13,'fill:var(--ink)');s+=w.svg;ny+=w.h+(N?6:10)});
    img.innerHTML=s;
    inote.innerHTML=`<div class="kicker">${F.k}</div><h4>${F.t}</h4><p>${F.txt}</p>`;
  }
  fb.addEventListener('click',e=>{const b=e.target.closest('[data-fr]');if(!b)return;fi=+b.dataset.fr;$$('[data-fr]',fb).forEach(x=>x.setAttribute('aria-pressed',x===b));
    if(stopC)stopC();const a=cam.slice(),z=FR[fi].c;stopC=animate(700,p=>{const q=ease(p);cam=a.map((v,i)=>lerp(v,z[i],q));drawImg()},()=>{stopC=null})});
  drawImg();
  const prevR=redraws.stigma;redraws.stigma=()=>{prevR&&prevR();drawImg()};
  const prevH=onHide.stigma;onHide.stigma=()=>{prevH&&prevH();if(stopC){stopC();stopC=null;cam=FR[fi].c.slice()}};
};
/* =============== 3.1 diet, activity & behaviour =============== */
