const MT_RESP_TXT={
 'STEP 1':'1961 adults without diabetes. Half of the people on semaglutide lost at least 15% of their starting weight; most on placebo lost less than 5%. <sup class="c" data-ref="Wilding2021STEP1" title="Source 600"><a href="/obesity/sources/#src-Wilding2021STEP1">600</a></sup>',
 'STEP 3':'611 adults, both arms with intensive behavioural therapy: 30 counselling visits and an 8-week low-calorie diet. The behavioural programme helped placebo, but the medicine still added a lot. <sup class="c" data-ref="Wadden2021STEP3" title="Source 576"><a href="/obesity/sources/#src-Wadden2021STEP3">576</a></sup>',
 'STEP 8':'338 adults, open-label: weekly semaglutide against daily liraglutide rather than placebo. <sup class="c" data-ref="Rubino2022STEP8" title="Source 479"><a href="/obesity/sources/#src-Rubino2022STEP8">479</a></sup>',
 'SURMOUNT-1':'2539 adults without diabetes. The abstract reports the 5% and 20% thresholds; 10 mg reached 20% in 50%. <sup class="c" data-ref="Jastreboff2022SURMOUNT1" title="Source 253"><a href="/obesity/sources/#src-Jastreboff2022SURMOUNT1">253</a></sup>',
 'OASIS 1':'667 adults without diabetes taking a 50 mg daily tablet, a higher dose than the 25 mg Wegovy tablet. <sup class="c" data-ref="Knop2023OASIS1,Wharton2025OASIS4" title="Source 292,594"><a href="/obesity/sources/#src-Knop2023OASIS1">292,594</a></sup>',
 'ATTAIN-1':'3127 adults without diabetes; the 36 mg trial dose corresponds to 17.2 mg on the Foundayo label. <sup class="c" data-ref="Wharton2025ATTAIN1,FDA-Foundayo" title="Source 143,593"><a href="/obesity/sources/#src-Wharton2025ATTAIN1">143,593</a></sup>',
 'SCALE':'3731 adults without diabetes, randomised 2:1 for 56 weeks. <sup class="c" data-ref="PiSunyer2015SCALE" title="Source 430"><a href="/obesity/sources/#src-PiSunyer2015SCALE">430</a></sup>'
};

inits.medtrials=()=>{
  const T=(x,y,txt,cls='t-xs',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${cls}"${st?` style="${st}"`:''}>${txt}</text>`;
  const famOn={};MT_FAM.forEach(f=>famOn[f.id]=!f.off);
  const colOf=id=>MT_FAM.find(f=>f.id===id).col;
  /* the schematic shape between published points: a saturating curve, k weeks to settle */
  function segF(a,b,w){const span=b[0]-a[0],u=clamp((w-a[0])/span),k=span>40?.28:.38,q=(1-Math.exp(-u/k))/(1-Math.exp(-1/k));return lerp(a[1],b[1],q)}
  function valAt(S,w){const P=S.P;if(w<=P[0][0])return P[0][1];for(let i=1;i<P.length;i++)if(w<=P[i][0])return segF(P[i-1],P[i],w);return P[P.length-1][1]}
  /* chips */
  const chips=$('#mtChips');
  chips.insertAdjacentHTML('beforeend',MT_FAM.map(f=>`<button class="btn" data-mf="${f.id}" aria-pressed="${!f.off}"><span class="mt-sw" style="background:${f.col}"></span>${f.n}</button>`).join(''));
  const svg=$('#mtSvg'),rg=$('#mtT');
  function draw(t){
    const N=vb(svg,'720 380','400 560');
    const L=N?{x:40,w:220,y:34,h:470,gx:268,ty:524,xl:546}:{x:56,w:420,y:26,h:300,gx:486,ty:346,xl:368};
    const p=phaseOf(MT_STEPS,t),P=MT_STEPS[p];
    const xmax=lerp(76,124,ease(ramp(t,.8,.85))),X=w=>L.x+L.w*w/xmax,Y=v=>L.y+L.h*(-v)/27;
    let s=`<rect x="${L.x}" y="${L.y}" width="${L.w}" height="${L.h}" style="fill:var(--field)"/>`;
    [0,-5,-10,-15,-20,-25].forEach(v=>{s+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/>`+T(L.x-6,Y(v)+3.5,(v?'−'+(-v):'0')+'%','t-xs t-end')});
    const tk=xmax>90?24:12;for(let w=0;w<=xmax;w+=tk){s+=`<line x1="${f1(X(w))}" x2="${f1(X(w))}" y1="${L.y+L.h}" y2="${L.y+L.h+4}" class="axis"/>`+T(X(w),L.ty,w,'t-xs t-mid')}
    s+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${L.y}" y2="${L.y}" class="axis"/>`+T(L.x+L.w,L.xl,'weeks since starting','t-xs t-end');
    s+=T(L.x,L.y-10,'mean % change in body weight','t-xs','fill:var(--ink);font-weight:700');
    /* stopping marks */
    const stopOn=ramp(t,.83,.88);
    if(stopOn>0){[[68,'STEP 1: all treatment stopped'],[36,'SURMOUNT-4: randomised']].forEach((m,i)=>{const x=X(m[0]);
      s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${L.y}" y2="${L.y+L.h}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3;opacity:${f1(stopOn)}"/>`;
      s+=`<g style="opacity:${f1(stopOn)}">${kitLabel(x+4,L.y+L.h*(N?.52:.5)+i*14,N?m[1].split(':')[0]:m[1],{halo:'var(--field)'})}</g>`})}
    const labs=[];
    MT_SER.forEach(S=>{if(!famOn[S.f])return;if(p<S.ph)return;
      let op=1;if(S.g==='main'&&p===4)op=.16;if(S.g==='main'&&p===5)op=0;if(S.g==='h2h'&&p===5)op=0;
      if(op<=0)return;
      const W=MT_WIN[S.ph],prog=ramp(t,W[0],W[1]),wEnd=S.P[S.P.length-1][0],wu=wEnd*prog;
      if(wu<=0)return;
      const col=colOf(S.f);let d='';const n=Math.max(2,Math.round(90*prog));
      for(let i=0;i<=n;i++){const w=wu*i/n;d+=(i?'L':'M')+f1(X(w))+' '+f1(Y(valAt(S,w)))}
      s+=`<path d="${d}" style="fill:none;stroke:${col};stroke-width:${S.dash?2.2:3};stroke-linejoin:round;opacity:${op}${S.dash?';stroke-dasharray:'+S.dash:''}"/>`;
      const v=valAt(S,wu),ex=X(wu),ey=Y(v);
      s+=`<circle cx="${f1(ex)}" cy="${f1(ey)}" r="${prog>=1?4:3}" style="fill:${col};stroke:var(--panel);stroke-width:1.5;opacity:${op}"/>`;
      S.P.slice(1,-1).forEach(q=>{if(wu>=q[0])s+=`<circle cx="${f1(X(q[0]))}" cy="${f1(Y(q[1]))}" r="3.5" style="fill:var(--panel);stroke:${col};stroke-width:1.6"/>`});
      if(op>.5)labs.push({x:ex,y:ey,ly:ey+3,col,txt:`${N?S.s:S.n} ${v<0?'−':'+'}${Math.abs(v).toFixed(1)}%`,fin:prog>=1})});
    /* labels in the right gutter, pushed apart */
    labs.sort((a,b)=>a.ly-b.ly);for(let i=1;i<labs.length;i++)if(labs[i].ly-labs[i-1].ly<12)labs[i].ly=labs[i-1].ly+12;
    const bot=L.y+L.h+6,over=labs.length?labs[labs.length-1].ly-bot:0;if(over>0)labs.forEach(l=>l.ly-=over);
    labs.forEach(l=>{s+=`<path d="M${f1(l.x+5)} ${f1(l.y)}L${f1(L.gx-4)} ${f1(l.ly-3)}" style="stroke:${l.col};stroke-width:1;opacity:.5"/>`+T(L.gx,l.ly,l.txt,'t-xs',`fill:var(--ink);font-weight:${l.fin?700:500}`)});
    svg.innerHTML=s;
    setSt(p);$('#mtNote').innerHTML=noteHTML(P);
  }
  const stop=playWire(rg,$('#mtPlay'),draw,24000,'Replay','medtrials');
  const setSt=stepWire($('#mtSteps'),MT_STEPS,rg,draw,stop);
  chips.addEventListener('click',e=>{const b=e.target.closest('[data-mf]');if(!b)return;const id=b.dataset.mf;famOn[id]=!famOn[id];b.setAttribute('aria-pressed',famOn[id]);draw(+rg.value)});
  draw(+rg.value);

  /* ---------- responders ---------- */
  const rsv=$('#mtResp'),tb=$('#mtTrialBtns'),hb=$('#mtThrBtns'),rnote=$('#mtRespNote');
  let ri=0,th=10,cur=[0,0],stopR=null;
  tb.insertAdjacentHTML('beforeend',MT_RESP.map((r,i)=>`<button class="btn" data-mr="${i}" aria-pressed="${i===0}">${r.n}</button>`).join(''));
  hb.insertAdjacentHTML('beforeend',[5,10,15,20].map(v=>`<button class="btn" data-mth="${v}" aria-pressed="${v===th}">${v}%</button>`).join(''));
  const target=()=>{const v=MT_RESP[ri].v[th];return v?v.slice():null};
  function drawR(){
    const N=vb(rsv,'720 300','400 560'),R=MT_RESP[ri],v=MT_RESP[ri].v[th];
    const sz=N?16:15,gp=4;
    const blocks=N?[[40,70],[40,340]]:[[90,62],[420,62]];
    let s=T(N?20:30,22,`${R.n} · ${R.wk} weeks · lost at least ${th}% of starting weight`,'t-sm','fill:var(--ink);font-weight:700');
    [[R.a,'var(--tx)',0],[R.b,'var(--figure-line)',1]].forEach((g,i)=>{const [bx,by]=blocks[i];
      const lbl=g[0].length>(N?44:46)?g[0].slice(0,g[0].lastIndexOf(' ',N?44:46))+'…':g[0];
      s+=T(bx,by-22,lbl,'t-xs','fill:var(--ink);font-weight:700');
      s+=T(bx,by-8,v?`${v[i]}% (shown as ${Math.round(v[i])} of 100)`:'not reported in the source used here','t-xs');
      const ia=iconArray(bx,by,{n:100,cols:10,size:sz,gap:gp,groups:[{k:v?Math.round(cur[i]):0,col:g[1]}],base:'var(--line)'});
      s+=ia.svg;
      s+=`<text x="${f1(bx+ia.w+14)}" y="${f1(by+ia.h/2+8)}" class="t-big" style="font-size:24px;fill:${i?'var(--muted)':'var(--tx)'};opacity:${v?1:0}">${Math.round(cur[i])}%</text>`});
    rsv.innerHTML=s;
    rnote.innerHTML=`<div class="kicker">${R.n}</div><h4>${v?`${v[0]}% vs ${v[1]}% lost at least ${th}%`:`The ${th}% threshold is not reported here`}</h4><p>${MT_RESP_TXT[R.n]}</p>${R.note?`<p>${R.note}</p>`:''}<p>Thresholds published for this trial: ${Object.keys(R.v).map(k=>'≥'+k+'%').join(', ')}. ${R.c}</p><div class="pt"><b>In plain words</b>Out of every 100 people on the medicine, this many reached the threshold; the rest lost less, and a few lost little or none.</div>`;
  }
  function go2(){const to=target()||[0,0],from=cur.slice();stopR&&stopR();stopR=animate(650,q=>{const e=ease(q);cur=from.map((x,i)=>lerp(x,to[i],e));drawR()},()=>{stopR=null;cur=to;drawR()})}
  tb.addEventListener('click',e=>{const b=e.target.closest('[data-mr]');if(!b)return;ri=+b.dataset.mr;$$('[data-mr]',tb).forEach(x=>x.setAttribute('aria-pressed',x===b));
    if(!MT_RESP[ri].v[th]){th=+Object.keys(MT_RESP[ri].v)[0];$$('[data-mth]',hb).forEach(x=>x.setAttribute('aria-pressed',+x.dataset.mth===th))}go2()});
  hb.addEventListener('click',e=>{const b=e.target.closest('[data-mth]');if(!b)return;th=+b.dataset.mth;$$('[data-mth]',hb).forEach(x=>x.setAttribute('aria-pressed',x===b));go2()});
  cur=target()||[0,0];drawR();
  const prev=redraws.medtrials;redraws.medtrials=()=>{prev&&prev();drawR()};
  const prevH=onHide.medtrials;onHide.medtrials=()=>{prevH&&prevH();stopR&&stopR();stopR=null;cur=target()||[0,0]};
};
/* =============== 3.4 other weight-loss medicines =============== */
/* Main player: a mechanism map. The brain (side view plus hypothalamus inset), a close-up panel and the gut sit side
   by side; each step is one medicine, and its fifth of the timeline animates that medicine's site of action. The band
   at the bottom builds the pivotal trial's published result. All drawings schematic; numbers from the research pass. */
const OM_STEPS=[
 {from:0,at:.17,k:'Gut lumen · capsule',t:'Orlistat',
  txt:'Orlistat reversibly blocks gastric and pancreatic lipases inside the gut, so undigested dietary fat (triglyceride) is not absorbed. <sup class="c" data-ref="FDA-Xenical" title="Source 151"><a href="/obesity/sources/#src-FDA-Xenical">151</a></sup> It is the one medicine here that does not act on the brain. In XENDOS, 4 years of orlistat with lifestyle change gave 5.8 kg loss vs 3.0 kg on placebo, and diabetes incidence of 6.2% vs 9.0%, a 37.3% risk reduction confined to people with impaired glucose tolerance. Only 52% on orlistat and 34% on placebo completed treatment. <sup class="c" data-ref="Torgerson2004XENDOS" title="Source 550"><a href="/obesity/sources/#src-Torgerson2004XENDOS">550</a></sup>',
  pt:'Orlistat stops some of the fat in food from being digested, so it passes out of the body in the stool instead of being absorbed. It works in the gut, not the brain.',
  hook:'Orlistat = gastric and pancreatic lipase inhibitor. XENDOS: diabetes risk down 37.3% over 4 years, only in impaired glucose tolerance. <sup class="c" data-ref="FDA-Xenical,Torgerson2004XENDOS" title="Source 151,550"><a href="/obesity/sources/#src-FDA-Xenical">151,550</a></sup>'},
 {from:.2,at:.37,k:'Hypothalamus · capsule',t:'Phentermine–topiramate',
  txt:'Phentermine is a sympathomimetic amine. Its weight effect is likely mediated by catecholamine release in the hypothalamus, which reduces appetite. The label says the mechanism of topiramate\'s weight effect is not known. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup> In CONQUER (2487 adults, 56 weeks), weight changed −9.8% on 15/92 mg and −7.8% on 7.5/46 mg vs −1.2% on placebo, as trial averages. <sup class="c" data-ref="Gadde2011CONQUER" title="Source 172"><a href="/obesity/sources/#src-Gadde2011CONQUER">172</a></sup>',
  pt:'Phentermine turns down appetite signals in the brain. Topiramate adds to the effect, though nobody is yet sure exactly how.',
  hook:'Qsymia is contraindicated in pregnancy (first-trimester topiramate raises the risk of oral clefts) and is dispensed only through a REMS programme. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup>'},
 {from:.4,at:.57,k:'Hypothalamus and reward circuit · tablet',t:'Naltrexone–bupropion',
  txt:'Naltrexone is an opioid antagonist; bupropion is a weak dopamine and noradrenaline reuptake inhibitor. Nonclinical studies suggest effects on the hypothalamus (appetite) and on the mesolimbic dopamine reward circuit. <sup class="c" data-ref="FDA-Contrave" title="Source 141"><a href="/obesity/sources/#src-FDA-Contrave">141</a></sup> In COR-I (1742 adults, 56 weeks), weight changed −6.1% vs −1.3%, and 48% vs 16% lost at least 5%; only half completed the trial. Nausea affected 29.8% vs 5.3%. <sup class="c" data-ref="Greenway2010CORI" title="Source 196"><a href="/obesity/sources/#src-Greenway2010CORI">196</a></sup>',
  pt:'This tablet pairs two older medicines. Together they seem to act on both hunger and the brain\'s reward system around food.',
  hook:'Contrave carries a boxed warning on suicidal thoughts and behaviours because it contains bupropion; it is contraindicated with seizure disorder, uncontrolled hypertension, bulimia or anorexia nervosa and chronic opioid use. <sup class="c" data-ref="FDA-Contrave" title="Source 141"><a href="/obesity/sources/#src-FDA-Contrave">141</a></sup>'},
 {from:.6,at:.77,k:'The MC4 receptor · injection',t:'Setmelanotide',
  txt:'Normally POMC neurons release alpha-MSH, which activates melanocortin-4 receptors (MC4R). <sup class="c" data-ref="Huszar1997" title="Source 240"><a href="/obesity/sources/#src-Huszar1997">240</a></sup> Setmelanotide is an MC4 receptor agonist with 20-fold less activity at MC3 and MC1 receptors; it may restore signalling in the leptin–melanocortin pathway when that pathway is under-activated. <sup class="c" data-ref="FDA-Imcivree" title="Source 144"><a href="/obesity/sources/#src-FDA-Imcivree">144</a></sup> In open-label phase 3 trials, 8 of 10 people with POMC deficiency and 5 of 11 with LEPR deficiency lost at least 10% at about 1 year. <sup class="c" data-ref="Clement2020" title="Source 87"><a href="/obesity/sources/#src-Clement2020">87</a></sup>',
  pt:'A few people have a rare gene change that breaks the brain\'s "I have had enough" signal, so they feel hungry all the time. Setmelanotide switches on the receptor at the end of that broken chain. It is not a treatment for common obesity.',
  hook:'Imcivree (as published): age 2 and over with Bardet-Biedl syndrome or genetically confirmed POMC, PCSK1 or LEPR deficiency; age 4 and over with acquired hypothalamic obesity. <sup class="c" data-ref="FDA-Imcivree" title="Source 144"><a href="/obesity/sources/#src-FDA-Imcivree">144</a></sup>'},
 {from:.8,at:.97,k:'Hypothalamus · daily injection',t:'Liraglutide',
  txt:'Liraglutide is a GLP-1 receptor agonist that resists breakdown by peptidases: its plasma half-life is 13 hours after injection, so it is given once daily, while native GLP-1 lasts only minutes. <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup> Native GLP-1 is made by intestinal L cells after meals. <sup class="c" data-ref="Holst2007" title="Source 231"><a href="/obesity/sources/#src-Holst2007">231</a></sup> In rodents, liraglutide entered the arcuate nucleus; GLP-1 excited POMC/CART neurons and indirectly inhibited NPY/AgRP neurons. <sup class="c" data-ref="Secher2014" title="Source 500"><a href="/obesity/sources/#src-Secher2014">500</a></sup> The Saxenda label reports SCALE as −7.4% vs −3.0% at 56 weeks. <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup>',
  pt:'Liraglutide copies a gut hormone that tells the brain food has arrived. It is a daily injection, the older relative of weekly semaglutide.',
  hook:'Head to head in STEP 8: semaglutide 2.4 mg weekly −15.8% vs liraglutide 3.0 mg daily −6.4% at 68 weeks. <sup class="c" data-ref="Rubino2022STEP8" title="Source 479"><a href="/obesity/sources/#src-Rubino2022STEP8">479</a></sup>'}
];
/* what the SVG writes for each medicine (no citations inside the SVG: they are in the caption and the note) */
const OM_SVGTXT=[
 {name:'Orlistat',cls:'lipase inhibitor · capsule with meals',site:'gut',close:'In the gut lumen',
  band:{lab:'XENDOS · 4 years · mean weight lost',a:5.8,b:3.0,max:10,fmt:v=>f1(v)+' kg',an:'orlistat',bn:'placebo'}},
 {name:'Phentermine–topiramate',cls:'sympathomimetic + anticonvulsant · capsule',site:'brain',close:'At a hypothalamic synapse',
  band:{lab:'CONQUER · 56 weeks · mean weight change',a:9.8,b:1.2,max:12,fmt:v=>'−'+f1(v)+'%',an:'15/92 mg',bn:'placebo'}},
 {name:'Naltrexone–bupropion',cls:'opioid antagonist + reuptake inhibitor · tablet',site:'brain',close:'At a synapse',
  band:{lab:'COR-I · 56 weeks · mean weight change',a:6.1,b:1.3,max:12,fmt:v=>'−'+f1(v)+'%',an:'32/360 mg',bn:'placebo'}},
 {name:'Setmelanotide',cls:'MC4R agonist · injection · rare genetic obesity',site:'brain',close:'On a PVN neuron',
  band:{lab:'Open-label trials · about 1 year · reached ≥10% loss',a:80,b:45,max:100,fmt:v=>Math.round(v)+'%',an:'POMC (8/10)',bn:'LEPR (5/11)',both:1}},
 {name:'Liraglutide 3.0 mg',cls:'GLP-1 receptor agonist · daily injection',site:'brain',close:'Level in the blood',
  band:{lab:'SCALE (label) · 56 weeks · mean weight change',a:7.4,b:3.0,max:12,fmt:v=>'−'+f1(v)+'%',an:'liraglutide',bn:'placebo'}}
];
const OM_LBL={closeup:'close-up',wall:'gut wall absorbs',splits:'lipase splits fat: absorbed',blocked:'lipase blocked: fat passes',
  colon:'unabsorbed fat → stool',lipase:'lipase',released:'catecholamines released',appetite:'appetite ↓',topi:'topiramate: weight',topi2:'mechanism not known',
  dat:'reuptake',bup:'bupropion: less reuptake',nal:'naltrexone: opioid block',opioid:'opioid receptor',reward:'reward circuit',
  nomsh:'POMC deficiency',msh:'α-MSH',mc4r:'MC4R',signal:'fullness signal',hours:'hours after a dose',level:'level',
  native:'native GLP-1: minutes',lira:'liraglutide',half:'half-life 13 h',lcells:'L cells make GLP-1',trial:'trial average'};

/* bars: the placebo-subtracted comparison. d,p = mean % change (drug, placebo); diff = the difference as published,
   otherwise d-p; r5 = % reaching ≥5% loss (drug, placebo). */
const OM_BARS=[
 {n:'Orlistat 120 mg',tr:'XENDOS · 4 years',kg:[5.8,3.0]},
 {n:'Phentermine–topiramate 7.5/46 mg',tr:'CONQUER · 56 weeks',d:7.8,p:1.2,r5:[62,21]},
 {n:'Phentermine–topiramate 15/92 mg',tr:'CONQUER · 56 weeks',d:9.8,p:1.2,r5:[70,21]},
 {n:'Naltrexone–bupropion 32/360 mg',tr:'COR-I · 56 weeks',d:6.1,p:1.3,r5:[48,16]},
 {n:'Liraglutide 3.0 mg',tr:'SCALE, label figures · 56 weeks',d:7.4,p:3.0,diff:4.5,r5:[62.3,34.4]},
 {n:'Semaglutide 2.4 mg (for reference)',tr:'STEP 1 · 68 weeks',d:14.9,p:2.4,diff:12.4,r5:[86.4,31.5],ref:1},
 {n:'Tirzepatide 15 mg (for reference)',tr:'SURMOUNT-1 · 72 weeks',d:20.9,p:3.1,r5:[91,35],ref:1}
];
const OM_VIEWS=[
 {id:'diff',n:'Placebo-subtracted',max:20,ticks:[0,5,10,15,20],unit:'percentage points more than placebo',
  note:'Each bar is the drug group\'s mean % weight loss minus the placebo group\'s, in the same trial. Where the trial or label states the difference, that figure is used (liraglutide 4.5, semaglutide 12.4); the others are subtracted here.'},
 {id:'raw',n:'Drug and placebo',max:22,ticks:[0,5,10,15,20],unit:'mean % weight lost',
  note:'Placebo groups also lost weight, because everyone in these trials had lifestyle support. That is why the placebo-subtracted view is the fairer measure of what the medicine adds.'},
 {id:'r5',n:'Reached ≥5% loss',max:100,ticks:[0,25,50,75,100],unit:'% of people reaching at least 5% loss',
  note:'The share of each group that lost at least 5% of body weight. A mean hides a wide spread: some people lose much more, some little.'}
];
const OM_BLBL={kg:'reported in kg only: 5.8 vs 3.0 kg',nr:'not reported in this source',drug:'drug',plc:'placebo',pts:' pts'};

/* the cautionary timeline: approvals, harms and safety trials */
const OM_HIST=[
 {y:1950,d:'1940s–50s',k:'appr',l:'Amphetamine-like appetite suppressants',
  txt:'After amphetamine and amphetamine-like anorectics were approved in the 1940s and 1950s, the FDA struggled to define their efficacy and safety. Limits on how long they could be used, and warnings about abuse and addiction, followed. <sup class="c" data-ref="Colman2005" title="Source 91"><a href="/obesity/sources/#src-Colman2005">91</a></sup>'},
 {y:1959.34,d:'May 1959',k:'appr',l:'Phentermine (Ionamin) approved',
  txt:'Phentermine resin complex (Ionamin) received its original US approval on 4 May 1959. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> Phentermine is still used today, and is one half of Qsymia. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup>'},
 {y:1996,d:'1996',k:'harm',l:'"Fen-phen": over 18 million prescriptions',
  txt:'In the mid-1990s, off-label "fen-phen" (fenfluramine plus phentermine) and the approval of dexfenfluramine led to widespread long-term use of appetite suppressants. <sup class="c" data-ref="Colman2005" title="Source 91"><a href="/obesity/sources/#src-Colman2005">91</a></sup> US prescriptions for fenfluramine and phentermine exceeded 18 million in 1996. <sup class="c" data-ref="Connolly1997" title="Source 92"><a href="/obesity/sources/#src-Connolly1997">92</a></sup>'},
 {y:1997.5,d:'1997',k:'harm',l:'Heart-valve disease; fenfluramines withdrawn',
  txt:'A 1997 report described valvular heart disease in 24 women (mean age 44) about 12 months after starting fenfluramine–phentermine: 8 had pulmonary hypertension and 5 needed heart surgery. <sup class="c" data-ref="Connolly1997" title="Source 92"><a href="/obesity/sources/#src-Connolly1997">92</a></sup> On 8 July 1997 the FDA issued a public health advisory, wrote to 700,000 practitioners and requested voluntary withdrawal of fenfluramine and dexfenfluramine. <sup class="c" data-ref="CDC1997Fenfluramine" title="Source 69"><a href="/obesity/sources/#src-CDC1997Fenfluramine">69</a></sup>'},
 {y:1997.9,d:'Nov 1997',k:'appr',l:'Sibutramine (Meridia) approved',
  txt:'Sibutramine (Meridia) received its original US approval on 22 November 1997. The product is now listed as "Discontinued". <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup>'},
 {y:1999.3,d:'Apr 1999',k:'appr',l:'Orlistat (Xenical) approved',
  txt:'Orlistat (Xenical) received its original US approval on 23 April 1999. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> A 60 mg version (Alli) is sold over the counter for overweight adults. <sup class="c" data-ref="FDA-Alli" title="Source 140"><a href="/obesity/sources/#src-FDA-Alli">140</a></sup>'},
 {y:2007,d:'2007',k:'harm',l:'Rimonabant: depression and anxiety',
  txt:'Rimonabant, a CB1 receptor blocker, was marketed in Europe but never approved in the USA. A 2007 meta-analysis of four trials (4105 people) found 4.7 kg more loss than placebo at 1 year, but people were 2.5 times more likely to stop because of depressive mood disorders and 3.0 times because of anxiety. The European Medicines Agency later withdrew it. <sup class="c" data-ref="Christensen2007,Sam2011" title="Source 77,489"><a href="/obesity/sources/#src-Christensen2007">77,489</a></sup>'},
 {y:2010,d:'2010',k:'harm',l:'SCOUT; sibutramine withdrawn in Europe',
  txt:'In SCOUT (9804 adults at high cardiovascular risk, mean 3.4 years), sibutramine raised the primary cardiovascular outcome to 11.4% vs 10.0% (HR 1.16), driven by non-fatal heart attack (HR 1.28) and stroke (HR 1.36), for only 1.7 kg extra weight loss after randomisation. <sup class="c" data-ref="James2010SCOUT" title="Source 251"><a href="/obesity/sources/#src-James2010SCOUT">251</a></sup> The European Medicines Agency withdrew sibutramine in 2010. <sup class="c" data-ref="Galhardo2010" title="Source 174"><a href="/obesity/sources/#src-Galhardo2010">174</a></sup>'},
 {y:2012.54,d:'Jul 2012',k:'appr',l:'Phentermine–topiramate (Qsymia) approved',
  txt:'Qsymia received its original US approval on 17 July 2012. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> Its label carries a pregnancy contraindication and a REMS programme because topiramate can cause oral clefts. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup>'},
 {y:2014.8,d:'2014',k:'appr',l:'Contrave and Saxenda approved',
  txt:'Naltrexone–bupropion (Contrave) was approved on 10 September 2014 and liraglutide 3.0 mg (Saxenda) on 23 December 2014. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup>'},
 {y:2016,d:'2016',k:'trial',l:'LIGHT: heart safety left uncertain',
  txt:'The naltrexone–bupropion cardiovascular outcome trial (8910 people) was stopped early after confidential interim data were released publicly. At 50% of events, major cardiovascular events were 2.0% vs 2.3% (HR 0.88), and cardiovascular safety "remains uncertain". <sup class="c" data-ref="Nissen2016LIGHT" title="Source 404"><a href="/obesity/sources/#src-Nissen2016LIGHT">404</a></sup>'},
 {y:2018,d:'2018',k:'trial',l:'CAMELLIA-TIMI 61: lorcaserin',
  txt:'Lorcaserin, a serotonin 2C agonist, was non-inferior to placebo on cardiovascular safety in about 12,000 people (major events 2.0% vs 2.1% per year, HR 0.99); 38.7% vs 17.4% lost at least 5% at 1 year. <sup class="c" data-ref="Bohula2018CAMELLIA" title="Source 49"><a href="/obesity/sources/#src-Bohula2018CAMELLIA">49</a></sup> The FDA later reviewed cancer risk in the same trial. <sup class="c" data-ref="Sharretts2020" title="Source 505"><a href="/obesity/sources/#src-Sharretts2020">505</a></sup>'},
 {y:2021.42,d:'Jun 2021',k:'appr',l:'Semaglutide 2.4 mg (Wegovy) approved',
  txt:'Wegovy injection received its original US approval on 4 June 2021, <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> and its label now also covers cardiovascular risk reduction in adults with established cardiovascular disease. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {y:2023.85,d:'Nov 2023',k:'appr',l:'Tirzepatide (Zepbound) approved',
  txt:'Zepbound received its original US approval on 8 November 2023. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> It is also indicated for moderate-to-severe obstructive sleep apnoea in adults with obesity. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>'},
 {y:2025.97,d:'Dec 2025',k:'appr',l:'Semaglutide tablets (Wegovy) approved',
  txt:'Wegovy tablets received their original US approval on 22 December 2025. <sup class="c" data-ref="FDA-DrugsAtFDA-AOM" title="Source 142"><a href="/obesity/sources/#src-FDA-DrugsAtFDA-AOM">142</a></sup> They are indicated for adults, not children. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {y:2026.57,d:'Jul 2026',k:'appr',l:'Orforglipron (Foundayo) label',
  txt:'Orforglipron, a small-molecule, non-peptide oral GLP-1 receptor agonist, is FDA-approved as Foundayo; it carries the same class boxed warning as the injectable incretin medicines. <sup class="c" data-ref="FDA-Foundayo" title="Source 143"><a href="/obesity/sources/#src-FDA-Foundayo">143</a></sup>'}
];
const OM_HKIND={appr:'approved',harm:'harm found',trial:'safety trial'};

inits.othermeds=()=>{
  const T=(x,y,s,c='t-sm',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${c}"${st?` style="${st}"`:''}>${s}</text>`;
  const frac=v=>v-Math.floor(v);
  /* ---- small glyphs ---- */
  const tg=(x,y,a=1)=>`<g style="opacity:${f1(a)}"><rect x="${f1(x-2)}" y="${f1(y-8)}" width="4" height="16" rx="1.5" style="fill:var(--fat-line)"/>`+
    [-6,0,6].map(d=>`<path d="M${f1(x+2)} ${f1(y+d)}q4 -3 8 0t8 0" style="fill:none;stroke:var(--fat);stroke-width:3;stroke-linecap:round"/>`).join('')+'</g>';
  const lipase=(x,y,r,blocked)=>{const a=.5;const m=`M${f1(x)} ${f1(y)}L${f1(x+r*Math.cos(-a))} ${f1(y+r*Math.sin(-a))}A${r} ${r} 0 1 0 ${f1(x+r*Math.cos(a))} ${f1(y+r*Math.sin(a))}Z`;
    return `<path d="${m}" style="fill:${blocked?'var(--device)':'var(--brand)'};opacity:${blocked?.55:.85};stroke:var(--panel);stroke-width:1.2"/>`};
  const ring=(x,y,u,col='var(--rx-drug)')=>{const q=frac(u*3);return `<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(7+q*12)}" style="fill:none;stroke:${col};stroke-width:2;opacity:${f1(1-q)}"/>`};
  const frame=(x,y,w,h,title)=>`<rect x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${f1(h)}" rx="12" style="fill:var(--field);stroke:var(--line);stroke-width:1.2"/>`+
    T(x+10,y+16,OM_LBL.closeup.toUpperCase(),'t-xs','letter-spacing:.08em')+T(x+10,y+30,title,'t-xs','fill:var(--ink);font-weight:700');
  /* ---- close-ups: each takes the panel box and the step's local progress u ---- */
  function cOrl(x,y,w,h,u){
    const wy=y+40,inh=ramp(u,.3,.5);let s='';
    s+=`<rect x="${f1(x+4)}" y="${f1(wy)}" width="${f1(w-8)}" height="16" style="fill:var(--gut);stroke:var(--gut-line);stroke-width:1"/>`;
    let v='';for(let i=0;i<=Math.floor((w-8)/12);i++){const vx=x+4+i*12;v+=`<path d="M${f1(vx)} ${f1(wy+16)}q6 9 12 0" style="fill:var(--gut);stroke:var(--gut-line);stroke-width:1"/>`}s+=v;
    s+=T(x+w/2,wy+34,OM_LBL.wall,'t-xs t-mid');
    const L=[[x+w*.32,y+h*.6],[x+w*.68,y+h*.74]];
    L.forEach((p,i)=>{s+=lipase(p[0],p[1],10,inh>.98)});
    s+=T(L[0][0],L[0][1]+22,OM_LBL.lipase,'t-xs t-mid');
    /* the drug docks on each lipase */
    L.forEach((p,i)=>{const q=ramp(u,.28+i*.06,.48+i*.04);if(q<=0)return;const sx=x+16+i*30,sy=wy+24;
      s+=hormoneDot(lerp(sx,p[0]+9,ease(q)),lerp(sy,p[1],ease(q)),'drug',{r:4})});
    /* triglycerides drift left to right */
    for(let k=0;k<5;k++){const p=frac(u*1.5+k/5),mx=x+12+p*(w-24),my=y+h*.5+(k%3)*14+4;
      const lx=L[k%2][0];
      if(inh<.5&&mx>lx){const q=clamp((mx-lx)/50);
        [-1,0,1].forEach(j=>{s+=`<circle cx="${f1(mx+j*7)}" cy="${f1(lerp(my,wy+20,q))}" r="2.6" style="fill:var(--fat-line);opacity:${f1(1-q*.85)}"/>`})}
      else s+=tg(mx,my,mx>x+w-26?.4:1)}
    s+=T(x+w/2,y+h-12,inh<.5?OM_LBL.splits:OM_LBL.blocked,'t-xs t-mid','fill:var(--ink);font-weight:700');
    return s}
  function synapse(x,y,w,h){const cx=x+w/2;
    return `<path d="M${f1(cx-58)} ${f1(y+44)}Q${f1(cx-62)} ${f1(y+104)} ${f1(cx)} ${f1(y+106)}Q${f1(cx+62)} ${f1(y+104)} ${f1(cx+58)} ${f1(y+44)}" style="fill:var(--brain);stroke:var(--brain-line);stroke-width:1.4"/>`+
      `<path d="M${f1(cx-62)} ${f1(y+150)}Q${f1(cx)} ${f1(y+136)} ${f1(cx+62)} ${f1(y+150)}L${f1(cx+62)} ${f1(y+162)}L${f1(cx-62)} ${f1(y+162)}Z" style="fill:var(--brain);stroke:var(--brain-line);stroke-width:1.4"/>`+
      [-30,-10,10,30].map(d=>`<path d="M${f1(cx+d-5)} ${f1(y+143+Math.abs(d)*.06)}q5 6 10 0" style="fill:none;stroke:var(--brain-line);stroke-width:2"/>`).join('')}
  function cPhen(x,y,w,h,u){const cx=x+w/2,rel=ramp(u,.15,.75);let s=synapse(x,y,w,h);
    s+=hormoneDot(cx-30,y+62,'drug',{r:4,op:ramp(u,0,.12)});
    const rr=rng(9);
    for(let i=0;i<4;i++){const vx=cx-24+i*16,vy=lerp(y+70,y+96,ramp(rel,i*.12,i*.12+.4));s+=`<circle cx="${f1(vx)}" cy="${f1(vy)}" r="6" style="fill:var(--panel);stroke:var(--brain-line);stroke-width:1"/><circle cx="${f1(vx)}" cy="${f1(vy)}" r="2" style="fill:var(--ink);opacity:.6"/>`}
    const n=Math.round(rel*22);for(let i=0;i<n;i++){const dx=(rr()-.5)*96,dy=rr()*26;s+=`<circle cx="${f1(cx+dx)}" cy="${f1(y+112+dy)}" r="2.2" style="fill:var(--ink);opacity:.7"/>`}
    s+=T(cx,y+180,OM_LBL.released,'t-xs t-mid','fill:var(--ink);font-weight:700');
    s+=`<rect x="${f1(x+10)}" y="${f1(y+h-34)}" width="${f1(w-20)}" height="26" rx="6" style="fill:none;stroke:var(--muted);stroke-dasharray:3 3;opacity:${f1(ramp(u,.5,.7))}"/>`;
    s+=`<g style="opacity:${f1(ramp(u,.5,.7))}">`+T(cx,y+h-23,OM_LBL.topi,'t-xs t-mid')+T(cx,y+h-12,OM_LBL.topi2,'t-xs t-mid')+'</g>';
    return s}
  function cNB(x,y,w,h,u){const cx=x+w/2,b=ramp(u,.2,.45),nb=ramp(u,.5,.7);let s=synapse(x,y,w,h);
    /* dopamine transporter on the left of the terminal */
    const tx=cx-50,ty=y+92;
    s+=`<rect x="${f1(tx-6)}" y="${f1(ty-10)}" width="12" height="20" rx="4" style="fill:var(--panel);stroke:var(--brain-line);stroke-width:1.4"/>`;
    if(b<1)s+=`<path d="M${f1(tx+2)} ${f1(ty+28)}L${f1(tx+2)} ${f1(ty+12)}" class="arrow" style="opacity:${f1(1-b)}" marker-end="url(#omAr)"/>`;
    if(b>0)s+=hormoneDot(lerp(tx-26,tx,ease(b)),ty,'drug',{r:4});
    const rr=rng(4),n=Math.round(8+b*14);for(let i=0;i<n;i++){const dx=(rr()-.5)*96,dy=rr()*24;s+=`<circle cx="${f1(cx+dx)}" cy="${f1(y+113+dy)}" r="2.2" style="fill:var(--ink);opacity:.7"/>`}
    s+=T(x+8,y+62,OM_LBL.dat,'t-xs');
    /* opioid receptor on the right, capped by naltrexone */
    const ox=cx+46,oy=y+146;
    s+=`<path d="M${f1(ox)} ${f1(oy)}L${f1(ox)} ${f1(oy-10)}M${f1(ox)} ${f1(oy-10)}L${f1(ox-6)} ${f1(oy-17)}M${f1(ox)} ${f1(oy-10)}L${f1(ox+6)} ${f1(oy-17)}" style="stroke:var(--brain-line);stroke-width:2.4;stroke-linecap:round"/>`;
    if(nb>0)s+=`<g style="opacity:${f1(nb)}">`+hormoneDot(ox,lerp(oy-40,oy-21,ease(nb)),'drug',{r:4})+'</g>';
    s+=T(cx,y+182,OM_LBL.bup,'t-xs t-mid','fill:var(--ink);font-weight:700;opacity:'+f1(.3+.7*b));
    s+=T(cx,y+198,OM_LBL.nal,'t-xs t-mid','fill:var(--ink);font-weight:700;opacity:'+f1(.3+.7*nb));
    return s}
  function cSet(x,y,w,h,u){const cx=x+w/2,my=y+h*.56,dk=ramp(u,.25,.55),act=ramp(u,.5,.8);let s='';
    s+=`<rect x="${f1(x+4)}" y="${f1(my-6)}" width="${f1(w-8)}" height="12" style="fill:var(--brain);stroke:var(--brain-line);stroke-width:1"/>`;
    for(let i=0;i<7;i++){const hx=cx-21+i*7;s+=`<rect x="${f1(hx-2.6)}" y="${f1(my-14)}" width="5.2" height="28" rx="2.6" style="fill:${act>0?'var(--pomc)':'var(--panel)'};fill-opacity:${f1(.25+.75*act)};stroke:var(--brain-line);stroke-width:1"/>`}
    s+=T(cx+30,my-18,OM_LBL.mc4r,'t-xs','fill:var(--ink);font-weight:700');
    /* the missing natural ligand */
    s+=`<circle cx="${f1(x+30)}" cy="${f1(y+58)}" r="8" style="fill:none;stroke:var(--muted);stroke-dasharray:3 2"/><path d="M${f1(x+25)} ${f1(y+53)}l10 10m0 -10l-10 10" style="stroke:var(--bad);stroke-width:1.6"/>`;
    s+=T(x+42,y+56,'no '+OM_LBL.msh,'t-xs')+T(x+42,y+70,OM_LBL.nomsh,'t-xs');
    s+=hormoneDot(lerp(x+w-30,cx,ease(dk)),lerp(y+52,my-22,ease(dk)),'drug',{r:5});
    if(act>0){for(let i=0;i<3;i++){const q=frac(u*2+i/3);s+=`<circle cx="${f1(cx)}" cy="${f1(lerp(my+16,y+h-34,q))}" r="3" style="fill:var(--pomc);opacity:${f1(act*(1-q))}"/>`}
      s+=`<path d="M${f1(cx)} ${f1(my+16)}L${f1(cx)} ${f1(y+h-30)}" class="arrow" style="stroke:var(--pomc);opacity:${f1(act)}" marker-end="url(#omArP)"/>`}
    s+=T(cx,y+h-12,OM_LBL.signal+(act>.5?' ↑':''),'t-xs t-mid','fill:var(--ink);font-weight:700;opacity:'+f1(.35+.65*act));
    return s}
  function cLir(x,y,w,h,u){const px=x+30,py=y+50,pw=w-44,ph=h-112,X=hh=>px+pw*hh/24,Y=v=>py+ph-ph*v,up=u*24;let s='';
    s+=`<rect x="${f1(px)}" y="${f1(py)}" width="${f1(pw)}" height="${f1(ph)}" style="fill:var(--panel)"/>`;
    [0,12,24].forEach(hh=>{s+=T(X(hh),py+ph+12,hh,'t-xs t-mid')});
    s+=T(px+pw,py+ph+24,OM_LBL.hours,'t-xs t-end')+T(px-4,py-6,OM_LBL.level,'t-xs');
    s+=`<line x1="${f1(px)}" y1="${f1(py+ph)}" x2="${f1(px+pw)}" y2="${f1(py+ph)}" class="axis"/><line x1="${f1(px)}" y1="${f1(py)}" x2="${f1(px)}" y2="${f1(py+ph)}" class="axis"/>`;
    /* native GLP-1: gone within minutes */
    const nat=clamp(1-up*8);s+=`<path d="M${f1(X(0))} ${f1(Y(1))}L${f1(X(Math.min(up,.15)))} ${f1(Y(nat))}" style="fill:none;stroke:var(--glp1);stroke-width:2.4"/>`;
    /* liraglutide: schematic decay from a peak with a 13 h half-life */
    const P=[];for(let i=0;i<=48;i++){const hh=i/2;if(hh>up)break;P.push([X(hh),Y(Math.pow(.5,hh/13))])}
    if(P.length>1)s+=`<path d="${ptsD(P)}" style="fill:none;stroke:var(--rx-drug);stroke-width:2.6"/>`;
    if(up>=13)s+=`<path d="M${f1(X(13))} ${f1(py+ph)}L${f1(X(13))} ${f1(Y(.5))}L${f1(px)} ${f1(Y(.5))}" style="fill:none;stroke:var(--muted);stroke-dasharray:3 3"/>`+T(X(13)+3,Y(.5)-5,OM_LBL.half,'t-xs','fill:var(--ink);font-weight:700');
    s+=T(px+4,py+ph+38,OM_LBL.native,'t-xs','fill:var(--ink)');
    s+=`<rect x="${f1(px-10)}" y="${f1(py+ph+32)}" width="10" height="3" style="fill:var(--glp1)"/><rect x="${f1(px-10)}" y="${f1(py+ph+46)}" width="10" height="3" style="fill:var(--rx-drug)"/>`+T(px+4,py+ph+51,OM_LBL.lira,'t-xs','fill:var(--ink)');
    return s}
  const CLOSE=[cOrl,cPhen,cNB,cSet,cLir];

  /* ---- the mechanism player ---- */
  const svg=$('#omSvg'),rg=$('#omT'),pb=$('#omPlay'),noteEl=$('#omNote'),stepsEl=$('#omSteps');
  let setActive=()=>{};
  function draw(t){
    const N=vb(svg,'720 380','400 560');
    const i=Math.min(4,Math.floor(t/.2)),u=clamp((t-i*.2)/.2),D=OM_SVGTXT[i];
    const L=N?{hx:14,bx:6,by:72,bs:1,cx:8,cy:236,cw:190,ch:226,gx:212,gy:234,gs:.86,band:488,bw:376}
             :{hx:16,bx:6,by:70,bs:1.08,cx:300,cy:62,cw:180,ch:228,gx:500,gy:50,gs:.86,band:306,bw:688};
    let s=`<defs>${marker('omAr','var(--muted)',6)}${marker('omArP','var(--pomc)',6)}</defs>`;
    s+=T(L.hx,28,D.name,'t-big','font-size:20px')+T(L.hx,46,D.cls,'t-sm');
    /* brain */
    let pomc=.25,agrp=.25,mc4r=.25;
    if(i===3){pomc=0;agrp=.3;mc4r=.1+.9*ramp(u,.5,.8)}
    if(i===4){const q=ramp(u,.3,.7);pomc=.2+.8*q;agrp=.7-.55*q;mc4r=.2+.6*q}
    const br=brainHypothalamus(L.bx,L.by,L.bs,{pomc,agrp,mc4r,labels:true});
    s+=`<g style="opacity:${i===0?.35:1}">`+br.svg;
    const BT=p=>[L.bx+p[0]*L.bs,L.by+p[1]*L.bs];
    if(i===2){const a=BT([80,94]),c=BT([58,58]),b=BT([40,66]),g=ramp(u,.3,.8);
      s+=`<path d="M${f1(a[0])} ${f1(a[1])}Q${f1(c[0])} ${f1(c[1])} ${f1(b[0])} ${f1(b[1])}" style="fill:none;stroke:var(--rx-drug);stroke-width:${f1(2+3*g)};stroke-linecap:round;opacity:${f1(.35+.65*g)}"/>`;
      s+=`<circle cx="${f1(a[0])}" cy="${f1(a[1])}" r="4" style="fill:var(--rx-drug)"/><circle cx="${f1(b[0])}" cy="${f1(b[1])}" r="4" style="fill:var(--rx-drug)"/>`+kitLabel(b[0]+2,b[1]-30*L.bs,OM_LBL.reward,{})}
    if(i>0&&i<3)s+=ring(br.at.hypo[0],br.at.hypo[1],u);
    if(i===1&&u>.5)s+=kitLabel(br.at.hypo[0],br.at.hypo[1]+30*L.bs,OM_LBL.appetite,{a:'m'});
    if(i===3)s+=ring(br.at.pvn[0],br.at.pvn[1],u,'var(--pomc)');
    if(i===4)s+=ring(br.at.pomc[0],br.at.pomc[1],u,'var(--pomc)');
    s+='</g>';
    /* gut */
    const gt=gutTract(L.gx,L.gy,L.gs,{labels:true,dim:i===0?0:.75,fill:0,glow:{ileum:i===4?.4+.6*Math.abs(Math.sin(u*Math.PI*2)):0},food:i===0?frac(u*1.15):null});
    s+=gt.svg;
    if(i===0){const fp=gt.route(frac(u*1.15));if(u>.5)s+=`<circle cx="${f1(fp[0])}" cy="${f1(fp[1])}" r="7" style="fill:var(--fat);stroke:var(--fat-line);stroke-width:1.4;opacity:.9"/>`;
      s+=ring(gt.at.jejunum[0],gt.at.jejunum[1],u,'var(--brand)');
      if(u>.55)s+=kitLabel(L.gx+100*L.gs,L.gy+270*L.gs+(N?14:10),OM_LBL.colon,{a:'m'})}
    if(i===4)s+=kitLabel(gt.at.ileum[0],gt.at.ileum[1]+22,OM_LBL.lcells,{a:'m'});
    /* close-up panel and its leader line */
    s+=frame(L.cx,L.cy,L.cw,L.ch,D.close)+CLOSE[i](L.cx,L.cy,L.cw,L.ch,u);
    const tgt=i===0?gt.at.jejunum:(i===3?br.at.pvn:i===4?br.at.pomc:br.at.hypo);
    const from=N?(i===0?[L.cx+L.cw,L.cy+60]:[L.cx+40,L.cy]):(i===0?[L.cx+L.cw,L.cy+50]:[L.cx,L.cy+50]);
    s+=`<path d="M${f1(from[0])} ${f1(from[1])}L${f1(tgt[0])} ${f1(tgt[1])}" style="fill:none;stroke:var(--muted);stroke-width:1.2;stroke-dasharray:4 4;opacity:.8"/>`;
    /* the band: the trial result builds */
    const B=D.band,g=ease(ramp(u,.4,.8)),y0=L.band,bx=N?118:200,bw=L.bw-(N?110:200);
    s+=`<line x1="${L.hx}" x2="${f1(L.hx+L.bw-6)}" y1="${y0}" y2="${y0}" class="axis"/>`;
    s+=T(L.hx,y0+18,B.lab,'t-xs','fill:var(--ink);font-weight:700');
    [[B.a,B.an,'var(--rx-drug)'],[B.b,B.bn,B.both?'var(--rx-drug)':'var(--figure)']].forEach((r,k)=>{const yy=y0+28+k*22,v=r[0]*g,ww=bw*v/B.max;
      s+=T(bx-8,yy+10,r[1],'t-xs t-end')+`<rect x="${bx}" y="${yy}" width="${f1(bw)}" height="13" rx="3" style="fill:var(--panel-2)"/><rect x="${bx}" y="${yy}" width="${f1(Math.max(0,ww))}" height="13" rx="3" style="fill:${r[2]};opacity:${B.both&&k?.6:1}"/>`;
      if(g>.05)s+=T(bx+ww+6,yy+10,B.fmt(v),'t-xs','fill:var(--ink);font-weight:700')});
    if(!N)s+=T(L.hx+L.bw-6,y0+18,OM_LBL.trial,'t-xs t-end');
    svg.innerHTML=s;
    const p=phaseOf(OM_STEPS,t);noteEl.innerHTML=noteHTML(OM_STEPS[p]);setActive(p);
  }
  const stop=playWire(rg,pb,draw,16000,'Replay','othermeds');
  setActive=stepWire(stepsEl,OM_STEPS,rg,draw,stop);
  /* a medicine's step button plays its own fifth of the timeline, so the site of action animates */
  let seg=null;const segStop=()=>{if(seg){seg();seg=null}};
  stepsEl.addEventListener('click',e=>{const b=e.target.closest('[data-st]');if(!b)return;segStop();const k=+b.dataset.st,a=OM_STEPS[k].from+.005,z=OM_STEPS[k].at;
    if(RM){rg.value=z;draw(z);return}seg=animate(2200,q=>{const v=lerp(a,z,q);rg.value=v;draw(v)},()=>{seg=null})});
  rg.addEventListener('input',segStop);pb.addEventListener('click',segStop);
  {const prev=onHide.othermeds;onHide.othermeds=()=>{prev&&prev();segStop()}}
  draw(+rg.value);

  /* ---- the weight comparison ---- */
  const bsvg=$('#omBars'),bbtn=$('#omBarBtns'),bnote=$('#omBarNote');
  let view=0,shown=OM_BARS.map(()=>[0,0]),stopB=null;
  const target=v=>OM_BARS.map(r=>{const V=OM_VIEWS[v].id;if(V==='diff')return r.d==null?[0,0]:[r.diff!=null?r.diff:+(r.d-r.p).toFixed(1),0];
    if(V==='raw')return r.d==null?[0,0]:[r.d,r.p];return r.r5?[r.r5[0],r.r5[1]]:[0,0]});
  function drawBars(vals){
    const N=vb(bsvg,'720 360','400 520'),V=OM_VIEWS[view];
    const L=N?{lx:12,bx:12,bw:330,top:34,rh:68,lab:0}:{lx:12,bx:262,bw:400,top:34,rh:44,lab:1};
    const X=v=>L.bx+L.bw*v/V.max,TV=target(view);let s='';
    s+=T(L.bx,20,V.unit,'t-xs','fill:var(--ink);font-weight:700');
    const gy0=L.top,gy1=L.top+OM_BARS.length*L.rh;
    V.ticks.forEach(k=>{s+=`<line x1="${f1(X(k))}" x2="${f1(X(k))}" y1="${gy0}" y2="${gy1}" class="grid"/>`+T(X(k),gy1+14,k,'t-xs t-mid')});
    OM_BARS.forEach((r,i)=>{const y=L.top+i*L.rh,two=V.id==='raw',by=L.lab?y+8:y+30,bh=two?11:16;
      if(r.ref)s+=`<rect x="0" y="${f1(y+1)}" width="${N?400:720}" height="${f1(L.rh-2)}" style="fill:var(--panel-2);opacity:.6"/>`;
      s+=T(L.lx,L.lab?y+18:y+14,r.n,'t-xs','fill:var(--ink);font-weight:700')+T(L.lx,L.lab?y+31:y+26,r.tr,'t-xs');
      const miss=r.d==null&&V.id!=='r5'?OM_BLBL.kg:(V.id==='r5'&&!r.r5?OM_BLBL.nr:'');
      if(miss){s+=T(L.bx,by+12,miss,'t-xs','font-style:italic');return}
      const v=vals[i],tv=TV[i];
      s+=`<rect x="${L.bx}" y="${f1(by)}" width="${f1(Math.max(0,X(v[0])-L.bx))}" height="${bh}" rx="3" style="fill:var(--rx-drug);opacity:${r.ref?.55:1}"/>`;
      s+=T(X(v[0])+5,by+bh-2,V.id==='diff'?f1(tv[0])+OM_BLBL.pts:f1(tv[0])+'%','t-xs','fill:var(--ink);font-weight:700');
      if(two||V.id==='r5'){const y2=by+bh+3;s+=`<rect x="${L.bx}" y="${f1(y2)}" width="${f1(Math.max(0,X(v[1])-L.bx))}" height="${two?11:9}" rx="3" style="fill:var(--figure)"/>`+T(X(v[1])+5,y2+(two?9:8),f1(tv[1])+'%','t-xs')}
    });
    bsvg.innerHTML=s;
  }
  function setView(v){view=v;$$('button',bbtn).forEach((b,k)=>b.setAttribute('aria-pressed',k===v));
    bnote.innerHTML=`<div class="kicker">${OM_VIEWS[v].n}</div><p>${OM_VIEWS[v].note}</p>`;
    const from=shown.map(a=>a.slice()),to=target(v);if(stopB)stopB();
    stopB=animate(650,p=>{const e=ease(p);shown=from.map((a,i)=>[lerp(a[0],to[i][0],e),lerp(a[1],to[i][1],e)]);drawBars(shown)},()=>{stopB=null})}
  bbtn.innerHTML=OM_VIEWS.map((v,i)=>`<button class="btn" aria-pressed="false" data-v="${i}">${v.n}</button>`).join('');
  bbtn.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(b)setView(+b.dataset.v)});
  shown=target(0);setView(0);drawBars(shown);
  {const prev=redraws.othermeds;redraws.othermeds=()=>{prev&&prev();drawBars(shown)}}

  /* ---- the cautionary timeline ---- */
  const hsvg=$('#omHist'),hr=$('#omHistT'),hp=$('#omHistPlay'),hnote=$('#omHistNote');
  const Y0=1945,Y1=2027,yOf=t=>t<=.2?lerp(Y0,1995,t/.2):lerp(1995,Y1,(t-.2)/.8);
  function drawHist(t){
    const N=vb(hsvg,'720 470','400 500'),yr=yOf(t),n=OM_HIST.length;
    const L=N?{dx:58,lx:76,tx:94,top:58,rh:27.5,dt:'t-xs'}:{dx:96,lx:116,tx:138,top:52,rh:25.5,dt:'t-sm'},fs=N?'10.5px':'13.5px';
    let s='',last=-1;OM_HIST.forEach((e,i)=>{if(yr>=e.y)last=i});
    s+=T(N?388:704,30,Math.min(2026,Math.floor(yr)),'t-big t-end','font-size:26px');
    const rowY=i=>L.top+i*L.rh;
    /* the line fills down to "now", between the last event and the next */
    const nxt=OM_HIST[last+1],cur=OM_HIST[last];let fy=rowY(0)-14;
    if(last>=0){fy=rowY(last);if(nxt)fy+=L.rh*clamp((yr-cur.y)/(nxt.y-cur.y))}
    s+=`<line x1="${L.lx}" x2="${L.lx}" y1="${f1(rowY(0)-14)}" y2="${f1(rowY(n-1))}" style="stroke:var(--line);stroke-width:3"/>`;
    s+=`<line x1="${L.lx}" x2="${L.lx}" y1="${f1(rowY(0)-14)}" y2="${f1(fy)}" style="stroke:var(--tx);stroke-width:3"/>`;
    s+=`<circle cx="${L.lx}" cy="${f1(fy)}" r="4" style="fill:var(--tx)"/>`;
    OM_HIST.forEach((e,i)=>{const y=rowY(i),on=i<=last,op=on?1:.28,col=e.k==='appr'?'var(--good)':e.k==='harm'?'var(--bad)':'var(--warn)';
      s+=`<g style="opacity:${op}">`+T(L.dx,y+4,e.d,L.dt+' t-end');
      if(e.k==='appr')s+=`<circle cx="${L.lx}" cy="${y}" r="6" style="fill:${col};stroke:var(--panel);stroke-width:2"/>`;
      else if(e.k==='harm')s+=`<circle cx="${L.lx}" cy="${y}" r="7" style="fill:var(--panel);stroke:${col};stroke-width:2"/><path d="M${L.lx-3.5} ${y-3.5}l7 7m0 -7l-7 7" style="stroke:${col};stroke-width:2"/>`;
      else s+=`<path d="M${L.lx} ${y-7}l7 7l-7 7l-7 -7z" style="fill:${col};stroke:var(--panel);stroke-width:2"/>`;
      s+=T(L.tx,y+4,e.l,i===last?'t-lbl':'t-sm','font-size:'+fs+(i===last?'':';fill:var(--ink)'));
      if(!N)s+=T(704,y+4,OM_HKIND[e.k],'t-xs t-end');
      s+='</g>'});
    hsvg.innerHTML=s;
    const e=OM_HIST[Math.max(0,last)];
    hnote.innerHTML=`<div class="kicker">${e.d} · ${OM_HKIND[e.k]}</div><h4>${e.l}</h4><p>${e.txt}</p>`;
  }
  playWire(hr,hp,drawHist,14000,'Replay','othermeds');
  drawHist(+hr.value);
};
/* =============== 3.5 side effects, safety & stopping =============== */
/* Main player: 120 weeks of one trial group. The Wegovy label's dose steps run along the bottom, a schematic curve of
   new stomach and gut symptoms peaks during the escalation and settles, and the weight-change line is drawn through the
   STEP 1 extension's published points (week 0, 68 and 120; the shape between them is schematic). A spotlight panel on
   the right changes with each step: GI rates, gallbladder, pancreatitis, the thyroid boxed warning, anaesthesia, lean
   mass, stopping. Numbers from the research pass; the curve shapes are illustrative. */
const SE_WK=120,SE_STOPW=68;
const SE_STEPS=[
 {from:0,at:.1,k:'Weeks 0–20 · the dose steps',t:'Stomach and gut effects',
  txt:'In the Wegovy label\'s pooled adult weight trials (2116 people on semaglutide 2.4 mg, 1261 on placebo), nausea affected 44% vs 16%, diarrhoea 30% vs 16%, vomiting 24% vs 6% and constipation 24% vs 11%; 6.8% vs 3.2% stopped because of adverse reactions. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> Across STEP 1–3, GI events were most frequent during or shortly after dose escalation; 99.5% were non-serious and 98.1% mild to moderate. Weight loss was similar in people with and without GI events, so it is not simply the result of feeling sick. <sup class="c" data-ref="Wharton2022GItolerability" title="Source 591"><a href="/obesity/sources/#src-Wharton2022GItolerability">591</a></sup>',
  pt:'Feeling sick, loose stools or constipation are common, mostly early on and when the dose goes up, and they usually settle. <sup class="c" data-ref="Wharton2022GItolerability" title="Source 591"><a href="/obesity/sources/#src-Wharton2022GItolerability">591</a></sup>',
  hook:'Wegovy label: nausea 44% vs 16% on placebo; most GI events come during or just after dose escalation. <sup class="c" data-ref="FDA-Wegovy,Wharton2022GItolerability" title="Source 150,591"><a href="/obesity/sources/#src-FDA-Wegovy">150,591</a></sup>'},
 {from:.18,at:.25,k:'Any time on treatment',t:'Gallbladder',
  txt:'In the Wegovy adult trials, gallstones (cholelithiasis) occurred in 1.6% on the injection vs 0.7% on placebo, and cholecystitis in 0.6% vs 0.2%. In adolescents, gallstones occurred in 3.8% vs 0%, and the label says acute gallbladder disease was more common than placebo even after accounting for the degree of weight loss. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> A meta-analysis of 76 trials (103,371 patients) linked GLP-1 receptor agonists to more gallbladder or biliary disease (RR 1.37), and more so in weight-loss trials (RR 2.29), at higher doses and with longer use. <sup class="c" data-ref="He2022Gallbladder" title="Source 221"><a href="/obesity/sources/#src-He2022Gallbladder">221</a></sup>',
  pt:'Gallstones are a little more common on these medicines, especially at the higher doses used for weight loss. <sup class="c" data-ref="He2022Gallbladder" title="Source 221"><a href="/obesity/sources/#src-He2022Gallbladder">221</a></sup>',
  hook:'GLP-1 receptor agonists and gallbladder disease: RR 2.29 in weight-loss trials. <sup class="c" data-ref="He2022Gallbladder" title="Source 221"><a href="/obesity/sources/#src-He2022Gallbladder">221</a></sup>'},
 {from:.3,at:.35,k:'Rare',t:'Pancreatitis',
  txt:'Adjudicated acute pancreatitis was uncommon: 4 cases on Wegovy (0.2 per 100 patient-years) vs 1 on placebo, and 9 of 3291 (0.3%) on Saxenda. The labels say to stop the drug if pancreatitis is suspected. <sup class="c" data-ref="FDA-Wegovy,FDA-Saxenda" title="Source 148,150"><a href="/obesity/sources/#src-FDA-Wegovy">148,150</a></sup> In the Zepbound sleep apnoea studies the rate was 0.84 patients per 100 years vs 0 on placebo. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup> A meta-analysis of 21 cardiovascular outcome trials (99,599 patients) found no difference in pancreatitis. <sup class="c" data-ref="Galli2025" title="Source 175"><a href="/obesity/sources/#src-Galli2025">175</a></sup>',
  pt:'Inflammation of the pancreas is rare. Severe stomach pain that does not go away, sometimes spreading to the back, needs urgent medical review. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>',
  hook:'Suspected pancreatitis: the labels say stop the drug. <sup class="c" data-ref="FDA-Wegovy,FDA-Saxenda" title="Source 148,150"><a href="/obesity/sources/#src-FDA-Wegovy">148,150</a></sup>'},
 {from:.4,at:.45,k:'Boxed warning',t:'Thyroid C-cell tumours',
  txt:'Wegovy, Zepbound and Saxenda carry a boxed warning: semaglutide, tirzepatide and liraglutide caused thyroid C-cell tumours in rodents, and human relevance "has not been determined". All are contraindicated with a personal or family history of medullary thyroid carcinoma (MTC) or multiple endocrine neoplasia type 2 (MEN 2). <sup class="c" data-ref="FDA-Wegovy,FDA-Zepbound,FDA-Saxenda" title="Source 148,150,152"><a href="/obesity/sources/#src-FDA-Wegovy">148,150,152</a></sup> Routine calcitonin or thyroid ultrasound monitoring is "of uncertain value"; patients are counselled about a neck mass, trouble swallowing, shortness of breath or persistent hoarseness. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> In a Scandinavian cohort of 145,410 GLP-1 receptor agonist users, the thyroid cancer HR was 0.93 (95% CI 0.66–1.31). <sup class="c" data-ref="Pasternak2024Thyroid" title="Source 418"><a href="/obesity/sources/#src-Pasternak2024Thyroid">418</a></sup>',
  pt:'The warning comes from studies in rats and mice. Large human studies so far have not shown a clear rise in thyroid cancer, though follow-up is still short. <sup class="c" data-ref="Pasternak2024Thyroid,Ko2026Cancer" title="Source 295,418"><a href="/obesity/sources/#src-Pasternak2024Thyroid">295,418</a></sup>',
  hook:'Boxed warning: rodent thyroid C-cell tumours; contraindicated with a personal or family history of MTC or MEN 2. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {from:.5,at:.54,k:'Before a procedure',t:'Anaesthesia and aspiration',
  txt:'Semaglutide delays gastric emptying. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> The Wegovy label describes rare postmarketing reports of pulmonary aspiration under general anaesthesia or deep sedation in people taking GLP-1 receptor agonists who had food left in the stomach despite fasting. It says the data are insufficient to recommend holding the drug or changing fasting, and that patients should tell their care team before any procedure. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> Slower emptying is also why Zepbound can reduce the effect of oral hormonal contraceptives. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>',
  pt:'If you are having surgery or a scope, tell the team that you take one of these medicines. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>',
  hook:'Aspiration under anaesthesia: food may remain in the stomach despite fasting. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {from:.56,at:.61,k:'Week 68 · body composition',t:'Lean mass share of loss',
  txt:'Weight lost includes some lean mass. In the SURMOUNT-1 DXA substudy (160 people), about 75% of the weight lost on tirzepatide was fat and 25% lean mass, the same proportions as with placebo. <sup class="c" data-ref="Look2025SURMOUNT1DXA" title="Source 332"><a href="/obesity/sources/#src-Look2025SURMOUNT1DXA">332</a></sup> Across GLP-1-based trials the lean share has ranged from about 15% or less to 40–60%. "Lean mass" includes organs, bone and water as well as muscle, and MRI studies suggest the muscle changes may be adaptive, with better muscle quality. <span class="ev early">Early evidence</span> <sup class="c" data-ref="Neeland2024LeanMass" title="Source 397"><a href="/obesity/sources/#src-Neeland2024LeanMass">397</a></sup>',
  pt:'Some of the weight lost is muscle and other lean tissue, so ways to protect muscle are worth discussing with a clinician. <sup class="c" data-ref="Neeland2024LeanMass" title="Source 397"><a href="/obesity/sources/#src-Neeland2024LeanMass">397</a></sup>',
  hook:'SURMOUNT-1 DXA: about 75% fat and 25% lean of the weight lost, as with placebo. <sup class="c" data-ref="Look2025SURMOUNT1DXA" title="Source 332"><a href="/obesity/sources/#src-Look2025SURMOUNT1DXA">332</a></sup>'},
 {from:.62,at:.96,k:'Weeks 68–120 · treatment stopped',t:'Stopping and regain',
  txt:'In the STEP 1 extension all treatment, including lifestyle support, stopped at week 68. People who had lost 17.3% regained 11.6 percentage points by week 120, "two-thirds of their prior weight loss", and most cardiometabolic gains reverted towards baseline; the authors say this confirms the chronicity of obesity. <sup class="c" data-ref="Wilding2022STEP1ext" title="Source 601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">601</a></sup> In STEP 4, switching to placebo led to +6.9% vs −7.9% for those who continued; <sup class="c" data-ref="Rubino2021STEP4" title="Source 478"><a href="/obesity/sources/#src-Rubino2021STEP4">478</a></sup> in SURMOUNT-4, +14.0% vs −5.5%. <sup class="c" data-ref="Aronne2024SURMOUNT4" title="Source 25"><a href="/obesity/sources/#src-Aronne2024SURMOUNT4">25</a></sup> Across 37 studies, weight returned at about 0.4 kg a month after any weight-management medicine stopped. <sup class="c" data-ref="West2026BMJ" title="Source 589"><a href="/obesity/sources/#src-West2026BMJ">589</a></sup>',
  pt:'Obesity is a long-term condition. When the medicine stops, the body tends to regain weight. This is biology, not failure. <sup class="c" data-ref="Wilding2022STEP1ext,Aronne2024SURMOUNT4" title="Source 25,601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">25,601</a></sup>',
  hook:'STEP 1 extension: two-thirds of the weight lost came back within a year of stopping. <sup class="c" data-ref="Wilding2022STEP1ext" title="Source 601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">601</a></sup>'}
];
/* weight change, % from week 0: published points at 0, 68 and 120 <sup class="c" data-ref="Wilding2022STEP1ext" title="Source 601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">601</a></sup>; the points between are schematic */
const SE_WSEM=[[0,0],[8,-3],[20,-8.5],[36,-13.5],[52,-16.3],[68,-17.3],[80,-14.6],[96,-10],[120,-5.6]];
const SE_WPLC=[[0,0],[20,-1.6],[44,-2.1],[68,-2.0],[94,-1],[120,-.1]];
const SE_WPUB=[[0,0],[68,-17.3],[120,-5.6]],SE_WPUBP=[[68,-2.0],[120,-.1]];
/* Wegovy label dose steps, mg weekly <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>; stopped at week 68 as in the STEP 1 extension */
const SE_DOSE=[[0,.25],[4,.5],[8,1],[12,1.7],[16,2.4],[68,0]];
/* pooled label rates, % (semaglutide 2.4 mg, placebo) <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> */
const SE_GI=[['nausea',44,16],['diarrhoea',30,16],['vomiting',24,6],['constipation',24,11]];
const SE_L={wt:'weight change, % from week 0',gi:'new stomach and gut symptoms (schematic shape)',dose:'label dose steps, mg weekly',
  wk:'week',on:'on semaglutide 2.4 mg',esc:'dose escalation',stopped:'treatment stopped',sem:'semaglutide group',plc:'placebo group',
  pooled:'pooled label data, adults, %',drug:'2.4 mg',pl:'placebo',
  gb:'gallstones (adults, injection)',gb2:'gallstones (adolescents)',gb3:'RR in weight-loss trials',gbl:'gallbladder',
  pan:'pancreas',pan1:'cases on Wegovy (1 on placebo)',pan2:'per 100 patient-years',pan3:'urgent: severe pain that does not settle',
  box:'BOXED WARNING',th1:'rodents: C-cell tumours',th2:'humans: relevance not determined',th3:'contraindicated with a personal',th4:'or family history of MTC or MEN 2',th5:'C cells',thy:'thyroid',
  an1:'food left in the stomach',an2:'despite fasting',an3:'aspiration risk',an4:'tell the team before any procedure',airway:'airway',
  ln1:'of the weight lost (SURMOUNT-1 DXA)',fat:'fat',lean:'lean',ln2:'lean share across trials',ln3:'≤15%',ln4:'40–60%',
  st1:'randomised to continue or stop',cont:'continued',swp:'switched to placebo',st2:'regain after any medicine stops',st3:'0.4 kg a month (37 studies)',
  pub:'published point',sch:'shape between points schematic'};

/* the adverse-event comparator: label (or trial) rates, % */
const SE_AE=[
 {id:'weg',n:'Wegovy',g:'semaglutide 2.4 mg weekly',arms:['placebo','2.4 mg'],
  rows:[['nausea',[16,44]],['diarrhoea',[16,30]],['vomiting',[6,24]],['constipation',[11,24]],['abdominal pain',[10,20]],['hair loss',[1,3]],['stopped: adverse reaction',[3.2,6.8]]],
  src:'Wegovy label, pooled adult weight trials (n=2116 vs 1261)',
  note:'Nausea (1.8% vs 0.2%) and vomiting (1.2% vs 0%) were the commonest reasons for stopping. The label also warns of severe GI reactions, does not recommend Wegovy in severe gastroparesis, and warns of acute kidney injury from fluid loss. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> Resting heart rate rose 1–4 beats per minute on average. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {id:'zep',n:'Zepbound',g:'tirzepatide weekly',arms:['placebo','5 mg','10 mg','15 mg'],
  rows:[['nausea',[8,25,29,28]],['diarrhoea',[8,19,21,23]],['vomiting',[2,8,11,13]],['constipation',[5,17,14,11]],['hair loss',[1,5,4,5]],['stopped: adverse event',[2.6,4.3,7.1,6.2]]],
  src:'Zepbound label, Studies 1–2; stopping from SURMOUNT-1',
  note:'Symptom rates are from the label. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup> The last row is from the SURMOUNT-1 paper: 4.3%, 7.1% and 6.2% stopped because of adverse events vs 2.6% on placebo. <sup class="c" data-ref="Jastreboff2022SURMOUNT1" title="Source 253"><a href="/obesity/sources/#src-Jastreboff2022SURMOUNT1">253</a></sup> Zepbound can reduce the effect of oral contraceptives; the label advises a non-oral method, or adding a barrier method for 4 weeks after starting and after each dose increase. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>'},
 {id:'sax',n:'Saxenda',g:'liraglutide 3.0 mg daily',arms:['placebo','3.0 mg'],
  rows:[['nausea',[13.8,39.3]],['diarrhoea',[9.9,20.9]],['constipation',[8.5,19.4]],['vomiting',[3.9,15.7]]],
  src:'Saxenda label (n=3384 vs 1941)',
  note:'Rates as given in the Saxenda label; adjudicated acute pancreatitis occurred in 9 of 3291 (0.3%). <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup>'},
 {id:'qsy',n:'Qsymia',g:'phentermine–topiramate ER',arms:['placebo','3.75/23','7.5/46','15/92'],
  rows:[['paraesthesia (tingling)',[2,4,14,20]],['dry mouth',[3,7,14,19]],['constipation',[6,8,15,16]],['dysgeusia (altered taste)',[1,1,7,9]]],
  src:'Qsymia label, by dose',
  note:'A different profile: tingling, dry mouth and altered taste rise with the dose. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup> In CONQUER, depression-related events were 4%, 4% and 7% and anxiety-related events 3%, 5% and 8% (placebo, 7.5/46, 15/92 mg). <sup class="c" data-ref="Gadde2011CONQUER" title="Source 172"><a href="/obesity/sources/#src-Gadde2011CONQUER">172</a></sup> Qsymia is contraindicated in pregnancy. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup>'},
 {id:'con',n:'Contrave',g:'naltrexone–bupropion ER',arms:['placebo','32/360 mg'],
  rows:[['nausea',[5.3,29.8]]],
  src:'COR-I trial (the label\'s own table is not in this guide\'s sources)',
  note:'Nausea is from the COR-I trial: 29.8% vs 5.3%. Blood pressure rose about 1.5 mm Hg at first and later fell about 1 mm Hg below baseline. <sup class="c" data-ref="Greenway2010CORI" title="Source 196"><a href="/obesity/sources/#src-Greenway2010CORI">196</a></sup> The label warns that Contrave can raise blood pressure or heart rate, especially in the first 3 months, and carries a boxed warning on suicidal thoughts and behaviours. <sup class="c" data-ref="FDA-Contrave" title="Source 141"><a href="/obesity/sources/#src-FDA-Contrave">141</a></sup>'}
];

inits.sideeffects=()=>{
  const T=(x,y,s,c='t-sm',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${c}"${st?` style="${st}"`:''}>${s}</text>`;
  /* schematic GI-symptom curve: a bump after each dose step, settling after escalation; zero once treatment stops */
  const giF=w=>{if(w<0||w>SE_STOPW)return 0;let v=.06+.2*Math.exp(-Math.max(0,w-18)/9);[0,4,8,12,16].forEach((s,k)=>{v+=(.42+.12*k)*Math.exp(-Math.pow(w-s-1.6,2)/(2*1.5*1.5))});return v};
  const GI_MAX=(()=>{let m=0;for(let w=0;w<=SE_STOPW;w+=.25)m=Math.max(m,giF(w));return m})();
  const GI_CUM=[];{let a=0;for(let i=0;i<=SE_STOPW*4;i++){a+=giF(i/4);GI_CUM.push(a)}}
  const giCum=w=>GI_CUM[Math.round(clamp(w,0,SE_STOPW)*4)]/GI_CUM[GI_CUM.length-1];
  const fW=monoFn(SE_WSEM),fP=monoFn(SE_WPLC);
  const doseAt=w=>{let d=0;SE_DOSE.forEach(p=>{if(w>=p[0])d=p[1]});return d};
  /* ---- spotlight panels: (x,y,w,h,u) ---- */
  const bar=(x,y,w,v,max,col,h=10)=>`<rect x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${h}" rx="3" style="fill:var(--panel-2)"/><rect x="${f1(x)}" y="${f1(y)}" width="${f1(Math.max(0,w*v/max))}" height="${h}" rx="3" style="fill:${col}"/>`;
  function spGI(x,y,w,h,u,wk){const F=giCum(wk),Fp=clamp(wk/SE_STOPW);let s=T(x,y+16,SE_L.pooled,'t-xs','fill:var(--ink);font-weight:700');
    const bx=x+86,bw=w-130;
    SE_GI.forEach((r,i)=>{const yy=y+38+i*44;s+=T(x,yy+10,r[0],'t-sm','fill:var(--ink)');
      s+=bar(bx,yy,bw,r[1]*F,50,'var(--rx-drug)')+T(bx+bw+6,yy+9,Math.round(r[1]*F)+'%','t-xs','fill:var(--ink);font-weight:700');
      s+=bar(bx,yy+14,bw,r[2]*Fp,50,'var(--figure)',8)+T(bx+bw+6,yy+22,Math.round(r[2]*Fp)+'%','t-xs')});
    const ly=y+38+4*44+6;
    s+=`<rect x="${f1(x)}" y="${f1(ly)}" width="10" height="10" rx="2" style="fill:var(--rx-drug)"/>`+T(x+14,ly+9,SE_L.drug,'t-xs')+`<rect x="${f1(x+70)}" y="${f1(ly)}" width="10" height="10" rx="2" style="fill:var(--figure)"/>`+T(x+84,ly+9,SE_L.pl,'t-xs');
    return s}
  function spGB(x,y,w,h,u){let s='';const lv=liver(x+8,y+14,1.1,{});s+=lv.svg;
    const g=[lv.at.hilum[0]+8,lv.at.hilum[1]+22];
    s+=`<ellipse cx="${f1(g[0])}" cy="${f1(g[1])}" rx="13" ry="20" transform="rotate(-30 ${f1(g[0])} ${f1(g[1])})" style="fill:var(--life);fill-opacity:.35;stroke:var(--life);stroke-width:1.6"/>`;
    s+=`<path d="M${f1(g[0]+6)} ${f1(g[1]-16)}Q${f1(g[0]+10)} ${f1(g[1]-30)} ${f1(lv.at.hilum[0])} ${f1(lv.at.hilum[1])}" style="fill:none;stroke:var(--life);stroke-width:2"/>`;
    [[-4,6],[3,10],[-1,0]].forEach((p,k)=>{const q=ramp(u,.2+k*.15,.4+k*.15);if(q>0)s+=`<circle cx="${f1(g[0]+p[0])}" cy="${f1(g[1]+p[1])}" r="${f1(3.4*q)}" style="fill:var(--device);stroke:var(--panel);stroke-width:1"/>`});
    s+=kitLabel(g[0]+18,g[1]+34,SE_L.gbl,{});
    const rows=[['1.6% vs 0.7%',SE_L.gb],['3.8% vs 0%',SE_L.gb2],['RR 2.29',SE_L.gb3]];
    rows.forEach((r,i)=>{const yy=y+164+i*40,op=ramp(u,.15+i*.2,.35+i*.2);s+=`<g style="opacity:${f1(.15+.85*op)}">`+T(x,yy,r[0],'t-big','font-size:19px')+T(x,yy+15,r[1],'t-xs')+'</g>'});
    return s}
  function spPan(x,y,w,h,u){let s='';const P=[[0,26],[30,16],[80,12],[130,4],[160,0],[164,14],[130,24],[80,34],[30,40],[4,42]].map(p=>[x+16+p[0]*.95,y+40+p[1]*1.1]);
    const glow=.25+.25*Math.sin(u*Math.PI*6);
    s+=`<path d="${smoothPath(P)}" style="fill:var(--cyto);stroke:var(--gut-line);stroke-width:1.4"/><path d="${smoothPath(P)}" style="fill:var(--risk);opacity:${f1(glow*ramp(u,.1,.3))}"/>`;
    s+=`<path d="${smoothPath([[x+30,y+20],[x+8,y+40],[x+10,y+72],[x+34,y+86]],false)}" style="fill:none;stroke:var(--gut-line);stroke-width:9;stroke-linecap:round;opacity:.55"/>`;
    s+=kitLabel(x+110,y+34,SE_L.pan,{a:'m'});
    s+=`<g style="opacity:${f1(.15+.85*ramp(u,.15,.4))}">`+T(x,y+128,'4','t-big','font-size:26px')+T(x+24,y+124,SE_L.pan1,'t-xs')+'</g>';
    s+=`<g style="opacity:${f1(.15+.85*ramp(u,.35,.6))}">`+T(x,y+168,'0.2','t-big','font-size:26px')+T(x+44,y+164,SE_L.pan2,'t-xs')+'</g>';
    s+=`<rect x="${f1(x)}" y="${f1(y+192)}" width="${f1(w-6)}" height="28" rx="6" style="fill:none;stroke:var(--risk);stroke-width:1.6;opacity:${f1(ramp(u,.5,.7))}"/>`+T(x+8,y+210,SE_L.pan3,'t-xs','fill:var(--ink);font-weight:700;opacity:'+f1(ramp(u,.5,.7)));
    return s}
  function spThy(x,y,w,h,u){let s='';const cx=x+70,cy=y+70;
    /* butterfly thyroid on the trachea */
    s+=`<rect x="${f1(cx-8)}" y="${f1(cy-56)}" width="16" height="112" rx="7" style="fill:var(--panel-2);stroke:var(--device);stroke-width:1"/>`;
    [-1,1].forEach(sg=>{s+=`<path d="${blob(cx+sg*22,cy+4,24,sg>0?3:5,{rough:.08,sq:1.45})}" style="fill:var(--lean);fill-opacity:.5;stroke:var(--lean);stroke-width:1.4"/>`});
    s+=`<rect x="${f1(cx-12)}" y="${f1(cy+10)}" width="24" height="10" rx="4" style="fill:var(--lean);fill-opacity:.5"/>`;
    const rr=rng(21),c=ramp(u,.1,.5);for(let i=0;i<14;i++){const sg=i%2?1:-1,a=rr()*6.28,d=rr()*16;const px=cx+sg*22+Math.cos(a)*d*.8,py=cy+4+Math.sin(a)*d*1.3;
      s+=`<circle cx="${f1(px)}" cy="${f1(py)}" r="${f1(1.8+1.6*c)}" style="fill:var(--rx-drug);opacity:${f1(.35+.6*c)}"/>`}
    s+=kitLabel(cx+52,cy-34,SE_L.thy,{})+kitLabel(cx+52,cy-20,SE_L.th5,{});
    const bx=x,by=y+150,bw=w-6,o=ramp(u,.25,.5);
    s+=`<g style="opacity:${f1(.1+.9*o)}"><rect x="${f1(bx)}" y="${f1(by)}" width="${f1(bw)}" height="96" style="fill:none;stroke:var(--ink);stroke-width:2.4"/>`+
      T(bx+10,by+18,SE_L.box,'t-xs','fill:var(--ink);font-weight:700;letter-spacing:.1em')+T(bx+10,by+38,SE_L.th1,'t-xs','fill:var(--ink)')+T(bx+10,by+54,SE_L.th2,'t-xs','fill:var(--ink)')+
      T(bx+10,by+72,SE_L.th3,'t-xs')+T(bx+10,by+86,SE_L.th4,'t-xs')+'</g>';
    return s}
  function spAn(x,y,w,h,u){let s='';const st=stomach(x+40,y+50,1.1,{fill:.25+.4*ramp(u,0,.6),labels:false});s+=st.svg;
    /* airway beside the oesophagus */
    const ax=x+30;s+=`<path d="M${f1(ax)} ${f1(y+10)}L${f1(ax)} ${f1(y+70)}" style="stroke:var(--device);stroke-width:10;stroke-linecap:round;opacity:.45"/>`+T(ax+10,y+14,SE_L.airway,'t-xs');
    const q=ramp(u,.4,.9);if(q>0){const e=st.at.eso;s+=`<path d="M${f1(e[0])} ${f1(e[1]+10)}Q${f1(e[0]-10)} ${f1(y+10)} ${f1(ax+6)} ${f1(y+40)}" style="fill:none;stroke:var(--risk);stroke-width:2;stroke-dasharray:4 3;opacity:${f1(q)}" marker-end="url(#seArR)"/>`;
      s+=kitLabel(e[0]+10,y+28,SE_L.an3,{})}
    s+=T(x,y+222,SE_L.an1,'t-sm','fill:var(--ink)')+T(x,y+238,SE_L.an2,'t-sm','fill:var(--ink)');
    s+=`<rect x="${f1(x)}" y="${f1(y+252)}" width="${f1(w-6)}" height="26" rx="6" style="fill:none;stroke:var(--tx);stroke-width:1.4"/>`+T(x+8,y+269,SE_L.an4,'t-xs','fill:var(--ink);font-weight:700');
    return s}
  function spLean(x,y,w,h,u){let s='';const bw=w-10,g=ease(ramp(u,0,.6));
    s+=T(x,y+28,'25%','t-big','font-size:30px;fill:var(--ink)')+T(x+66,y+24,SE_L.lean,'t-sm','fill:var(--ink)')+T(x,y+46,SE_L.ln1,'t-xs');
    const by=y+62;s+=`<rect x="${f1(x)}" y="${f1(by)}" width="${f1(bw)}" height="26" rx="5" style="fill:var(--panel-2)"/>`;
    s+=`<rect x="${f1(x)}" y="${f1(by)}" width="${f1(bw*.75*g)}" height="26" rx="5" style="fill:var(--fat)"/><rect x="${f1(x+bw*.75*g)}" y="${f1(by)}" width="${f1(bw*.25*g)}" height="26" rx="5" style="fill:var(--lean)"/>`;
    if(g>.5)s+=kitLabel(x+bw*.36,by+17,SE_L.fat+' 75%',{a:'m'})+kitLabel(x+bw*.875,by+17,SE_L.lean,{a:'m'});
    /* the range across trials */
    const ry=y+150,o=ramp(u,.45,.8),X=v=>x+bw*v/100;
    s+=`<g style="opacity:${f1(.12+.88*o)}">`+T(x,ry-22,SE_L.ln2,'t-xs','fill:var(--ink);font-weight:700');
    s+=`<line x1="${f1(X(0))}" x2="${f1(X(100))}" y1="${ry}" y2="${ry}" class="axis"/>`;
    [0,25,50,75,100].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${ry-3}" y2="${ry+3}" class="axis"/>`+T(X(v),ry+16,v+'%','t-xs t-mid')});
    s+=`<rect x="${f1(X(0))}" y="${ry-7}" width="${f1(X(15)-X(0))}" height="14" rx="3" style="fill:var(--lean);opacity:.8"/><rect x="${f1(X(40))}" y="${ry-7}" width="${f1(X(60)-X(40))}" height="14" rx="3" style="fill:var(--lean);opacity:.8"/>`;
    s+=`<circle cx="${f1(X(25))}" cy="${ry}" r="5" style="fill:var(--lean);stroke:var(--panel);stroke-width:2"/>`;
    s+=T(X(7.5),ry+32,SE_L.ln3,'t-xs t-mid')+T(X(50),ry+32,SE_L.ln4,'t-xs t-mid')+'</g>';
    return s}
  function spStop(x,y,w,h,u){let s='';const g=ease(ramp(u,.05,.5)),c=x+w*.46,sc=(w*.46-10)/15;
    s+=T(x,y+14,SE_L.st1,'t-xs','fill:var(--ink);font-weight:700');
    const D=[['STEP 4 (from week 20)',-7.9,6.9],['SURMOUNT-4 (from week 36)',-5.5,14.0]];
    D.forEach((d,i)=>{const yy=y+40+i*76;s+=T(x,yy,d[0],'t-xs');
      s+=`<line x1="${f1(c)}" x2="${f1(c)}" y1="${yy+6}" y2="${yy+52}" class="axis"/>`;
      const a=d[1]*g,b=d[2]*g;
      s+=`<rect x="${f1(c+a*sc)}" y="${yy+10}" width="${f1(-a*sc)}" height="15" rx="3" style="fill:var(--rx-drug)"/>`+T(c+a*sc-4,yy+22,f1(a)+'%','t-xs t-end','fill:var(--ink);font-weight:700');
      s+=`<rect x="${f1(c)}" y="${yy+30}" width="${f1(b*sc)}" height="15" rx="3" style="fill:var(--figure)"/>`+T(c+b*sc+4,yy+42,'+'+f1(b)+'%','t-xs','fill:var(--ink);font-weight:700')});
    const ly=y+196;s+=`<rect x="${f1(x)}" y="${ly}" width="10" height="10" rx="2" style="fill:var(--rx-drug)"/>`+T(x+14,ly+9,SE_L.cont,'t-xs')+`<rect x="${f1(x+90)}" y="${ly}" width="10" height="10" rx="2" style="fill:var(--figure)"/>`+T(x+104,ly+9,SE_L.swp,'t-xs');
    const o=ramp(u,.5,.8);s+=`<g style="opacity:${f1(.12+.88*o)}">`+T(x,y+246,SE_L.st3,'t-big','font-size:17px')+T(x,y+262,SE_L.st2,'t-xs')+'</g>';
    return s}
  const SP=[spGI,spGB,spPan,spThy,spAn,spLean,spStop];

  const svg=$('#seSvg'),rg=$('#seT'),pb=$('#sePlay'),noteEl=$('#seNote'),stepsEl=$('#seSteps');
  let setActive=()=>{};
  function draw(t){
    const N=vb(svg,'720 380','400 650');
    const wk=t*SE_WK,p=phaseOf(SE_STEPS,t),nx=SE_STEPS[p+1]?SE_STEPS[p+1].from:1.0001,u=clamp((t-SE_STEPS[p].from)/(nx-SE_STEPS[p].from));
    const L=N?{x0:44,x1:388,ay:44,ah:112,by:186,bh:46,cy:256,ch:30,ty:304,sx:14,sy:330,sw:372,sh:300}
             :{x0:52,x1:438,ay:44,ah:130,by:204,bh:52,cy:280,ch:34,ty:330,sx:472,sy:26,sw:240,sh:340};
    const X=w=>L.x0+(L.x1-L.x0)*w/SE_WK,YA=v=>L.ay+L.ah*(2-v)/22,YB=v=>L.by+L.bh-L.bh*v/GI_MAX,YC=v=>L.cy+L.ch-L.ch*v/2.4;
    let s=`<defs>${marker('seArR','var(--risk)',6)}</defs>`;
    s+=T(L.x0-38,20,`${SE_L.wk} ${Math.round(wk)}`,'t-big','font-size:18px')+T(L.x0+48,19,wk<=SE_STOPW?(wk<17?SE_L.esc:SE_L.on):SE_L.stopped,'t-sm',wk>SE_STOPW?'fill:var(--ink)':'');
    /* off-treatment shading */
    s+=`<rect x="${f1(X(SE_STOPW))}" y="${L.ay}" width="${f1(X(SE_WK)-X(SE_STOPW))}" height="${f1(L.cy+L.ch-L.ay)}" style="fill:var(--panel-2);opacity:.6"/>`;
    s+=`<rect x="${f1(X(0))}" y="${L.ay}" width="${f1(X(16)-X(0))}" height="${f1(L.cy+L.ch-L.ay)}" style="fill:var(--tx);opacity:.07"/>`;
    /* panel A: weight */
    [0,-5,-10,-15,-20].forEach(v=>{s+=`<line x1="${L.x0}" x2="${L.x1}" y1="${f1(YA(v))}" y2="${f1(YA(v))}" class="grid"/>`+T(L.x0-5,YA(v)+3.5,v,'t-xs t-end')});
    s+=T(L.x0,L.ay-6,SE_L.wt,'t-xs','fill:var(--ink);font-weight:700');
    const curve=(f,col,lw,dash)=>{const P=[];for(let w=0;w<=wk;w+=1)P.push([X(w),YA(f(w))]);P.push([X(wk),YA(f(wk))]);return `<path d="${ptsD(P)}" style="fill:none;stroke:${col};stroke-width:${lw};stroke-linejoin:round${dash?';stroke-dasharray:'+dash:''}"/>`};
    s+=curve(fP,'var(--figure-line)',2,'5 4')+curve(fW,'var(--rx-drug)',3);
    SE_WPUB.forEach(q=>{if(wk>=q[0])s+=`<circle cx="${f1(X(q[0]))}" cy="${f1(YA(q[1]))}" r="4.5" style="fill:var(--rx-drug);stroke:var(--panel);stroke-width:2"/>`});
    SE_WPUBP.forEach(q=>{if(wk>=q[0])s+=`<circle cx="${f1(X(q[0]))}" cy="${f1(YA(q[1]))}" r="3.5" style="fill:var(--figure-line);stroke:var(--panel);stroke-width:1.5"/>`});
    if(wk>=SE_STOPW)s+=kitLabel(X(SE_STOPW)+6,YA(-17.3)+4,'−17.3%',{});
    if(wk>=SE_WK-.5)s+=kitLabel(X(SE_WK)-4,YA(-5.6)+18,'−5.6%',{a:'e'});
    const ey=YA(fW(wk)),rt=X(wk)>L.x1-110,lx=rt?X(wk)-6:X(wk)+6,la=rt?'t-xs t-end':'t-xs';s+=T(lx,ey+(rt?16:-8),SE_L.sem,la,'fill:var(--rx-drug);font-weight:700;opacity:'+f1(ramp(wk,4,12)));
    s+=T(lx,YA(fP(wk))+(rt?14:-6),SE_L.plc,la,'opacity:'+f1(ramp(wk,4,12)));
    /* panel B: GI symptoms */
    s+=T(L.x0,L.by-6,SE_L.gi,'t-xs','fill:var(--ink);font-weight:700');
    {const P=[];for(let w=0;w<=wk;w+=.5)P.push([X(w),YB(giF(w))]);if(P.length>1)s+=`<path d="${ptsD(P)}L${f1(P[P.length-1][0])} ${f1(YB(0))}L${f1(X(0))} ${f1(YB(0))}Z" style="fill:var(--rx-drug);opacity:.18"/><path d="${ptsD(P)}" style="fill:none;stroke:var(--rx-drug);stroke-width:2"/>`}
    s+=`<line x1="${L.x0}" x2="${L.x1}" y1="${f1(YB(0))}" y2="${f1(YB(0))}" class="axis"/>`;
    /* panel C: dose steps */
    s+=T(L.x1,L.cy-6,SE_L.dose,'t-xs t-end','fill:var(--ink);font-weight:700');
    {let d='';SE_DOSE.forEach((q,k)=>{const nxw=SE_DOSE[k+1]?SE_DOSE[k+1][0]:SE_WK;if(q[0]>wk)return;const e=Math.min(nxw,wk);d+=(d?'L':'M')+f1(X(q[0]))+' '+f1(YC(q[1]))+'L'+f1(X(e))+' '+f1(YC(q[1]))});
      s+=`<path d="${d}" style="fill:none;stroke:var(--tx);stroke-width:2.6"/>`}
    if(wk>=16)s+=T(X(16)+6,YC(2.4)+12,'2.4 mg','t-xs','fill:var(--tx);font-weight:700');
    s+=`<line x1="${L.x0}" x2="${L.x1}" y1="${f1(YC(0))}" y2="${f1(YC(0))}" class="axis"/>`;
    /* week axis and now line */
    [0,16,40,68,94,120].forEach(w=>{s+=`<line x1="${f1(X(w))}" x2="${f1(X(w))}" y1="${f1(L.cy+L.ch)}" y2="${f1(L.cy+L.ch+4)}" class="axis"/>`+T(X(w),L.ty,w,'t-xs t-mid')});
    s+=T(L.x1,L.ty+14,SE_L.wk+'s','t-xs t-end');
    s+=T(X(SE_STOPW)+4,L.by+14,SE_L.stopped,'t-xs','fill:var(--ink)');
    s+=`<line x1="${f1(X(wk))}" x2="${f1(X(wk))}" y1="${L.ay}" y2="${f1(L.cy+L.ch)}" style="stroke:var(--ink);stroke-width:1.2;opacity:.5"/>`;
    /* spotlight */
    s+=`<rect x="${L.sx-8}" y="${L.sy-8}" width="${L.sw+12}" height="${L.sh+12}" rx="12" style="fill:var(--field);stroke:var(--line)"/>`;
    s+=T(L.sx,L.sy+12,SE_STEPS[p].t,'t-lbl');
    s+=SP[p](L.sx,L.sy+24,L.sw,L.sh-24,u,wk);
    svg.innerHTML=s;
    noteEl.innerHTML=noteHTML(SE_STEPS[p]);setActive(p);
  }
  const stop=playWire(rg,pb,draw,22000,'Replay','sideeffects');
  setActive=stepWire(stepsEl,SE_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- the adverse-event comparator ---- */
  const asvg=$('#seAE'),abtn=$('#seAEBtns'),anote=$('#seAENote');
  let cur=0,stopA=null;
  const armCol=(k,n)=>k===0?'var(--figure)':'var(--rx-drug)',armOp=(k,n)=>k===0?1:(n===2?1:[0,.45,.72,1][k]);
  function drawAE(g){
    const D=SE_AE[cur],na=D.arms.length,N=NARROW(),bh=na>2?10:13,gap=3;
    const rowH=na*(bh+gap)+(N?28:16),top=68,H=top+D.rows.length*rowH+24,Wd=N?400:720;
    vb(asvg,`720 ${H}`,`400 ${H+10}`);
    const L=N?{lx:12,bx:12,bw:316}:{lx:12,bx:210,bw:440},max=50,X=v=>L.bx+L.bw*v/max;
    let s=T(12,20,D.n+' · '+D.g,'t-lbl')+T(12,36,D.src,'t-xs');
    /* legend */
    let lx=12;D.arms.forEach((a,k)=>{s+=`<rect x="${lx}" y="44" width="10" height="10" rx="2" style="fill:${armCol(k,na)};opacity:${armOp(k,na)}"/>`+T(lx+14,53,a,'t-xs');lx+=24+a.length*6.4});
    [0,10,20,30,40,50].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${top}" y2="${f1(H-20)}" class="grid"/>`+T(X(v),H-6,v+'%','t-xs t-mid')});
    D.rows.forEach((r,i)=>{const y=top+i*rowH;
      s+=T(L.lx,N?y+12:y+14,r[0],'t-sm','fill:var(--ink)');
      const by=N?y+18:y+4;
      r[1].forEach((v,k)=>{const yy=by+k*(bh+gap),vv=v*g;s+=`<rect x="${L.bx}" y="${f1(yy)}" width="${f1(Math.max(0,X(vv)-L.bx))}" height="${bh}" rx="2.5" style="fill:${armCol(k,na)};opacity:${armOp(k,na)}"/>`+T(X(vv)+4,yy+bh-1.5,f1(v)+'%','t-xs',k?'fill:var(--ink)':'')})});
    asvg.innerHTML=s;
  }
  function setAE(i){cur=i;$$('button',abtn).forEach((b,k)=>b.setAttribute('aria-pressed',k===i));
    const D=SE_AE[i];anote.innerHTML=`<div class="kicker">${D.src}</div><h4>${D.n}</h4><p>${D.note}</p>`;
    if(stopA)stopA();stopA=animate(600,p=>drawAE(ease(p)),()=>{stopA=null})}
  abtn.innerHTML=SE_AE.map((d,i)=>`<button class="btn" aria-pressed="false" data-ae="${i}">${d.n}</button>`).join('');
  abtn.addEventListener('click',e=>{const b=e.target.closest('[data-ae]');if(b)setAE(+b.dataset.ae)});
  setAE(0);drawAE(1);
  {const prev=redraws.sideeffects;redraws.sideeffects=()=>{prev&&prev();drawAE(1)}}
};
/* =============== 3.6 Metabolic & bariatric surgery =============== */
/* Main player: one gut drawn by gutTract() changes from a normal stomach into a sleeve gastrectomy, then (starting
   again from a normal stomach) into a Roux-en-Y gastric bypass; then the gut-hormone signals and the newer bile-acid and
   microbiome ideas. Hormone arrows show direction only, never measured levels. */
const SU_STEPS=[
 {from:0,at:.06,k:'Before surgery',t:'The stomach and gut',
  txt:'Food passes from the oesophagus into the stomach, then the duodenum, the small intestine and the colon. The stomach and gut also send hunger and fullness hormones such as ghrelin, GLP-1 and PYY (see <a href="#appetite" data-go="appetite">the gut-brain loop</a>). About 280,000 metabolic and bariatric operations were done in the United States in 2022, yet the ASMBS estimates that only about 1% of people who qualify have surgery. <sup class="c" data-ref="Clapp2024ASMBS" title="Source 84"><a href="/obesity/sources/#src-Clapp2024ASMBS">84</a></sup> Contemporary operations are done laparoscopically in the vast majority of cases. <sup class="c" data-ref="Nguyen2017NatRev" title="Source 400"><a href="/obesity/sources/#src-Nguyen2017NatRev">400</a></sup>',
  pt:'Weight-loss surgery changes the stomach and gut, and also the hormones that control hunger and fullness. It is more than "a smaller stomach".',
  hook:'Sleeve gastrectomy and Roux-en-Y gastric bypass together make up about 90% of operations worldwide. <sup class="c" data-ref="Eisenberg2022ASMBS" title="Source 132"><a href="/obesity/sources/#src-Eisenberg2022ASMBS">132</a></sup>'},
 {from:.17,at:.3,k:'Operation 1',t:'Sleeve gastrectomy',
  txt:'The surgeon removes the greater curvature of the stomach, leaving a narrow tube along the lesser curvature. One review describes resection of "approximately 80%" of the stomach; <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> another describes a vertical division that reduces stomach size "by 75%" while keeping the pylorus. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> In one series the cut started 6 cm from the pylorus and was sized on a 48 Fr bougie. <sup class="c" data-ref="Genco2017" title="Source 192"><a href="/obesity/sources/#src-Genco2017">192</a></sup> Removing the greater curvature lowers ghrelin. <sup class="c" data-ref="Kim2026Complications,Karamanakos2008" title="Source 272,284"><a href="/obesity/sources/#src-Kim2026Complications">272,284</a></sup>',
  pt:'In a sleeve, most of the stomach is removed and the rest becomes a narrow tube. Food still takes its usual route through the gut.',
  hook:'Sleeve gastrectomy is the most performed operation worldwide (IFSO survey 2020 to 2021). <sup class="c" data-ref="Angrisani2024IFSO" title="Source 18"><a href="/obesity/sources/#src-Angrisani2024IFSO">18</a></sup>'},
 {from:.36,at:.5,k:'Operation 2',t:'Roux-en-Y gastric bypass',
  txt:'A small gastric pouch is joined to a jejunal Roux limb, so food bypasses most of the stomach, the duodenum and a variable length of upper small bowel. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> The bypassed stomach stays in place. Digestive juices from the liver and pancreas run down the biliary limb and meet food at the join. In the YOMEGA trial the Roux (alimentary) limb was 150 cm and the biliary limb 50 cm. <sup class="c" data-ref="Robert2019YOMEGA" title="Source 465"><a href="/obesity/sources/#src-Robert2019YOMEGA">465</a></sup> A longer biliopancreatic limb has been linked with more weight loss and better glucose control (<span class="ev early">Early evidence</span>). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup>',
  pt:'In a bypass, a small pouch is made at the top of the stomach and joined straight to the small intestine. Food skips most of the stomach and the first part of the gut.',
  hook:'Bypass: pouch, alimentary (Roux) limb, biliopancreatic limb, common channel. YOMEGA limbs: 150 cm alimentary, 50 cm biliary. <sup class="c" data-ref="Robert2019YOMEGA" title="Source 465"><a href="/obesity/sources/#src-Robert2019YOMEGA">465</a></sup>'},
 {from:.56,at:.65,k:'Mechanism',t:'Gut hormones change',
  txt:'After gastric bypass, PYY and GLP-1 rose after meals and insulin responses came early and exaggerated, compared with lean controls and controls with obesity. None of these changes occurred in people who lost the same weight with a gastric band (<span class="ev est">Established</span>). <sup class="c" data-ref="leRoux2006" title="Source 319"><a href="/obesity/sources/#src-leRoux2006">319</a></sup> After a diet-induced weight loss of 17%, 24-hour ghrelin rose by 24%; after a 36% loss with gastric bypass, it was 77% lower than in normal-weight controls. <sup class="c" data-ref="Cummings2002" title="Source 104"><a href="/obesity/sources/#src-Cummings2002">104</a></sup> In a randomised study, fasting ghrelin fell markedly after sleeve but not significantly after bypass, and fasting PYY rose after both. <sup class="c" data-ref="Karamanakos2008" title="Source 272"><a href="/obesity/sources/#src-Karamanakos2008">272</a></sup>',
  pt:'After a bypass, the gut sends stronger "I am full" signals after meals. Dieting tends to push the hunger hormone up; surgery does not do this in the same way.',
  hook:'Sleeve lowers ghrelin; bypass raises postprandial GLP-1 and PYY. <sup class="c" data-ref="Karamanakos2008,leRoux2006" title="Source 272,319"><a href="/obesity/sources/#src-Karamanakos2008">272,319</a></sup>'},
 {from:.74,at:.86,k:'Newer ideas',t:'Beyond restriction',
  txt:'In mice with diet-induced obesity, the benefits of sleeve gastrectomy did not come from mechanical restriction: bile acids rose, gut microbes changed, and without the bile-acid receptor FXR the weight and glucose benefits were "substantially reduced" (<span class="ev early">Early evidence</span>, animal data). <sup class="c" data-ref="Ryan2014Nature" title="Source 481"><a href="/obesity/sources/#src-Ryan2014Nature">481</a></sup> Bypass produced lasting microbiome changes in people, and germ-free mice given these patients\' stool stored less fat (<span class="ev hyp">Hypothesis</span> for humans). <sup class="c" data-ref="Tremaroli2015" title="Source 551"><a href="/obesity/sources/#src-Tremaroli2015">551</a></sup> A diabetes-surgery consensus calls the gut "a meaningful target" for treating type 2 diabetes. <sup class="c" data-ref="Rubino2016DSS" title="Source 476"><a href="/obesity/sources/#src-Rubino2016DSS">476</a></sup>',
  pt:'Surgery seems to work through hormones, bile acids and gut bacteria as well as through size. How much each part matters in people is still being studied.',
  hook:'Hormone changes are established in people; bile-acid/FXR and microbiome roles come mainly from mice. <sup class="c" data-ref="leRoux2006,Ryan2014Nature,Tremaroli2015" title="Source 319,481,551"><a href="/obesity/sources/#src-leRoux2006">319,481,551</a></sup>'}
];
/* hormone rows per phase: [kind, name, direction (-1 falls, 0 no change, 1 rises, null: not reported), text] */
const SU_HROWS=[
 [['ghrelin','ghrelin',0,'stomach: meal-time rhythm'],['glp1','GLP-1',0,'L cells: after meals'],['pyy','PYY',0,'L cells: after meals'],['insulin','insulin',0,'pancreas']],
 [['ghrelin','ghrelin',-1,'fasting level falls'],['glp1','GLP-1',null,'not measured in that trial'],['pyy','PYY',1,'fasting level rises'],['insulin','insulin',null,'not measured in that trial']],
 [['ghrelin','ghrelin',0,'fasting: no significant change'],['glp1','GLP-1',1,'rises after meals'],['pyy','PYY',1,'rises after meals'],['insulin','insulin',1,'early, exaggerated']],
 [['ghrelin','ghrelin',0,'fasting: no significant change'],['glp1','GLP-1',1,'rises after meals'],['pyy','PYY',1,'rises after meals'],['insulin','insulin',1,'early, exaggerated']],
 [['ghrelin','ghrelin',0,'fasting: no significant change'],['glp1','GLP-1',1,'rises after meals'],['pyy','PYY',1,'rises after meals'],['insulin','insulin',1,'early, exaggerated']]
];
const SU_TITLE=[['A normal stomach and gut','food takes the usual route'],['Sleeve gastrectomy','a narrow tube; the pylorus is kept'],['Roux-en-Y gastric bypass','a small pouch joined to the small bowel'],['Gut hormones after bypass','direction of change, not measured levels'],['Beyond restriction','bile acids and gut microbes']];

/* the procedure explorer: route segments and what happens to each */
const SU_SEGS=['Oesophagus','Stomach','Duodenum','Upper small bowel','Lower small bowel (ileum)','Colon'];
const SU_PX={
 sleeve:{lab:'Sleeve',pass:[1,1,1,1,1,1],how:['food passes','a narrow tube','food passes','food passes','food passes','food passes'],
  note:{k:'Sleeve gastrectomy',t:'A narrow tube, same route',
   txt:'The greater curvature is removed and the pylorus kept, so food still passes the duodenum. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> One review gives "approximately 80%" of the stomach removed. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> It remained the most performed operation worldwide in 2020 to 2021. <sup class="c" data-ref="Angrisani2024IFSO" title="Source 18"><a href="/obesity/sources/#src-Angrisani2024IFSO">18</a></sup> Reflux is its signature late problem: endoscopic oesophagitis in 31% after sleeve versus 7% after bypass at 10 years in SLEEVEPASS. <sup class="c" data-ref="Salminen2022SLEEVEPASS" title="Source 488"><a href="/obesity/sources/#src-Salminen2022SLEEVEPASS">488</a></sup>',
   pt:'The stomach is made much smaller, but nothing is rerouted.',
   hook:'Sleeve: resecting the greater curvature lowers plasma ghrelin, a hunger-promoting hormone. <sup class="c" data-ref="Kim2026Complications,Karamanakos2008" title="Source 272,284"><a href="/obesity/sources/#src-Kim2026Complications">272,284</a></sup>'}},
 bypass:{lab:'Bypass',pass:[1,.5,0,.5,1,1],how:['food passes','small pouch only','bypassed','biliary limb bypassed','food meets digestive juices','food passes'],
  note:{k:'Roux-en-Y gastric bypass',t:'A pouch and a new route',
   txt:'A small pouch is joined to a jejunal Roux limb, bypassing most of the stomach, the duodenum and some upper small bowel. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> YOMEGA used a 150 cm alimentary limb and a 50 cm biliary limb. <sup class="c" data-ref="Robert2019YOMEGA" title="Source 465"><a href="/obesity/sources/#src-Robert2019YOMEGA">465</a></sup> The one-anastomosis bypass uses a single join with a 200 cm biliopancreatic limb; it was non-inferior for weight at 2 years (excess BMI loss 87.9% versus 85.8%) but had more serious adverse events (42 versus 24), including nine nutritional complications versus none. <sup class="c" data-ref="Robert2019YOMEGA" title="Source 465"><a href="/obesity/sources/#src-Robert2019YOMEGA">465</a></sup>',
   pt:'Food goes from a small pouch straight into the small intestine, skipping most of the stomach and the first part of the gut.',
   hook:'Vitamin B12 deficiency affects 19 to 35% at 5 years after bypass and biliopancreatic diversion, because the duodenum is bypassed and gastric acid and intrinsic factor fall. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup>'}},
 band:{lab:'Band',pass:[1,1,1,1,1,1],how:['food passes','through the band\'s outlet','food passes','food passes','food passes','food passes'],
  note:{k:'Adjustable gastric band',t:'A band that can be adjusted',
   txt:'A silicone band sits a few centimetres below the cardia; the outlet is adjusted by adding or removing saline through a port under the skin. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> Its use "has diminished significantly over the past decade" <sup class="c" data-ref="Eisenberg2022ASMBS" title="Source 132"><a href="/obesity/sources/#src-Eisenberg2022ASMBS">132</a></sup> and continued to decline worldwide. <sup class="c" data-ref="Angrisani2024IFSO" title="Source 18"><a href="/obesity/sources/#src-Angrisani2024IFSO">18</a></sup> In LABS-2, weight loss at 7 years averaged 14.9% after a band versus 28.4% after bypass, and 160 band versus 14 bypass participants had reoperations. <sup class="c" data-ref="Courcoulas2018LABS" title="Source 99"><a href="/obesity/sources/#src-Courcoulas2018LABS">99</a></sup>',
   pt:'A band is a ring around the top of the stomach. It can be tightened or loosened, but it is now used much less often.',
   hook:'After a band, the gut-hormone changes seen after bypass did not occur, despite equal weight loss. <sup class="c" data-ref="leRoux2006" title="Source 319"><a href="/obesity/sources/#src-leRoux2006">319</a></sup>'}},
 switch:{lab:'Duodenal switch',pass:[1,1,.3,0,1,1],how:['food passes','a sleeve','divided just past the pylorus','bypassed','food joins a short common channel','food passes'],
  note:{k:'Biliopancreatic diversion and duodenal switch',t:'The most malabsorptive operations',
   txt:'Biliopancreatic diversion leaves 200 to 250 mL of upper stomach joined to the last 250 cm of small bowel, with a 50 cm common channel where food and digestive juices mix, producing marked fat and protein malabsorption; it and its duodenal-switch variant are used in under 2% of operations because of nutritional risk. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> In people with BMI 50 to 60, BMI fell by 22.1 units after duodenal switch versus 13.6 after bypass at 5 years, but 44.8% versus 9.7% needed further procedures. <sup class="c" data-ref="Risstad2015JAMASurg" title="Source 464"><a href="/obesity/sources/#src-Risstad2015JAMASurg">464</a></sup> SADI-S, a single-join variant, appears in the IFSO/ASMBS evidence review. <sup class="c" data-ref="DeLuca2024IFSO" title="Source 116"><a href="/obesity/sources/#src-DeLuca2024IFSO">116</a></sup>',
   pt:'This operation combines a sleeve with a long bypass. It gives the most weight loss and the most risk of missing vitamins and protein.',
   hook:'Biliopancreatic diversion/duodenal switch: most weight loss, most malabsorption. <sup class="c" data-ref="Risstad2015JAMASurg,Buchwald2004JAMA" title="Source 56,464"><a href="/obesity/sources/#src-Risstad2015JAMASurg">56,464</a></sup>'}}
};

/* SOS weight change: overall surgery and control groups to 20 years <sup class="c" data-ref="Sjostrom2013JIM" title="Source 514"><a href="/obesity/sources/#src-Sjostrom2013JIM">514</a></sup>; by operation to 10 years,
   with the maximum (reached at 1 to 2 years) plotted at 1.5 years <sup class="c" data-ref="Sjostrom2007SOS" title="Source 511"><a href="/obesity/sources/#src-Sjostrom2007SOS">511</a></sup> */
const SU_SOS=[
 {id:'all',lab:'All surgery',col:'var(--tx)',dash:'',on:1,P:[[0,0],[2,-23],[10,-17],[15,-16],[20,-18]]},
 {id:'ctl',lab:'Controls (usual care)',col:'var(--muted)',dash:'6 4',on:1,P:[[0,0],[2,0],[10,1],[15,-1],[20,-1]]},
 {id:'gbp',lab:'Gastric bypass',col:'var(--brand)',dash:'',on:0,P:[[0,0],[1.5,-32],[10,-25]]},
 {id:'vbg',lab:'Vertical banded gastroplasty',col:'var(--accent)',dash:'2 3',on:0,P:[[0,0],[1.5,-25],[10,-16]]},
 {id:'band',lab:'Banding',col:'var(--hl)',dash:'9 3 2 3',on:0,P:[[0,0],[1.5,-20],[10,-14]]}
];
/* STAMPEDE 5-year results <sup class="c" data-ref="Schauer2017STAMPEDE" title="Source 494"><a href="/obesity/sources/#src-Schauer2017STAMPEDE">494</a></sup> */
const SU_ST={
 a1c:{lab:'HbA1c 6.0% or less',head:'% reaching HbA1c of 6.0% or less at 5 years',v:[5,29,23],max:40,fmt:v=>v+'%'},
 wt:{lab:'Weight change',head:'% weight change at 5 years',v:[-5,-23,-19],max:30,fmt:v=>'−'+Math.abs(v)+'%'},
 ins:{lab:'Insulin use',head:'fall in the share using insulin at 5 years (% points)',v:[13,35,34],max:40,fmt:v=>v+'%'}
};
const SU_ARMS=['Intensive medical therapy','Gastric bypass','Sleeve gastrectomy'];

inits.surgery=()=>{
  /* ---------- main player ---------- */
  const svg=$('#suSvg'),rg=$('#suT'),note=$('#suNote');
  const arrow=(x,y,dir,col,op=1)=>{
    if(dir==null)return `<text x="${f1(x)}" y="${f1(y+4)}" class="t-sm t-mid" style="opacity:${f1(op)}">n/a</text>`;
    if(dir===0)return `<path d="M${f1(x-7)} ${f1(y)}H${f1(x+7)}" style="stroke:var(--muted);stroke-width:2.4;stroke-linecap:round;opacity:${f1(op)}"/>`;
    const d=dir;return `<path d="M${f1(x)} ${f1(y-8*d)}V${f1(y+8*d)}M${f1(x-5)} ${f1(y-3*d)}L${f1(x)} ${f1(y-8*d)}L${f1(x+5)} ${f1(y-3*d)}" style="fill:none;stroke:${col};stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;opacity:${f1(op)}"/>`};
  const box=(x,y,w,h)=>`<rect x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${f1(h)}" rx="12" style="fill:var(--panel-2);stroke:var(--line)"/>`;
  const tiles=(x,y,w,h,items,u)=>{let s='';const n=items.length,tw=(w-(n-1)*8)/n;
    items.forEach((it,i)=>{const tx=x+i*(tw+8),op=clamp(.4+u*4-i*.4);
      s+=`<g style="opacity:${f1(op)}"><rect x="${f1(tx)}" y="${f1(y)}" width="${f1(tw)}" height="${f1(h)}" rx="10" style="fill:var(--panel);stroke:var(--line)"/>`;
      s+=`<text x="${f1(tx+10)}" y="${f1(y+30)}" class="t-big" style="font-size:22px;fill:var(--tx)">${it.v}</text>`;
      it.l.forEach((ln,j)=>{s+=`<text x="${f1(tx+10)}" y="${f1(y+50+j*13)}" class="t-xs" style="fill:var(--ink)">${ln}</text>`});s+='</g>'});
    return s};
  function stat(p,u,m,x,y,w,h,N){
    let s=box(x,y,w,h);const ix=x+12,iw=w-24;
    if(p===0)s+=tiles(ix,y+12,iw,h-24,[{v:'280,000',l:['US operations','in 2022']},{v:'~1%',l:['of people who','qualify (estimate)']},{v:'~90%',l:['sleeve or bypass,','worldwide']}],u);
    else if(p===1){const v=Math.round(80*m);
      s+=`<text x="${f1(ix)}" y="${f1(y+26)}" class="t-xs" style="fill:var(--ink);font-weight:700">stomach removed in a sleeve (one review)</text>`;
      s+=`<text x="${f1(ix)}" y="${f1(y+74)}" class="t-big" style="font-size:44px;fill:var(--tx)">${v}%</text>`;
      const bx=ix+(N?120:130),bw=iw-(N?120:130),by=y+46,bh=26;
      s+=`<rect x="${f1(bx)}" y="${by}" width="${f1(bw)}" height="${bh}" rx="6" style="fill:var(--stomach);stroke:var(--gut-line)"/>`;
      s+=`<rect x="${f1(bx+bw*(1-.8*m))}" y="${by}" width="${f1(bw*.8*m)}" height="${bh}" rx="6" style="fill:var(--panel);stroke:var(--gut-line);stroke-dasharray:4 3"/>`;
      s+=`<text x="${f1(bx+4)}" y="${by+bh+14}" class="t-xs">kept</text><text x="${f1(bx+bw)}" y="${by+bh+14}" class="t-xs t-end">removed</text>`;
      s+=`<text x="${f1(ix)}" y="${f1(y+h-14)}" class="t-xs" style="fill:var(--ink)">${N?'another review: "by 75%"; pylorus kept':'another review says "by 75%", keeping the pylorus'}</text>`}
    else if(p===2){const lw=N?118:150,sc=(iw-lw-20)/200;
      s+=`<text x="${f1(ix)}" y="${f1(y+24)}" class="t-xs" style="fill:var(--ink);font-weight:700">limb lengths in the YOMEGA trial</text>`;
      [['alimentary (Roux) limb',150,'var(--gut)','150 cm','food'],['biliary limb',50,'var(--gip)','50 cm','juices'],['common channel',0,'','the rest','both']].forEach((r,i)=>{
        const yy=y+(N?40:34)+i*(N?30:22),grow=clamp(m*1.6-i*.3);
        s+=`<text x="${f1(ix)}" y="${f1(yy+12)}" class="t-xs" style="fill:var(--ink)">${r[0]}</text>`;
        if(r[1]){s+=`<rect x="${f1(ix+lw)}" y="${f1(yy+2)}" width="${f1(r[1]*sc*grow)}" height="14" rx="5" style="fill:${r[2]};stroke:var(--gut-line)"/>`;
          if(grow>.95)s+=`<text x="${f1(ix+lw+r[1]*sc+6)}" y="${f1(yy+13)}" class="t-xs" style="fill:var(--ink);font-weight:700">${r[3]}</text>`}
        else s+=`<rect x="${f1(ix+lw)}" y="${f1(yy+2)}" width="${f1((iw-lw-60)*grow)}" height="14" rx="5" style="fill:none;stroke:var(--gut-line);stroke-dasharray:4 3"/><text x="${f1(ix+iw)}" y="${f1(yy+13)}" class="t-xs t-end" style="opacity:${f1(grow)}">${r[3]}</text>`});
      s+=`<text x="${f1(ix)}" y="${f1(y+h-12)}" class="t-xs">the gastric pouch volume is not given in our sources</text>`}
    else if(p===3){const c1=x+(N?168:200),c2=x+(N?286:320);
      s+=`<text x="${f1(ix)}" y="${f1(y+24)}" class="t-xs" style="fill:var(--ink);font-weight:700">same weight lost, different signals</text>`;
      s+=`<text x="${f1(c1)}" y="${f1(y+(N?44:40))}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">after bypass</text><text x="${f1(c2)}" y="${f1(y+(N?44:40))}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">after band</text>`;
      [['glp1','GLP-1 after meals'],['pyy','PYY after meals'],['insulin','early insulin']].forEach((r,i)=>{const yy=y+(N?64:58)+i*(N?22:18),op=clamp(u*3-i*.5);
        s+=hormoneDot(ix+6,yy-3,r[0],{r:4.5})+`<text x="${f1(ix+18)}" y="${f1(yy+1)}" class="t-xs" style="fill:var(--ink)">${r[1]}</text>`;
        s+=arrow(c1,yy-3,1,HORMONE_INFO[r[0]].col,op)+`<g style="opacity:${f1(op)}">${arrow(c2,yy-3,0,'',1)}</g>`});
      s+=`<text x="${f1(ix)}" y="${f1(y+h-12)}" class="t-xs">le Roux 2006; arrows: direction only</text>`}
    else{const tg=[['Gut hormones in people','Established','var(--good-soft)','var(--good)'],['Bile acids and FXR (mice)','Early evidence','var(--warn-soft)','var(--warn)'],['Microbiome (mouse transfer)','Hypothesis','var(--hl-soft)','var(--hl)']];
      tg.forEach((r,i)=>{const yy=y+14+i*((h-28)/3),op=clamp(u*3-i*.6),hh=(h-28)/3-8;
        s+=`<g style="opacity:${f1(op)}"><rect x="${f1(ix)}" y="${f1(yy)}" width="${f1(iw)}" height="${f1(hh)}" rx="9" style="fill:${r[2]}"/><text x="${f1(ix+10)}" y="${f1(yy+hh/2+4)}" class="t-xs" style="fill:var(--ink);font-weight:700">${r[0]}</text><text x="${f1(ix+iw-10)}" y="${f1(yy+hh/2+4)}" class="t-xs t-end" style="fill:${r[3]};font-weight:700">${r[1].toUpperCase()}</text></g>`})}
    return s}
  function draw(t){
    const N=vb(svg,'720 380','400 510');
    const p=phaseOf(SU_STEPS,t),P=SU_STEPS[p],nx=SU_STEPS[p+1],u=clamp((t-P.from)/((nx?nx.from:1)-P.from));
    const L=N?{gx:8,gy:62,gs:1,bx:300,by:58,bs:.56,tx:16,ty:24,rx:214,ry:150,rh:34,sx:14,sy:344,sw:372,sh:154}
             :{gx:24,gy:34,gs:1.2,bx:600,by:62,bs:.66,tx:300,ty:36,rx:300,ry:96,rh:27,sx:300,sy:238,sw:410,sh:128};
    let variant='normal',morph=0;
    if(p===1){variant='sleeve';morph=ease(ramp(t,.19,.31))}
    else if(p>=2){variant='bypass';morph=p===2?ease(ramp(t,.38,.5)):1}
    const pulse=.5+.5*Math.sin(t*90);
    const glow={stomach:p===0?.75:p===1?lerp(.75,.12,morph):.35,ileum:p<2?.3:p===2?lerp(.3,.7,morph):.55+.4*pulse,pancreas:p>=3?.4+.5*pulse:0};
    const food=(t*8)%1;
    const g=gutTract(L.gx,L.gy,L.gs,{variant,morph,food:food<.97?food:null,glow,labels:true,fill:p===0?.35:0});
    let s=g.svg;const A=g.at;
    /* operation labels on the gut */
    if(p===1&&morph>.5)s+=kitLabel(A.stomach[0]+4,A.stomach[1]-14,'removed part (dashed)',{a:'m'});
    if(p>=2&&morph>.6){const op=ramp(morph,.6,1);
      s+=`<g style="opacity:${f1(op)}">`+kitLabel(A.pouch[0]+14,A.pouch[1]-2,'pouch')+kitLabel(A.join[0]+10,A.join[1]-9,'join')+`<circle cx="${f1(A.join[0])}" cy="${f1(A.join[1])}" r="7" style="fill:none;stroke:var(--ink);stroke-width:1.2;stroke-dasharray:2 2"/>`;
      if(!N||p===2)s+=kitLabel(A.duo[0]-2,A.duo[1]+30,'biliary limb',{a:'e'});
      s+='</g>'}
    /* bile acids and microbes */
    if(p===4){const bu=ramp(u,0,.4);
      const bp=polyAt([A.duo,[lerp(A.duo[0],A.join[0],.5),lerp(A.duo[1],A.join[1],.5)+10*L.gs],A.join]);
      for(let i=0;i<6;i++){const q=bp(((t*5)+i/6)%1);s+=`<path d="M${f1(q[0])} ${f1(q[1]-5)}Q${f1(q[0]+4)} ${f1(q[1]+1)} ${f1(q[0])} ${f1(q[1]+3)}Q${f1(q[0]-4)} ${f1(q[1]+1)} ${f1(q[0])} ${f1(q[1]-5)}Z" style="fill:var(--gold);stroke:var(--panel);stroke-width:.8;opacity:${f1(bu)}"/>`}
      const rr=rng(9),cx=A.colon[0],cy=A.colon[1];
      for(let i=0;i<9;i++){const a=rr()*6.28,d=rr()*16*L.gs,x=cx+Math.cos(a)*d*.5,y=cy+Math.sin(a)*d*2+Math.sin(t*40+i)*2;
        s+=`<rect x="${f1(x-4)}" y="${f1(y-2)}" width="8" height="4" rx="2" transform="rotate(${f1(rr()*180)} ${f1(x)} ${f1(y)})" style="fill:var(--macro);opacity:${f1(ramp(u,.2,.6))}"/>`}
      s+=`<g style="opacity:${f1(ramp(u,.1,.4))}">`+kitLabel(A.colon[0]-6,A.colon[1]+40*L.gs,'gut microbes change',{a:N?'':'m'})+kitLabel(A.join[0]+10,A.join[1]-24,'bile acids rise (mice)')+'</g>'}
    /* brain */
    const br=brainHypothalamus(L.bx,L.by,L.bs,{inset:false,pomc:p>=2?.4+.4*pulse*(p>=3?1:0):.2});s+=br.svg;
    s+=`<text x="${f1(L.bx+40*L.bs)}" y="${f1(L.by-6)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">brain</text>`;
    /* hormone dots travelling to the brain */
    const hy=br.at.hypo;
    const lane=(src)=>N?polyAt([src,[200,140],[270,128],hy]):polyAt([src,[288,224],[560,222],[612,180],hy]);
    const dots=[];
    if(p<=1){const n=p===0?4:Math.round(4*(1-morph*.75));for(let i=0;i<n;i++)dots.push(['ghrelin',A.stomach,i/4])}
    if(p>=2){const n=p===2?Math.round(4*morph):6;for(let i=0;i<n;i++)dots.push([i%2?'pyy':'glp1',A.ileum,i/Math.max(n,1)])}
    if(p===0)for(let i=0;i<2;i++)dots.push([i?'pyy':'glp1',A.ileum,i/2+.25]);
    dots.forEach(d=>{const f=lane(d[1]),q=f((t*6+d[2])%1);s+=hormoneDot(q[0],q[1],d[0],{r:4.5})});
    /* title */
    const T=SU_TITLE[p];
    s+=`<text x="${L.tx}" y="${L.ty}" class="t-big" style="font-size:${N?17:19}px">${T[0]}</text><text x="${L.tx}" y="${L.ty+(N?17:20)}" class="t-sm">${T[1]}</text>`;
    /* hormone rows */
    const R=SU_HROWS[p];
    R.forEach((r,i)=>{const y=L.ry+i*L.rh,op=p===4?.55:1,col=HORMONE_INFO[r[0]].col;
      s+=hormoneDot(L.rx+6,y,r[0],{r:5,op});
      s+=`<text x="${L.rx+18}" y="${y+4}" class="t-lbl" style="font-size:12px;opacity:${op}">${r[1]}</text>`;
      if(N){s+=arrow(L.rx+92,y,r[2],col,op*clamp(u*4))+`<text x="${L.rx}" y="${y+19}" class="t-xs" style="fill:var(--ink);opacity:${op}">${r[3]}</text>`}
      else s+=arrow(L.rx+86,y,r[2],col,op*clamp(u*4))+`<text x="${L.rx+102}" y="${y+4}" class="t-xs" style="fill:var(--ink);opacity:${op}">${r[3]}</text>`});
    /* stat box */
    s+=stat(p,u,morph,L.sx,L.sy,L.sw,L.sh,N);
    svg.innerHTML=s;
    setSt(p);note.innerHTML=noteHTML(P);
  }
  const stop=playWire(rg,$('#suPlay'),draw,26000,'Replay','surgery');
  const setSt=stepWire($('#suSteps'),SU_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- procedure explorer ---------- */
  const px=$('#suPx'),pr=$('#suPxT'),pb=$('#suPxBtns'),pn=$('#suPxNote');let pv='sleeve';
  pb.innerHTML=Object.keys(SU_PX).map(k=>`<button class="btn" data-px="${k}" aria-pressed="${k===pv}">${SU_PX[k].lab}</button>`).join('');
  function drawPx(t){
    const N=vb(px,'720 340','400 620'),D=SU_PX[pv];
    const L=N?{gx:96,gy:16,gs:1,lx:16,ly:300,lw:368,lh:40,lg:8}:{gx:24,gy:18,gs:1.12,lx:300,ly:20,lw:400,lh:42,lg:9};
    const g=gutTract(L.gx,L.gy,L.gs,{variant:pv,morph:1,food:t>0&&t<1?t:null,labels:true,fill:.3});
    let s=g.svg;
    const passed=D.pass.map((v,i)=>v>0?i:-1).filter(i=>i>=0),ci=passed[Math.min(passed.length-1,Math.floor(t*passed.length))];
    SU_SEGS.forEach((nm,i)=>{const y=L.ly+i*(L.lh+L.lg),v=D.pass[i],cur=i===ci&&t>0&&t<1,done=passed.indexOf(i)>=0&&passed.indexOf(i)<passed.indexOf(ci);
      const fill=v===0?'var(--panel)':cur?'var(--tx-soft)':'var(--panel-2)',stroke=cur?'var(--tx)':'var(--line)';
      s+=`<rect x="${L.lx}" y="${y}" width="${L.lw}" height="${L.lh}" rx="10" style="fill:${fill};stroke:${stroke};stroke-width:${cur?2:1}${v===0?';stroke-dasharray:5 4':''}"/>`;
      s+=`<circle cx="${L.lx+18}" cy="${y+L.lh/2}" r="6" style="fill:${v===0?'none':done||cur?'var(--gut-line)':'var(--gut)'};stroke:var(--gut-line);stroke-width:1.4${v===0?';stroke-dasharray:2 2':''}"/>`;
      s+=`<text x="${L.lx+34}" y="${y+17}" class="t-lbl" style="font-size:12.5px;${v===0?'fill:var(--muted)':''}">${nm}</text>`;
      s+=`<text x="${L.lx+34}" y="${y+32}" class="t-xs" style="fill:${v===0?'var(--muted)':'var(--ink)'}">${D.how[i]}${v>0&&v<1?' (part)':''}</text>`;
      if(i<SU_SEGS.length-1)s+=`<path d="M${L.lx+18} ${y+L.lh/2+7}V${y+L.lh+L.lg+L.lh/2-7}" style="stroke:var(--gut-line);stroke-width:1.4;opacity:.5"/>`});
    px.innerHTML=s;
  }
  const stopPx=playWire(pr,$('#suPxPlay'),drawPx,7000,'Replay','surgery');
  pb.addEventListener('click',e=>{const b=e.target.closest('[data-px]');if(!b)return;pv=b.dataset.px;
    $$('[data-px]',pb).forEach(x=>x.setAttribute('aria-pressed',x===b));pn.innerHTML=noteHTML(SU_PX[pv].note);stopPx();drawPx(+pr.value)});
  pn.innerHTML=noteHTML(SU_PX[pv].note);drawPx(+pr.value);

  /* ---------- SOS weight curves ---------- */
  const so=$('#suSos'),sr=$('#suSosT'),sbt=$('#suSosBtns'),sread=$('#suSosRead');
  const on={};SU_SOS.forEach(S=>on[S.id]=!!S.on);
  sbt.innerHTML=SU_SOS.map(S=>`<button class="btn" data-sos="${S.id}" aria-pressed="${on[S.id]}"><span class="su-key" style="border-top-color:${S.col};border-top-style:${S.dash?'dashed':'solid'}"></span>${S.lab}</button>`).join('');
  function drawSos(t){
    const N=vb(so,'720 330','400 380'),yr=20*t;
    const L=N?{x:46,y:30,w:330,h:290}:{x:60,y:28,w:600,h:252};
    const ax=curveAxes(L.x,L.y,L.w,L.h,{x0:0,x1:20,y0:-35,y1:5,xt:[0,2,5,10,15,20],yt:[-30,-20,-10,0],yfmt:v=>(v>0?'+':v<0?'−':'')+Math.abs(v)+'%',xfmt:v=>v+(v===20?' y':''),ylabel:'weight change from baseline',xlabel:N?'':'years after surgery'});
    let s=ax.svg;
    s+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${f1(ax.Y(0))}" y2="${f1(ax.Y(0))}" style="stroke:var(--ink);stroke-width:1;opacity:.5"/>`;
    SU_SOS.forEach(S=>{if(!on[S.id])return;
      const last=S.P[S.P.length-1][0];
      s+=plotLine(S.P,ax.X,ax.Y,{col:S.col,lw:1.4,dash:S.dash||'3 3',smooth:true}).svg.replace('<path','<path opacity=".3"');
      const pl=plotLine(S.P,ax.X,ax.Y,{col:S.col,lw:3,dash:S.dash,smooth:true,upto:Math.min(yr,last)});s+=pl.svg;
      S.P.forEach(q=>{if(q[0]>yr+1e-6||q[0]===0)return;s+=`<circle cx="${f1(ax.X(q[0]))}" cy="${f1(ax.Y(q[1]))}" r="4.2" style="fill:${S.col};stroke:var(--panel);stroke-width:1.6"/>`});
      if(yr>=last-1e-6){const e=[ax.X(last),ax.Y(S.P[S.P.length-1][1])];
        const lbl=S.id==='all'?(N?'all':'all surgery'):S.id==='ctl'?'controls':S.id==='gbp'?'bypass':S.id==='vbg'?'VBG':'band';
        const end=last===20;s+=kitLabel(end?e[0]-4:e[0]+8,e[1]+(S.id==='ctl'?-8:S.id==='all'?14:4),lbl+' '+(S.P[S.P.length-1][1]>0?'+':S.P[S.P.length-1][1]<0?'−':'')+Math.abs(S.P[S.P.length-1][1])+'%',{a:end?'e':''})}});
    s+=`<line x1="${f1(ax.X(yr))}" x2="${f1(ax.X(yr))}" y1="${L.y}" y2="${L.y+L.h}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/>`;
    s+=`<text x="${f1(Math.min(ax.X(yr)+6,L.x+L.w-60))}" y="${L.y+14}" class="t-sm" style="fill:var(--ink);font-weight:700">year ${yr.toFixed(yr<10?1:0)}</text>`;
    so.innerHTML=s;
    const shown=SU_SOS.filter(S=>on[S.id]);
    sread.innerHTML=shown.map(S=>{let q=null;S.P.forEach(p=>{if(p[0]<=yr+1e-6&&p[0]>0)q=p});
      return `<span><b>${S.lab}:</b> ${q?(q[1]>0?'+':q[1]<0?'−':'')+Math.abs(q[1])+'% at '+(q[0]===1.5?'maximum (1 to 2 years)':q[0]+' years'):'no published point yet'}</span>`}).join('');
  }
  playWire(sr,$('#suSosPlay'),drawSos,12000,'Replay','surgery');
  sbt.addEventListener('click',e=>{const b=e.target.closest('[data-sos]');if(!b)return;const k=b.dataset.sos;on[k]=!on[k];
    if(!Object.values(on).some(Boolean))on[k]=true;b.setAttribute('aria-pressed',on[k]);drawSos(+sr.value)});
  drawSos(+sr.value);

  /* ---------- STAMPEDE bars ---------- */
  const st=$('#suSt'),stb=$('#suStBtns');let sm='a1c',grow=1,stopG=null;
  stb.innerHTML=Object.keys(SU_ST).map(k=>`<button class="btn" data-stm="${k}" aria-pressed="${k===sm}">${SU_ST[k].lab}</button>`).join('');
  function drawSt(){
    const N=vb(st,'720 250','400 300'),M=SU_ST[sm];
    const L=N?{x:16,y:44,w:368,bh:56,gap:22,lw:0}:{x:220,y:46,w:420,bh:42,gap:20,lw:200};
    let s=`<text x="16" y="22" class="t-xs" style="fill:var(--ink);font-weight:700">${M.head}</text>`;
    M.v.forEach((v,i)=>{const y=L.y+i*(L.bh+L.gap),a=Math.abs(v)/M.max*grow,col=i===0?'var(--muted)':i===1?'var(--brand)':'var(--tx)';
      const by=N?y+18:y,bh=N?L.bh-22:L.bh;
      s+=`<text x="${N?L.x:L.x-12}" y="${N?y+12:y+bh/2+4}" class="t-lbl ${N?'':'t-end'}" style="font-size:12.5px">${SU_ARMS[i]}</text>`;
      s+=`<rect x="${L.x}" y="${f1(by)}" width="${f1(L.w)}" height="${f1(bh)}" rx="7" style="fill:var(--field);stroke:var(--line)"/>`;
      s+=`<rect x="${L.x}" y="${f1(by)}" width="${f1(Math.max(2,L.w*a))}" height="${f1(bh)}" rx="7" style="fill:${col}"/>`;
      s+=`<text x="${f1(L.x+L.w*a+8)}" y="${f1(by+bh/2+5)}" class="t-big" style="font-size:16px">${M.fmt(Math.round(v*grow))}</text>`});
    s+=N?`<text x="16" y="276" class="t-xs">150 people with type 2 diabetes, BMI 27 to 43;</text><text x="16" y="290" class="t-xs">group results at 5 years</text>`:`<text x="${L.x}" y="240" class="t-xs">150 people with type 2 diabetes, BMI 27 to 43; group results at 5 years</text>`;
    st.innerHTML=s}
  stb.addEventListener('click',e=>{const b=e.target.closest('[data-stm]');if(!b)return;sm=b.dataset.stm;
    $$('[data-stm]',stb).forEach(x=>x.setAttribute('aria-pressed',x===b));if(stopG)stopG();grow=0;drawSt();stopG=animate(700,q=>{grow=ease(q);drawSt()},()=>{stopG=null})});
  drawSt();
  const prevR=redraws.surgery;redraws.surgery=()=>{prevR&&prevR();drawSt()};

  /* ---------- eligibility explainer ---------- */
  const eb=$('#suBmi'),em=$('#suMet'),ea=$('#suAsian'),eo=$('#suElig');
  function elig(){
    const b=+eb.value,met=em.checked,as=ea.checked;let a,ac,n,nc;
    if(b>=35){a='ASMBS/IFSO 2022: surgery "is recommended for individuals with a body mass index (BMI) >35 kg/m², regardless of presence, absence, or severity of co-morbidities".';ac='yes'}
    else if(as&&b>=27.5){a='ASMBS/IFSO 2022: in Asian populations, "individuals with BMI >27.5 kg/m² should be offered" surgery.';ac='yes'}
    else if(b>=30&&met){a='ASMBS/IFSO 2022: surgery "should be considered for individuals with metabolic disease and BMI of 30-34.9 kg/m²".';ac='maybe'}
    else if(b>=30){a='ASMBS/IFSO 2022 names BMI 30 to 34.9 only together with metabolic disease (or above 27.5 in Asian populations).';ac='out'}
    else if(as&&b>=25){a='ASMBS/IFSO 2022: in Asian populations a BMI above 25 suggests clinical obesity; the surgery threshold as published is above 27.5.';ac='out'}
    else{a='Below the BMI thresholds in the ASMBS/IFSO 2022 statement.';ac='out'}
    if(b>=40){n='1991 NIH: within the old threshold of BMI above 40.';nc='yes'}
    else if(b>=35&&met){n='1991 NIH: within the old threshold of BMI above 35 with comorbidities.';nc='yes'}
    else if(b>=35){n='1991 NIH: outside the old threshold, which required comorbidities between BMI 35 and 40.';nc='out'}
    else{n='1991 NIH: outside the old thresholds (BMI above 40, or above 35 with comorbidities).';nc='out'}
    eo.innerHTML=`<div class="verdict ${ac}"><span class="kicker">2022 statement, as published</span><br>${a} <sup class="c" data-ref="Eisenberg2022ASMBS" title="Source 132"><a href="/obesity/sources/#src-Eisenberg2022ASMBS">132</a></sup></div><div class="verdict ${nc}"><span class="kicker">1991 thresholds, for comparison</span><br>${n} <sup class="c" data-ref="Eisenberg2022ASMBS,Arterburn2020JAMA" title="Source 29,132"><a href="/obesity/sources/#src-Eisenberg2022ASMBS">29,132</a></sup></div>`}
  [eb,em,ea].forEach(el=>el.addEventListener('change',elig));elig();
};
/* =============== 3.7 Life after surgery =============== */
/* Main player: a logarithmic time axis from the day of surgery to 20 years. Each lane is a window when a problem is
   most often met; the lanes a moment falls in light up. Windows are schematic except where the notes cite a time. */
const AF_LN=Math.log(7301);
const afDay=t=>Math.exp(t*AF_LN)-1, afT=d=>Math.log(1+d)/AF_LN;
const AF_STEPS=[
 {from:0,at:.2,k:'Day 0 to 30',t:'The first month',
  txt:'In LABS (4776 first operations, 2005 to 2007), 30-day mortality after bypass or band was 0.3% and 4.3% had at least one major adverse outcome. <sup class="c" data-ref="Flum2009LABS" title="Source 161"><a href="/obesity/sources/#src-Flum2009LABS">161</a></sup> Current perioperative mortality is reported at 0.03% to 0.2%. <sup class="c" data-ref="Arterburn2020JAMA,Eisenberg2022ASMBS" title="Source 29,132"><a href="/obesity/sources/#src-Arterburn2020JAMA">29,132</a></sup> A 2026 review gives leaks in about 1% after sleeve and 0.6% after bypass, early bleeding in 0.6 to 2.5% and 1 to 1.5%, and blood clots in veins in 0.3 to 2.4%; 70 to 80% of these clots are diagnosed after discharge. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> Signs of a leak can be vague: a fast heart rate that persists, fever, belly or shoulder pain and changes in breathing. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup>',
  pt:'Most people recover from the operation without serious problems. A fast heartbeat, fever, belly or shoulder pain or trouble breathing in the first weeks needs urgent care.',
  hook:'In 210 bypass patients, breathing difficulty and a heart rate above 120 were the most sensitive signs of a leak; a routine contrast swallow caught only 2 of 9 leaks. <sup class="c" data-ref="Hamilton2003" title="Source 213"><a href="/obesity/sources/#src-Hamilton2003">213</a></sup>'},
 {from:.386,at:.48,k:'Weeks to months',t:'Eating again, and dumping',
  txt:'Eating restarts in stages that each surgical programme sets; the 2019 perioperative guideline calls a team approach "mandatory", with attention to nutrition. <sup class="c" data-ref="Mechanick2020SOARD" title="Source 364"><a href="/obesity/sources/#src-Mechanick2020SOARD">364</a></sup> Early dumping is reported in up to 40% and late dumping in up to 25%. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> An international consensus defines late dumping by a glucose nadir below 50 mg/dL, and early dumping by a rise in haematocrit above 3% or pulse above 10 beats a minute 30 minutes into a glucose test. Dietary adjustment is the first step; acarbose helps late dumping. <sup class="c" data-ref="Scarpellini2020" title="Source 493"><a href="/obesity/sources/#src-Scarpellini2020">493</a></sup>',
  pt:'After surgery, food can move into the gut faster than before. This can cause symptoms soon after eating (early dumping) or a drop in blood sugar later (late dumping). Changing what and how you eat is the first step, with your team.',
  hook:'Late dumping diagnostic nadir: glucose below 50 mg/dL; first-line treatment is dietary. <sup class="c" data-ref="Scarpellini2020" title="Source 493"><a href="/obesity/sources/#src-Scarpellini2020">493</a></sup>'},
 {from:.586,at:.62,k:'6 to 12 months',t:'Gallstones and ulcers',
  txt:'Gallstones form in about 10 to 50% after surgery, driven by rapid weight loss, typically in the first 6 to 12 months. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> In UPGRADE (985 randomised), ursodeoxycholic acid for 6 months did not significantly reduce symptomatic gallstone disease overall (6.5% versus 9.7%), but did in people without gallstones before bypass. <sup class="c" data-ref="Haal2021UPGRADE" title="Source 205"><a href="/obesity/sources/#src-Haal2021UPGRADE">205</a></sup> In 350 bypass patients, 6.6% developed a symptomatic marginal ulcer; smoking, corticosteroids and NSAIDs were risk factors. <sup class="c" data-ref="Coblijn2015" title="Source 88"><a href="/obesity/sources/#src-Coblijn2015">88</a></sup> Closing the mesenteric defects during bypass cut reoperation for small-bowel obstruction from 10.2% to 5.5% at 3 years. <sup class="c" data-ref="Stenberg2016Lancet" title="Source 523"><a href="/obesity/sources/#src-Stenberg2016Lancet">523</a></sup>',
  pt:'Gallstones are common in the first year, when weight falls fastest. Ulcers at the join are more likely with smoking and some painkillers, so check with your team before taking anti-inflammatory medicines.',
  hook:'Marginal ulcer after bypass: think smoking, NSAIDs, steroids. Internal hernia is reduced by closing mesenteric defects (HR 0.56). <sup class="c" data-ref="Coblijn2015,Stenberg2016Lancet" title="Source 88,523"><a href="/obesity/sources/#src-Coblijn2015">88,523</a></sup>'},
 {from:.664,at:.7,k:'Year 1 to 2',t:'New risks emerge',
  txt:'Post-bariatric hypoglycaemia typically presents more than 1 year after surgery, with symptoms such as confusion or seizures. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> In Sweden, hospitalisation for hypoglycaemia was 2.7 times as likely after gastric bypass, though only 0.2% were affected. <sup class="c" data-ref="Marsk2010" title="Source 355"><a href="/obesity/sources/#src-Marsk2010">355</a></sup> In LABS-2, alcohol use disorder symptoms were 7.6% the year before surgery, 7.3% at 1 year and 9.6% in the second year; bypass doubled the odds compared with a band (AOR 2.07). <sup class="c" data-ref="King2012JAMA" title="Source 285"><a href="/obesity/sources/#src-King2012JAMA">285</a></sup> Median maximum weight loss after bypass, 37.4%, came at a median of 2 years. <sup class="c" data-ref="King2018JAMA" title="Source 287"><a href="/obesity/sources/#src-King2018JAMA">287</a></sup>',
  pt:'Alcohol can hit harder after a bypass, and the risk of drinking problems goes up from the second year. Tell your team if drinking worries you.',
  hook:'Alcohol use disorder symptoms rise in the second year after bypass (9.6%), about twice the odds after a band. <sup class="c" data-ref="King2012JAMA" title="Source 285"><a href="/obesity/sources/#src-King2012JAMA">285</a></sup>'},
 {from:.741,at:.84,k:'Years 2 to 10',t:'Lifelong follow-up',
  txt:'After the lowest weight, some weight usually returns: in 1406 LABS-2 bypass patients, median regain rose from 9.5% of the maximum lost 1 year after the nadir to 26.8% at 5 years. <sup class="c" data-ref="King2018JAMA" title="Source 287"><a href="/obesity/sources/#src-King2018JAMA">287</a></sup> This is biology, not a failure of effort, and further treatment can help. Cumulative new alcohol use disorder symptoms reached 20.8% after bypass versus 11.3% after band by 5 years. <sup class="c" data-ref="King2017SOARD" title="Source 286"><a href="/obesity/sources/#src-King2017SOARD">286</a></sup> Vitamin B12 deficiency affects 19 to 35% at 5 years after bypass and biliopancreatic diversion, and iron deficiency more than 30%. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> At 10 years, endoscopic oesophagitis was found in 31% after sleeve versus 7% after bypass. <sup class="c" data-ref="Salminen2022SLEEVEPASS" title="Source 488"><a href="/obesity/sources/#src-Salminen2022SLEEVEPASS">488</a></sup>',
  pt:'You need vitamins and minerals for life, and regular blood tests. Some weight often comes back after the first two years; that is the body\'s biology, and there are treatments that can help.',
  hook:'Regain measured as a percentage of maximum weight lost best tracked the return of diabetes, high blood pressure and lower quality of life. <sup class="c" data-ref="King2018JAMA" title="Source 287"><a href="/obesity/sources/#src-King2018JAMA">287</a></sup>'},
 {from:.922,at:.97,k:'The long view',t:'Life expectancy',
  txt:'In SOS, with a median follow-up of 24 years, adjusted median life expectancy was 3.0 years longer after surgery than with usual care, but 5.5 years shorter than in the general population. Overall mortality hazard ratio was 0.77; 90-day postoperative mortality was 0.2%. <sup class="c" data-ref="Carlsson2020NEJM" title="Source 63"><a href="/obesity/sources/#src-Carlsson2020NEJM">63</a></sup> These are group statistics from a study in which most people had operations now rarely used. <sup class="c" data-ref="Sjostrom2013JIM" title="Source 514"><a href="/obesity/sources/#src-Sjostrom2013JIM">514</a></sup>',
  pt:'On average, people who had surgery in this study lived about 3 years longer than similar people who did not. That is an average for a group, not a promise for any one person.',
  hook:'SOS life expectancy: +3.0 years versus usual care, but −5.5 years versus the general population. <sup class="c" data-ref="Carlsson2020NEJM" title="Source 63"><a href="/obesity/sources/#src-Carlsson2020NEJM">63</a></sup>'}
];
