/* micronutrient explorer: published figures by nutrient; p = operations a row is about */
const AF_NU={
 iron:{lab:'Iron',rows:[
   {l:'Anaemia within 2 years, all operations',lo:33,hi:49,p:'all'},
   {l:'Anaemia after sleeve (about)',lo:17,hi:17,p:'sleeve'},
   {l:'Anaemia after bypass or biliopancreatic diversion',lo:45,hi:50,p:'bypass switch'},
   {l:'Low ferritin at 5 years (more than)',lo:30,hi:30,p:'all'},
   {l:'Low ferritin 5 y after bypass: adolescents',lo:48,hi:48,p:'bypass'},
   {l:'Low ferritin 5 y after bypass: adults',lo:29,hi:29,p:'bypass'}],
  note:{k:'Iron',t:'Anaemia is common',
   txt:'Anaemia affects 33 to 49% within 2 years of surgery: about 17% after sleeve and 45 to 50% after bypass or biliopancreatic diversion; low ferritin occurs in more than 30% at 5 years. When iron deficiency is established, oral iron may not be enough and intravenous iron may be needed. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> Five years after bypass, low ferritin was found in 48% of adolescents versus 29% of adults. <sup class="c" data-ref="Inge2019NEJM" title="Source 246"><a href="/obesity/sources/#src-Inge2019NEJM">246</a></sup> Calcium interferes with the absorption of iron, zinc and copper, so iron and calcium supplements are taken apart. <sup class="c" data-ref="Lupoli2017,Kim2026Complications" title="Source 284,345"><a href="/obesity/sources/#src-Lupoli2017">284,345</a></sup>',
   pt:'Low iron is one of the most common problems after surgery. Blood tests pick it up; your team decides the treatment.',
   hook:'Iron and calcium supplements are separated in time, because calcium blocks iron absorption. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup>'}},
 b12:{lab:'Vitamin B12',rows:[{l:'Deficiency at 5 years after bypass or BPD',lo:19,hi:35,p:'bypass switch'}],
  note:{k:'Vitamin B12',t:'Less acid, less intrinsic factor',
   txt:'Vitamin B12 deficiency affects 19 to 35% at 5 years after biliopancreatic diversion and bypass, because the duodenum is bypassed and gastric acid and intrinsic factor fall. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> A 2026 review cites ASMBS guidance for a bariatric multivitamin with at least 350 to 1000 μg of vitamin B12 (quoted, not an instruction). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup>',
   pt:'After a bypass the body absorbs less vitamin B12 from food, so supplements and regular checks are part of lifelong care.',
   hook:'B12 deficiency after bypass: duodenum bypassed, less gastric acid and intrinsic factor. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup>'}},
 vitd:{lab:'Vitamin D',rows:[{l:'Vitamin D below 20 ng/mL, operated patients (about)',lo:60,hi:60,p:'all'}],
  note:{k:'Vitamin D',t:'Low in most',
   txt:'Vitamin D deficiency (below 20 ng/mL) is seen in about 60% of operated patients across studies. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> A 2026 review cites ASMBS guidance of at least 3000 IU a day of vitamin D, titrated to a 25-OH vitamin D level above 30 ng/mL (quoted, not an instruction). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> In Quebec, fracture risk after surgery was higher than in matched controls with obesity (RR 1.38); the increase was significant only after biliopancreatic diversion. <sup class="c" data-ref="Rousseau2016BMJ" title="Source 475"><a href="/obesity/sources/#src-Rousseau2016BMJ">475</a></sup>',
   pt:'Many people are low in vitamin D, which matters for bones. It is checked and topped up as your team advises.',
   hook:'After surgery the fracture pattern shifted from lower-limb fractures to upper limb, spine, pelvis, hip and femur. <sup class="c" data-ref="Rousseau2016BMJ" title="Source 475"><a href="/obesity/sources/#src-Rousseau2016BMJ">475</a></sup>'}},
 ca:{lab:'Calcium',rows:[],empty:'Our sources give no deficiency rate for calcium; its role is bone health and the supplement statements beside.',
  note:{k:'Calcium',t:'Bones, and timing',
   txt:'A 2026 review cites ASMBS guidance of 1200 to 1500 mg a day of elemental calcium, preferably citrate, in divided doses (quoted, not an instruction). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> Calcium interferes with absorption of iron, zinc and copper, so they are taken apart. <sup class="c" data-ref="Lupoli2017,Kim2026Complications" title="Source 284,345"><a href="/obesity/sources/#src-Lupoli2017">284,345</a></sup> Fracture risk rose after surgery in a Quebec study of 12,676 people (RR 1.38 versus controls with obesity). <sup class="c" data-ref="Rousseau2016BMJ" title="Source 475"><a href="/obesity/sources/#src-Rousseau2016BMJ">475</a></sup> ARMMS-T2D also found more fractures after surgery than with medical care. <sup class="c" data-ref="Courcoulas2024ARMMS" title="Source 100"><a href="/obesity/sources/#src-Courcoulas2024ARMMS">100</a></sup>',
   pt:'Calcium protects bones. It is usually taken at a different time from iron.',
   hook:'Calcium citrate in divided doses, separate from iron (as cited from ASMBS guidance). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup>'}},
 b1:{lab:'Thiamine (B1)',rows:[{l:'Thiamine deficiency after surgery (up to)',lo:0,hi:49,p:'all',upto:1}],
  note:{k:'Thiamine (vitamin B1)',t:'Vomiting is the warning',
   txt:'Thiamine deficiency can occur in up to 49% after surgery and, untreated, can lead to Wernicke-Korsakoff syndrome; persistent vomiting is a trigger. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> The ASMBS micronutrient guideline covers screening, prevention and repletion of B1 among other nutrients. <sup class="c" data-ref="Parrott2017ASMBS" title="Source 417"><a href="/obesity/sources/#src-Parrott2017ASMBS">417</a></sup>',
   pt:'Vomiting that keeps happening can drain vitamin B1 quickly, which can harm the brain and nerves. Tell your team promptly.',
   hook:'Thiamine deficiency with vomiting after surgery risks Wernicke-Korsakoff syndrome. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup>'}},
 fol:{lab:'Folate',rows:[],empty:'Our sources give no deficiency rate for folate after surgery; the published supplement statements are beside.',
  note:{k:'Folate',t:'Especially before pregnancy',
   txt:'A 2026 review cites ASMBS guidance for a bariatric multivitamin with 400 to 800 μg of folic acid (quoted, not an instruction). <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> A 2019 pregnancy consensus lists folic acid 5 mg in its minimum preconception supplement, and advises checking folate every trimester. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup> More in <a href="#pregnancy" data-go="pregnancy">Pregnancy &amp; fertility</a>.',
   pt:'Folate matters most if you might become pregnant. Talk to your team about timing and the special vitamins you will need.',
   hook:'Pregnancy after surgery: folate, B12, iron and vitamin A checked every trimester (2019 consensus). <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup>'}},
 vita:{lab:'Vitamin A',rows:[{l:'Deficiency 2 to 4 years after BPD',lo:61,hi:69,p:'switch'}],
  note:{k:'Vitamin A',t:'Most affected by diversion',
   txt:'Vitamin A deficiency was found in 61 to 69% at 2 to 4 years after biliopancreatic diversion. <sup class="c" data-ref="Lupoli2017" title="Source 345"><a href="/obesity/sources/#src-Lupoli2017">345</a></sup> In pregnancy after surgery, the 2019 consensus lists vitamin A as beta-carotene, because the retinol form is teratogenic. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup>',
   pt:'Fat-soluble vitamins such as A are hardest to absorb after the operations that bypass the most bowel.',
   hook:'Avoid retinol-form vitamin A in pregnancy after surgery; the consensus uses beta-carotene. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup>'}}
};
const AF_PROC={sleeve:'Sleeve',bypass:'Bypass',switch:'Diversion / duodenal switch'};

inits.aftersurgery=()=>{
  /* ---------- the timeline ---------- */
  const svg=$('#afSvg'),rg=$('#afT'),note=$('#afNote');
  function tiles(x,y,w,h,items,u){let s='';const n=items.length,tw=(w-(n-1)*8)/n;
    items.forEach((it,i)=>{const tx=x+i*(tw+8),op=clamp(.4+u*4-i*.4);
      s+=`<g style="opacity:${f1(op)}"><rect x="${f1(tx)}" y="${f1(y)}" width="${f1(tw)}" height="${f1(h)}" rx="10" style="fill:var(--panel);stroke:var(--line)"/>`;
      s+=`<text x="${f1(tx+9)}" y="${f1(y+26)}" class="t-big" style="font-size:19px;fill:var(--tx)">${it.v.replace('<','&lt;')}</text>`;
      it.l.forEach((ln,j)=>{s+=`<text x="${f1(tx+9)}" y="${f1(y+44+j*12)}" class="t-xs" style="fill:var(--ink)">${ln}</text>`});s+='</g>'});
    return s}
  function lifeExp(x,y,w,h,u,N){let s='';const X=v=>x+24+(w-48)*v/9,yy=y+(N?92:54),g=ease(clamp(u*1.6));
    s+=`<text x="${f1(x+12)}" y="${f1(y+20)}" class="t-xs" style="fill:var(--ink);font-weight:700">${N?'median life expectancy vs usual care':'median life expectancy, years more than usual care (SOS, median follow-up 24 years)'}</text>`;
    if(N)s+=`<text x="${f1(x+12)}" y="${f1(y+34)}" class="t-xs" style="fill:var(--ink);font-weight:700">(SOS, median follow-up 24 years)</text>`;
    s+=`<line x1="${f1(X(0))}" x2="${f1(X(9))}" y1="${f1(yy)}" y2="${f1(yy)}" class="axis"/>`;
    [0,3,6,9].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${f1(yy-3)}" y2="${f1(yy+3)}" class="axis"/><text x="${f1(X(v))}" y="${f1(yy+16)}" class="t-xs t-mid">${v?'+'+v+' y':'0'}</text>`});
    s+=`<rect x="${f1(X(0))}" y="${f1(yy-4)}" width="${f1((X(3)-X(0))*g)}" height="8" rx="4" style="fill:var(--tx)"/>`;
    s+=`<rect x="${f1(X(3))}" y="${f1(yy-4)}" width="${f1((X(8.5)-X(3))*clamp(g*2-1))}" height="8" rx="4" style="fill:none;stroke:var(--muted);stroke-dasharray:3 3"/>`;
    const mk=(v,t1,a,col,op,dy)=>`<g style="opacity:${f1(op)}"><circle cx="${f1(X(v))}" cy="${f1(yy)}" r="6" style="fill:${col};stroke:var(--panel);stroke-width:2"/><text x="${f1(X(v)+(a==='t-end'?6:a===''?-6:0))}" y="${f1(yy-12-dy)}" class="t-xs ${a}" style="fill:var(--ink);font-weight:700">${t1}</text></g>`;
    s+=mk(0,'usual care','',`var(--muted)`,1,0)+mk(3,'surgery: +3.0 y','t-mid',`var(--tx)`,clamp(g*2),N?14:0)+mk(8.5,'general population: 5.5 y more','t-end',`var(--ink)`,clamp(g*2-1),0);
    return s}
  function draw(t){
    const N=vb(svg,'720 400','400 600');
    const p=phaseOf(AF_STEPS,t),P=AF_STEPS[p],nx=AF_STEPS[p+1],u=clamp((t-P.from)/((nx?nx.from:1)-P.from)),d=afDay(t);
    const L=N?{ax:22,aw:356,ay:62,ly:80,lh:33,lx:22,sx:14,sy:420,sw:372,sh:170}:{ax:226,aw:476,ay:56,ly:70,lh:22,lx:20,sx:20,sy:302,sw:682,sh:90};
    const X=dd=>L.ax+L.aw*afT(dd);
    const dTxt=d<1?'Day of surgery':d<60?`Day ${Math.round(d)}`:d<730?`Month ${Math.round(d/30.44)}`:`Year ${(d/365.25).toFixed(1)}`;
    let s=`<text x="${N?22:20}" y="${N?30:30}" class="t-big" style="font-size:22px">${dTxt}</text><text x="${N?378:702}" y="30" class="t-sm t-end" style="fill:var(--ink)">${P.k}</text>`;
    /* axis */
    s+=`<line x1="${L.ax}" x2="${L.ax+L.aw}" y1="${L.ay}" y2="${L.ay}" class="axis"/>`;
    AF_TICKS.forEach(k=>{if(N&&k[2])return;const x=X(k[0]);s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${L.ay-4}" y2="${L.ay}" class="axis"/><text x="${f1(x)}" y="${L.ay-8}" class="t-xs ${k[0]===0?'':'t-mid'}">${k[1]}</text>`;
      s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${L.ly-4}" y2="${L.ly+AF_LANES.length*L.lh}" class="grid"/>`});
    /* lanes */
    AF_LANES.forEach((ln,i)=>{const y=L.ly+i*L.lh,a=X(ln[1]),b=X(ln[2]),on=d>=ln[1]&&d<=ln[2],past=d>ln[2];
      const by=N?y+14:y+5,bh=N?10:12,ly=N?y+10:y+15;
      s+=`<text x="${N?L.lx:L.ax-10}" y="${ly}" class="t-xs ${N?'':'t-end'}" style="fill:var(--ink);font-weight:${on?700:500};opacity:${on?1:.62}">${ln[0]}</text>`;
      s+=`<rect x="${f1(a)}" y="${by}" width="${f1(Math.max(4,b-a))}" height="${bh}" rx="${bh/2}" style="fill:${ln[3]};opacity:${on?.28:.13}"/>`;
      if(d>=ln[1]){const e=Math.min(X(d),b);s+=`<rect x="${f1(a)}" y="${by}" width="${f1(Math.max(4,e-a))}" height="${bh}" rx="${bh/2}" style="fill:${ln[3]};opacity:${past?.45:.9}"/>`}
      if(on)s+=`<circle cx="${f1(X(d))}" cy="${by+bh/2}" r="${bh/2+2.5}" style="fill:${ln[3]};stroke:var(--panel);stroke-width:2"/>`});
    /* now line */
    const nxp=X(d);s+=`<line x1="${f1(nxp)}" x2="${f1(nxp)}" y1="${L.ay}" y2="${L.ly+AF_LANES.length*L.lh}" style="stroke:var(--ink);stroke-width:1.4;stroke-dasharray:4 3"/><path d="M${f1(nxp-5)} ${L.ay-1}L${f1(nxp+5)} ${L.ay-1}L${f1(nxp)} ${L.ay+6}Z" style="fill:var(--ink)"/>`;
    /* bottom box */
    s+=`<rect x="${L.sx}" y="${L.sy}" width="${L.sw}" height="${L.sh}" rx="12" style="fill:var(--panel-2);stroke:var(--line)"/>`;
    if(AF_TILES[p]){const T=AF_TILES[p];
      if(N){T.forEach((it,i)=>{const ty=L.sy+10+i*52,op=clamp(.4+u*4-i*.4);s+=`<g style="opacity:${f1(op)}"><rect x="${L.sx+10}" y="${ty}" width="${L.sw-20}" height="46" rx="10" style="fill:var(--panel);stroke:var(--line)"/><text x="${L.sx+20}" y="${ty+30}" class="t-big" style="font-size:19px;fill:var(--tx)">${it.v.replace('<','&lt;')}</text>`+it.l.map((ln,j)=>`<text x="${L.sx+140}" y="${ty+20+j*13}" class="t-xs" style="fill:var(--ink)">${ln}</text>`).join('')+'</g>'})}
      else s+=tiles(L.sx+10,L.sy+10,L.sw-20,L.sh-20,T,u)}
    else s+=lifeExp(L.sx,L.sy,L.sw,L.sh,u,N);
    svg.innerHTML=s;
    setSt(p);note.innerHTML=noteHTML(P);
  }
  const stop=playWire(rg,$('#afPlay'),draw,26000,'Replay','aftersurgery');
  const setSt=stepWire($('#afSteps'),AF_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- micronutrient explorer ---------- */
  const nv=$('#afNu'),nb=$('#afNuBtns'),ps=$('#afProc'),nn=$('#afNuNote');let nu='iron',g=1,stopG=null;
  nb.innerHTML=Object.keys(AF_NU).map(k=>`<button class="btn" data-nu="${k}" aria-pressed="${k===nu}">${AF_NU[k].lab}</button>`).join('');
  function drawNu(){
    const N=vb(nv,'720 330','400 570'),D=AF_NU[nu],pr=ps.value;
    const L=N?{gx:120,gy:30,gs:.8,rx:16,ry:270,rw:300,rh:46}:{gx:16,gy:28,gs:1,rx:252,ry:44,rw:400,rh:46};
    const gt=gutTract(L.gx,L.gy,L.gs,{variant:pr,morph:1,labels:!N});
    let s=gt.svg+`<text x="${f1(N?200:L.gx+100*L.gs)}" y="${f1(N?16:L.gy+278*L.gs)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">${AF_PROC[pr]}</text>`;
    s+=`<text x="${L.rx}" y="${L.ry-18}" class="t-xs" style="fill:var(--ink);font-weight:700">${D.lab}: published figures (% of people)</text>`;
    if(!D.rows.length){s+=`<rect x="${L.rx}" y="${L.ry-4}" width="${N?368:440}" height="70" rx="10" style="fill:var(--panel-2);stroke:var(--line);stroke-dasharray:4 3"/>`;
      const words=D.empty.split(' ');let line='',ls=[];words.forEach(w=>{if((line+' '+w).length>(N?56:68)){ls.push(line);line=w}else line=(line?line+' ':'')+w});ls.push(line);
      ls.forEach((l,i)=>{s+=`<text x="${L.rx+12}" y="${L.ry+20+i*14}" class="t-xs" style="fill:var(--ink)">${l}</text>`})}
    D.rows.forEach((r,i)=>{const y=L.ry+i*L.rh,rel=r.p==='all'||r.p.split(' ').indexOf(pr)>=0,op=rel?1:.32,X=v=>L.rx+L.rw*v/100;
      s+=`<g style="opacity:${op}"><text x="${L.rx}" y="${y+8}" class="t-xs" style="fill:var(--ink)">${r.l}${rel?'':' (other operation)'}</text>`;
      s+=`<rect x="${L.rx}" y="${y+14}" width="${L.rw}" height="14" rx="7" style="fill:var(--field);stroke:var(--line)"/>`;
      const lo=r.upto?0:r.lo;
      if(lo>0)s+=`<rect x="${L.rx}" y="${y+14}" width="${f1((X(lo)-L.rx)*g)}" height="14" rx="7" style="fill:var(--brand)"/>`;
      if(r.hi>r.lo||r.upto)s+=`<rect x="${f1(X(lo))}" y="${y+14}" width="${f1((X(r.hi)-X(lo))*g)}" height="14" rx="4" style="fill:var(--brand);opacity:.4"/>`;
      s+=`<text x="${f1(X(r.hi)+8)}" y="${y+26}" class="t-lbl" style="font-size:12.5px">${r.upto?'up to '+r.hi:r.hi>r.lo?r.lo+'-'+r.hi:r.lo}%</text></g>`});
    if(D.rows.length)s+=`<text x="${L.rx}" y="${f1(L.ry+D.rows.length*L.rh+8)}" class="t-xs">solid: published value; pale: published range</text>`;
    nv.innerHTML=s}
  function setNu(){nn.innerHTML=noteHTML(AF_NU[nu].note);if(stopG)stopG();g=0;drawNu();stopG=animate(600,q=>{g=ease(q);drawNu()},()=>{stopG=null})}
  nb.addEventListener('click',e=>{const b=e.target.closest('[data-nu]');if(!b)return;nu=b.dataset.nu;$$('[data-nu]',nb).forEach(x=>x.setAttribute('aria-pressed',x===b));setNu()});
  ps.addEventListener('change',()=>{drawNu()});
  nn.innerHTML=noteHTML(AF_NU[nu].note);drawNu();
  const prevR=redraws.aftersurgery;redraws.aftersurgery=()=>{prevR&&prevR();drawNu()};
};
/* =============== 4.1 Children & adolescents =============== */
/* Main player: a schematic BMI-for-age chart. The curves are shapes, not CDC data (no BMI values are printed on the
   axis), so the chart teaches how the 85th, 95th, 120% and 140% of the 95th percentile relate as a child grows. Beside
   it, the AAP 2023 options light up when the child's age and severity meet the published thresholds. */
const CH_P95=monoFn([[2,19.3],[4,18],[6,18.4],[8,20],[10,22.4],[12,24.6],[14,26.6],[16,28.4],[18,29.8]]);
const CH_P85=monoFn([[2,18.2],[4,17],[6,17.1],[8,18.2],[10,19.9],[12,21.7],[14,23.3],[16,24.8],[18,26]]);
/* the child's position between the lines: 0 = 85th, 1 = 95th, 2 = 120% of 95th, 3 = 140% of 95th (schematic) */
const CH_S=monoFn([[3,-.7],[5,-.35],[7,.25],[9,.95],[11,1.5],[13,2.1],[15,2.35],[18,2.5]]);
function chBmi(a,s){const p85=CH_P85(a),p95=CH_P95(a);
  if(s<0)return p85+(p85-p95)*(-s)*.8;if(s<1)return lerp(p85,p95,s);if(s<2)return lerp(p95,1.2*p95,s-1);return lerp(1.2*p95,1.4*p95,s-2)}
const chAge=t=>3+15*t;
const CH_STEPS=[
 {from:0,at:.04,k:'Age 2 and up',t:'A yearly check',
  txt:'The AAP guideline (key action statement 1) says to screen all children aged 2 years and older for overweight and obesity at least once a year, using BMI percentile for age and sex. <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup> The 2000 CDC growth charts, which introduced BMI-for-age charts built from five US national surveys, cover ages 2 to 20. <sup class="c" data-ref="Kuczmarski2002" title="Source 302"><a href="/obesity/sources/#src-Kuczmarski2002">302</a></sup> A child’s BMI is compared with other children of the same age and sex, because BMI changes a great deal as children grow.',
  pt:'Doctors plot a child’s measurements on a growth chart that compares them with other children of the same age and sex. The chart is a tool, not a judgement.',
  hook:'Children: BMI percentile for age and sex, checked at least yearly from age 2 (AAP KAS 1). <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup>'},
 {from:.2,at:.27,k:'85th percentile',t:'Crossing the 85th',
  txt:'In a US study of 8579 children and young people aged 3 to 19 with BMI at or above the 85th percentile, 46.9% had overweight, 36.4% class I obesity, 11.9% class II and 4.8% class III. <sup class="c" data-ref="Skinner2015" title="Source 516"><a href="/obesity/sources/#src-Skinner2015">516</a></sup> The AAP refers children with overweight and obesity to intensive health behaviour and lifestyle treatment (IHBLT), described as most effective with 26 or more hours of face-to-face, family-based, multicomponent treatment over 3 to 12 months (KAS 11). <sup class="c" data-ref="Cuda2024OMA,Orr2026,Hampl2023AAP" title="Source 102,216,414"><a href="/obesity/sources/#src-Cuda2024OMA">102,216,414</a></sup> The recommendation is graded B from age 6 and C for ages 2 to 5. <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup>',
  pt:'Treatment for children means the whole family working on everyday habits with a skilled team, for many hours over months. It is not a diet for the child.',
  hook:'IHBLT: 26 hours or more, face to face, family-based, over 3 to 12 months (AAP KAS 11). <sup class="c" data-ref="Cuda2024OMA,Orr2026" title="Source 102,414"><a href="/obesity/sources/#src-Cuda2024OMA">102,414</a></sup>'},
 {from:.4,at:.45,k:'95th percentile',t:'At or above the 95th: obesity',
  txt:'In children and adolescents, obesity is defined as BMI at or above the 95th percentile of BMI-for-age. <sup class="c" data-ref="Ogden2023" title="Source 410"><a href="/obesity/sources/#src-Ogden2023">410</a></sup> The AAP guideline recommends against “watchful waiting”: treatment should begin when obesity is diagnosed, and comorbidities are treated at the same time (KAS 4, grade A). <sup class="c" data-ref="Cuda2024OMA,Orr2026,Hampl2023AAP" title="Source 102,216,414"><a href="/obesity/sources/#src-Cuda2024OMA">102,216,414</a></sup> In a meta-analysis of 15 cohorts (200,777 participants), children and adolescents with obesity were around five times more likely to have obesity as adults. <sup class="c" data-ref="Simmonds2016" title="Source 510"><a href="/obesity/sources/#src-Simmonds2016">510</a></sup>',
  pt:'Obesity in a child is not something to wait and see about. Help can start as soon as it is found, and it focuses on health for the whole family.',
  hook:'Paediatric obesity = BMI at or above the 95th percentile for age and sex; no “watchful waiting”. <sup class="c" data-ref="Ogden2023,Cuda2024OMA" title="Source 102,410"><a href="/obesity/sources/#src-Ogden2023">102,410</a></sup>'},
 {from:.6,at:.66,k:'120% and 140% of the 95th',t:'Severe obesity',
  txt:'Severe obesity is BMI at or above 120% of the 95th percentile, or a BMI of 35 or more; the AAP uses 120% for class 2 and 140% for class 3. <sup class="c" data-ref="Ogden2023,Hampl2023AAP" title="Source 216,410"><a href="/obesity/sources/#src-Ogden2023">216,410</a></sup> The 2000 charts could not grade this well, so in December 2022 CDC released extended charts that reach a BMI of 60 and add the 98th, 99th, 99.9th and 99.99th percentiles. From about age 7 the extended 98th approximates 120% of the 95th. <sup class="c" data-ref="Ogden2023" title="Source 410"><a href="/obesity/sources/#src-Ogden2023">410</a></sup> In 2017 to March 2020, 6.7% of US children and adolescents aged 2 to 19 had BMI at or above 120% of the 95th percentile. <sup class="c" data-ref="Ogden2023" title="Source 410"><a href="/obesity/sources/#src-Ogden2023">410</a></sup>',
  pt:'For higher BMIs, doctors describe how far above the 95th line a child is, as a percentage of it. Special extended charts now show these higher values.',
  hook:'Class 2 = 120% of the 95th percentile (or BMI 35); class 3 = 140% (or BMI 40). <sup class="c" data-ref="Ogden2023,Hampl2023AAP" title="Source 216,410"><a href="/obesity/sources/#src-Ogden2023">216,410</a></sup>'},
 {from:.74,at:.8,k:'Age 12 and up',t:'Medicines can be offered',
  txt:'Key action statement 12: offer adolescents aged 12 and older with obesity weight-loss pharmacotherapy as an adjunct to health behaviour and lifestyle treatment, weighing risks and benefits (grade B), quoted as published. <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup> Added to lifestyle therapy, newer medicines reduce mean BMI by about 5% to 17% at one year in adolescents. <sup class="c" data-ref="Kelly2024JAMA" title="Source 276"><a href="/obesity/sources/#src-Kelly2024JAMA">276</a></sup> Uptake is low: fewer than 2% of eligible adolescents receive pharmacotherapy. <sup class="c" data-ref="Orr2026" title="Source 414"><a href="/obesity/sources/#src-Orr2026">414</a></sup>',
  pt:'Some teenagers aged 12 or older may be offered a medicine alongside family lifestyle support. The decision is made with a specialist team and the family.',
  hook:'AAP KAS 12: pharmacotherapy offered from age 12, as an adjunct (grade B). <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup>'},
 {from:.88,at:.95,k:'Age 13 and up, severe obesity',t:'Evaluation for surgery',
  txt:'Key action statement 13: refer adolescents aged 13 and older with severe obesity for evaluation for metabolic and bariatric surgery (grade C), quoted as published. <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup> The ASMBS 2018 paediatric guideline says adolescents with class II obesity plus a listed comorbidity, or class III obesity, “should be considered” for surgery. <sup class="c" data-ref="Pratt2018ASMBS" title="Source 440"><a href="/obesity/sources/#src-Pratt2018ASMBS">440</a></sup> AAP policy calls surgery an underused option, with unequal access. <sup class="c" data-ref="Armstrong2019AAP" title="Source 23"><a href="/obesity/sources/#src-Armstrong2019AAP">23</a></sup>',
  pt:'For some teenagers with very high weight, surgery can be discussed with a specialist team. Referral means an assessment, not a decision.',
  hook:'AAP KAS 13: refer for surgical evaluation from age 13 with severe obesity (grade C). <sup class="c" data-ref="Orr2026,Hampl2023AAP" title="Source 216,414"><a href="/obesity/sources/#src-Orr2026">216,414</a></sup>'}
];
const CH_OPTS=[
 {n:'Screen every year',d:'BMI percentile from age 2',ok:(a,s)=>a>=2,w:''},
 {n:'Treat at diagnosis',d:'no watchful waiting; IHBLT 26 h+',ok:(a,s)=>s>=0,w:'overweight or obesity'},
 {n:'Medicines can be offered',d:'age 12+, with obesity',ok:(a,s)=>a>=12&&s>=1,w:'age 12 and obesity'},
 {n:'Evaluation for surgery',d:'age 13+, severe obesity',ok:(a,s)=>a>=13&&s>=2,w:'age 13 and severe obesity'}
];
const CH_ZONE=['below the 85th percentile','85th to below 95th: overweight','95th or above: obesity','120% of the 95th or above: severe obesity'];

/* STEP TEENS: published points only, straight lines between them <sup class="c" data-ref="Weghuber2022STEPTEENS" title="Source 587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">587</a></sup> */
const CH_ST={sema:[[0,0],[68,-16.1],[75,-13.2]],plac:[[0,0],[68,.6],[75,1.2]]};
const CH_ST_STEPS=[
 {from:0,k:'Weeks 0 to 68',t:'On treatment, with lifestyle support',
  txt:'STEP TEENS randomised 201 adolescents aged 12 to under 18 with obesity (or overweight plus a comorbidity) 2:1 to weekly semaglutide 2.4 mg or placebo, both with lifestyle intervention. At baseline the mean age was 15.4 years and mean BMI 37.0; 62% were girls. <sup class="c" data-ref="Weghuber2022STEPTEENS" title="Source 587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">587</a></sup>',
  pt:'Everyone in the trial had lifestyle support. The gap between the two lines is what the medicine added, on average; with placebo, BMI stayed about the same.'},
 {from:.9,k:'Week 68',t:'The end of treatment',
  txt:'Mean BMI change was −16.1% with semaglutide and +0.6% with placebo, a difference of −16.7 percentage points (95% CI −20.3 to −13.2). Body weight changed −14.7% vs +2.7%, and 73% (95/131) vs 18% (11/62) lost 5% or more. <sup class="c" data-ref="Weghuber2022STEPTEENS" title="Source 587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">587</a></sup> These are trial averages, not a prediction for any one young person.',
  hook:'STEP TEENS at 68 weeks: BMI −16.1% (semaglutide) vs +0.6% (placebo). <sup class="c" data-ref="Weghuber2022STEPTEENS" title="Source 587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">587</a></sup>'},
 {from:.95,k:'Week 75, seven weeks off treatment',t:'BMI starts to rise again',
  txt:'Seven weeks after stopping, BMI change was −13.2% with semaglutide vs +1.2% with placebo, which the authors describe as a small regain. <sup class="c" data-ref="Weghuber2022STEPTEENS" title="Source 587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">587</a></sup> After liraglutide was stopped in another adolescent trial, BMI SDS also rose more than with placebo (difference 0.15). <sup class="c" data-ref="Kelly2020Liraglutide" title="Source 274"><a href="/obesity/sources/#src-Kelly2020Liraglutide">274</a></sup> This fits obesity as a chronic, relapsing disease, not a failure of effort.',
  pt:'When the medicine stops, the body’s hunger signals come back and some weight returns. That is biology, not anyone’s fault.',
  hook:'Regain after stopping (−16.1% to −13.2% by week 75) is consistent with a chronic, relapsing disease. <sup class="c" data-ref="Weghuber2022STEPTEENS,Kelly2020Liraglutide" title="Source 274,587"><a href="/obesity/sources/#src-Weghuber2022STEPTEENS">274,587</a></sup>'}
];
/* comparator views */
const CH_CMP=[
 {id:'type',b:'By treatment type',h:'Mean BMI fall at about 1 year, adolescents (approximate)',u:'%',min:0,max:35,
  rows:[{n:'Intensive lifestyle (over 26 h)',v:3,l:'about 3%'},{n:'Medicines + lifestyle',lo:5,v:17,l:'about 5 to 17%'},{n:'Surgery, severe obesity',v:30,l:'about 30%'}],
  k:'A review of adolescent obesity',t:'More intensive treatment, larger average change',
  txt:'Lifestyle therapy alone needs more than 26 contact hours over a year to produce a mean BMI fall of about 3%. Added to lifestyle therapy, newer medicines reduce mean BMI by about 5% to 17% at one year, and severe adverse events are rare. In adolescents with BMI at or above 120% of the 95th percentile, surgery reduces mean BMI by about 30% at one year; about 15% have minor and 8% major perioperative complications. <sup class="c" data-ref="Kelly2024JAMA" title="Source 276"><a href="/obesity/sources/#src-Kelly2024JAMA">276</a></sup>'},
 {id:'labs3',b:'Teen-LABS at 3 years',h:'Teen-LABS: share whose condition remitted 3 years after surgery',u:'%',min:0,max:100,
  rows:[{n:'Type 2 diabetes',v:95},{n:'Abnormal kidney function',v:86},{n:'Prediabetes',v:76},{n:'Elevated blood pressure',v:74},{n:'Dyslipidaemia',v:66}],
  k:'242 adolescents, mean BMI 53',t:'Health conditions often went into remission',
  txt:'Three years after surgery, mean weight had fallen 27% (95% CI 25 to 29): 28% after gastric bypass and 26% after sleeve gastrectomy. There were costs too: 57% had low ferritin (hypoferritinaemia) and 13% had had further intra-abdominal procedures. <sup class="c" data-ref="Inge2016NEJM" title="Source 245"><a href="/obesity/sources/#src-Inge2016NEJM">245</a></sup>'},
 {id:'labs5',b:'Teens vs adults, 5 years',h:'5 years after gastric bypass: adolescents (filled) vs adults (outline)',u:'%',min:0,max:100,pair:1,
  rows:[{n:'Weight change (fall)',v:26,w:29},{n:'Diabetes remission',v:86,w:53},{n:'Hypertension remission',v:68,w:41},{n:'Low ferritin',v:48,w:29}],
  k:'Teen-LABS vs adult LABS',t:'Similar weight change, more remission, more follow-up needs',
  txt:'Five years after gastric bypass, weight change was similar in adolescents (−26%) and adults (−29%). Adolescents were more likely to have remission of type 2 diabetes (86% vs 53%) and hypertension (68% vs 41%), but had more abdominal reoperations (19 vs 10 per 500 person-years) and more low ferritin (48% vs 29%). <sup class="c" data-ref="Inge2019NEJM" title="Source 246"><a href="/obesity/sources/#src-Inge2019NEJM">246</a></sup>'},
 {id:'amos',b:'AMOS, Sweden',h:'AMOS: mean BMI change over 5 years (kg/m²)',u:'',min:-15,max:5,
  rows:[{n:'Gastric bypass',v:-13.1,l:'−13.1'},{n:'Matched, no surgery',v:3.3,l:'+3.3'}],
  k:'81 adolescents, mean BMI 45.5',t:'BMI fell after surgery and rose without it',
  txt:'In the Swedish AMOS study, BMI fell by 13.1 kg/m² over 5 years after gastric bypass, while it rose 3.3 kg/m² in matched adolescents treated without surgery. 25% of surgical patients needed further abdominal surgery and 72% had some nutritional deficiency; 25% of the non-surgical group went on to have surgery within 5 years. <sup class="c" data-ref="Olbers2017AMOS" title="Source 413"><a href="/obesity/sources/#src-Olbers2017AMOS">413</a></sup>'}
];

inits.children=()=>{
  /* ---------- growth chart player ---------- */
  const svg=$('#chSvg'),rg=$('#chT'),note=$('#chNote');let setA=null;
  function draw(t){
    const N=vb(svg,'720 380','400 640');
    const L=N?{x:40,y:46,w:262,h:250,ox:20,oy:364,ow:360,oh:52,og:8,sy:620,lx:306}
             :{x:46,y:44,w:330,h:270,ox:460,oy:56,ow:252,oh:58,og:10,sy:362,lx:380};
    const a=chAge(t),s=CH_S(a),X=v=>L.x+L.w*(v-2)/16,Y=v=>L.y+L.h-L.h*(v-13)/(44-13);
    let g=`<rect x="${L.x}" y="${L.y}" width="${L.w}" height="${L.h}" style="fill:var(--field)"/>`;
    /* bands between curves */
    const band=(f0,f1_,col,op)=>{let top='',bot='';for(let i=0;i<=64;i++){const v=2+16*i/64;top+=(i?'L':'M')+f1(X(v))+' '+f1(Y(Math.min(44,f1_(v))));}
      for(let i=64;i>=0;i--){const v=2+16*i/64;bot+='L'+f1(X(v))+' '+f1(Y(Math.min(44,f0(v))))}
      return `<path d="${top+bot}Z" style="fill:${col};opacity:${op}"/>`};
    const p120=v=>1.2*CH_P95(v),p140=v=>1.4*CH_P95(v),ceil=()=>44;
    g+=band(CH_P85,CH_P95,'var(--warn-soft)',.9)+band(CH_P95,p120,'var(--accent-soft)',.9)+band(p120,ceil,'var(--hl-soft)',.75);
    for(let v=2;v<=18;v+=2){g+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${L.y+L.h}" y2="${L.y+L.h+4}" class="axis"/><text x="${f1(X(v))}" y="${L.y+L.h+16}" class="t-xs t-mid">${v}</text>`}
    g+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${L.y+L.h}" y2="${L.y+L.h}" class="axis"/><line x1="${L.x}" x2="${L.x}" y1="${L.y}" y2="${L.y+L.h}" class="axis"/>`;
    g+=`<text x="${L.x+L.w}" y="${L.y+L.h+30}" class="t-xs t-end">age in years</text><text x="${L.x}" y="${L.y-8}" class="t-xs">BMI-for-age (schematic, no values)</text>`;
    const curve=(f,col,w,dash,lbl)=>{const d=pathFn(u=>(44-Math.min(44,f(2+16*u)))/(44-13),L.x,L.x+L.w,L.y,L.y+L.h,80);
      return `<path d="${d}" style="fill:none;stroke:${col};stroke-width:${w};${dash?'stroke-dasharray:'+dash:''}"/>`+kitLabel(L.lx,Y(Math.min(43.4,f(18)))+3,lbl)};
    g+=curve(CH_P85,'var(--muted)',1.4,'4 3','85th')+curve(CH_P95,'var(--ink)',2,'','95th')+curve(p120,'var(--accent)',1.8,'','120% of 95th')+curve(p140,'var(--hl)',1.6,'6 3','140% of 95th');
    /* the child's line */
    let d='';const n=Math.max(2,Math.round((a-3)*8));for(let i=0;i<=n;i++){const v=3+(a-3)*i/n;d+=(i?'L':'M')+f1(X(v))+' '+f1(Y(chBmi(v,CH_S(v))))}
    g+=`<path d="${d}" style="fill:none;stroke:var(--life);stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round"/>`;
    const cx=X(a),cy=Y(chBmi(a,s));
    g+=`<circle cx="${f1(cx)}" cy="${f1(cy)}" r="6.5" style="fill:var(--life);stroke:var(--panel);stroke-width:2.5"/>`;
    /* crossing markers */
    [[0,'85th'],[1,'95th'],[2,'120%']].forEach(([lv,lb])=>{if(s<lv)return;let lo=3,hi=a;for(let k=0;k<24;k++){const m=(lo+hi)/2;if(CH_S(m)<lv)lo=m;else hi=m}
      const px=X(hi),py=Y(chBmi(hi,lv));g+=`<circle cx="${f1(px)}" cy="${f1(py)}" r="4" style="fill:var(--panel);stroke:var(--life);stroke-width:2"/>`});
    /* a growing child in the empty upper-left of the chart: same figure, same body size, only height changes with age */
    const ph=lerp(64,112,ramp(a,3,18)),px0=L.x+(N?34:40);
    g+=person(px0,L.y+L.h*.62-ph,ph,{kid:a<11,size:.45}).svg;
    g+=`<text x="${px0+(N?40:46)}" y="${L.y+30}" class="t-big" style="font-size:24px">Age ${a.toFixed(1)}</text>`;
    /* options panel */
    const zone=s<0?0:s<1?1:s<2?2:3;
    g+=`<text x="${L.ox}" y="${L.oy-12}" class="t-sm" style="fill:var(--ink);font-weight:700">AAP 2023 options, as published</text>`;
    CH_OPTS.forEach((o,i)=>{const on=o.ok(a,s),y=L.oy+i*(L.oh+L.og);
      g+=`<rect x="${L.ox}" y="${y}" width="${L.ow}" height="${L.oh}" rx="10" style="fill:${on?'var(--life-soft)':'var(--panel)'};stroke:${on?'var(--life)':'var(--line)'};stroke-width:${on?2:1.2};${on?'':'stroke-dasharray:5 4'}"/>`;
      g+=on?`<path d="M${L.ox+12} ${y+L.oh/2}l5 5 9-11" style="fill:none;stroke:var(--life);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round"/>`:`<circle cx="${L.ox+19}" cy="${y+L.oh/2}" r="6" style="fill:none;stroke:var(--muted);stroke-width:1.5"/>`;
      g+=`<text x="${L.ox+36}" y="${y+L.oh/2-5}" class="t-sm" style="fill:var(--ink);font-weight:700">${o.n}</text><text x="${L.ox+36}" y="${y+L.oh/2+11}" class="t-xs">${on?o.d:'waits for: '+o.w}</text>`});
    g+=`<text x="${N?L.ox:L.x}" y="${L.sy}" class="t-xs" style="fill:var(--ink);font-weight:700">Now: ${CH_ZONE[zone]}</text>`;
    svg.innerHTML=g;
    const p=phaseOf(CH_STEPS,t);note.innerHTML=noteHTML(CH_STEPS[p]);setA&&setA(p);
  }
  const stop=playWire(rg,$('#chPlay'),draw,15000,'Replay','children');
  setA=stepWire($('#chSteps'),CH_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- STEP TEENS ---------- */
  const tsv=$('#chTeen'),trg=$('#chTeenT'),tnote=$('#chTeenNote');
  const at=(P,w)=>{if(w<=P[0][0])return P[0][1];for(let i=1;i<P.length;i++)if(w<=P[i][0])return lerp(P[i-1][1],P[i][1],(w-P[i-1][0])/(P[i][0]-P[i-1][0]));return P[P.length-1][1]};
  function drawTeen(t){
    const N=vb(tsv,'720 320','400 500');
    const L=N?{x:52,y:44,w:296,h:220,ax:40,ay:356,gap:180}:{x:60,y:40,w:370,h:220,ax:470,ay:70,gap:130};
    const wk=75*t,ax=curveAxes(L.x,L.y,L.w,L.h,{x0:0,x1:75,y0:-20,y1:5,xt:[0,20,40,60,75],yt:[-20,-15,-10,-5,0,5],yfmt:v=>(v>0?'+':'')+v+'%',xlabel:'weeks',ylabel:'mean BMI change from baseline'});
    let g=ax.svg;const X=ax.X,Y=ax.Y;
    g+=`<rect x="${f1(X(68))}" y="${L.y}" width="${f1(X(75)-X(68))}" height="${L.h}" style="fill:var(--warn-soft);opacity:.8"/><line x1="${f1(X(68))}" x2="${f1(X(68))}" y1="${L.y}" y2="${L.y+L.h}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/>`;
    g+=kitLabel(X(68)-4,L.y+14,'treatment stops, week 68',{a:'e'});
    g+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${f1(Y(0))}" y2="${f1(Y(0))}" style="stroke:var(--muted);stroke-width:1"/>`;
    const line=(P,col,dash)=>{let d='';const n=60;for(let i=0;i<=n;i++){const w=wk*i/n;d+=(i?'L':'M')+f1(X(w))+' '+f1(Y(at(P,w)))}return `<path d="${d}" style="fill:none;stroke:${col};stroke-width:3;stroke-linejoin:round;${dash?'stroke-dasharray:'+dash:''}"/>`};
    g+=line(CH_ST.plac,'var(--muted)','6 4')+line(CH_ST.sema,'var(--rx-drug)','');
    [['sema','var(--rx-drug)',v=>v.toFixed(1)+'%',14],['plac','var(--muted)',v=>'+'+v.toFixed(1)+'%',-8]].forEach(([k,col,fm,dy])=>{
      CH_ST[k].slice(1).forEach(p=>{if(wk<p[0]-.01)return;g+=`<circle cx="${f1(X(p[0]))}" cy="${f1(Y(p[1]))}" r="4.5" style="fill:${col};stroke:var(--panel);stroke-width:2"/>`+kitLabel(X(p[0])-(p[0]===68?8:-6),Y(p[1])+dy,fm(p[1]),{a:p[0]===68?'e':''})});
      const e=at(CH_ST[k],wk);g+=`<circle cx="${f1(X(wk))}" cy="${f1(Y(e))}" r="3.5" style="fill:${col}"/>`});
    g+=kitLabel(X(6),Y(-4),'semaglutide')+kitLabel(X(6),Y(2.6),'placebo');
    /* who lost 5% or more by week 68 */
    const rev=ramp(wk,56,68);
    g+=`<text x="${L.ax}" y="${L.ay-26}" class="t-sm" style="fill:var(--ink);font-weight:700">Lost 5% or more of body weight by week 68</text>`;
    [['Semaglutide',73,'var(--rx-drug)'],['Placebo',18,'var(--muted)']].forEach(([nm,k,col],i)=>{const x=L.ax+i*L.gap;
      const ia=iconArray(x,L.ay,{n:100,cols:10,size:9,gap:2,shape:'dot',k:Math.round(k*rev),col,base:'var(--line)'});
      g+=`<text x="${x}" y="${L.ay-8}" class="t-xs" style="fill:var(--ink);font-weight:700">${nm}: ${Math.round(k*rev)} in 100</text>`+ia.svg});
    tsv.innerHTML=g;
    tnote.innerHTML=noteHTML(CH_ST_STEPS[phaseOf(CH_ST_STEPS,t)]);
  }
  playWire(trg,$('#chTeenPlay'),drawTeen,9000,'Replay','children');
  drawTeen(+trg.value);

  /* ---------- comparator ---------- */
  const csv=$('#chCmp'),cb=$('#chCmpBtns'),cnote=$('#chCmpNote');let ci=0,stopC=null,cp=1;
  cb.innerHTML=CH_CMP.map((c,i)=>`<button class="btn" data-cv="${i}" aria-pressed="${i===0}">${c.b}</button>`).join('');
  function drawCmp(){
    const N=vb(csv,'720 300','400 420'),c=CH_CMP[ci];
    const L=N?{lx:20,bx:20,bw:300,y0:52,rh:c.rows.length>3?66:90,ly:-6,bh:16}:{lx:20,bx:270,bw:360,y0:56,rh:c.rows.length>3?46:70,ly:12,bh:18};
    const X=v=>L.bx+L.bw*(v-c.min)/(c.max-c.min),x0=X(0);
    let g=`<text x="20" y="22" class="t-sm" style="fill:var(--ink);font-weight:700">${c.h}</text>`;
    if(c.pair)g+=`<rect x="${N?20:L.bx}" y="32" width="12" height="8" style="fill:var(--life)"/><text x="${(N?20:L.bx)+16}" y="40" class="t-xs">adolescents</text><rect x="${(N?20:L.bx)+100}" y="32" width="12" height="8" style="fill:none;stroke:var(--ink);stroke-width:1.2"/><text x="${(N?20:L.bx)+116}" y="40" class="t-xs">adults</text>`;
    if(c.min<0)g+=`<line x1="${f1(x0)}" x2="${f1(x0)}" y1="44" y2="${L.y0+c.rows.length*L.rh-10}" style="stroke:var(--ink);stroke-width:1.2"/>`+kitLabel(x0,44,'0',{a:'m'});
    c.rows.forEach((r,i)=>{const y=L.y0+i*L.rh,by=N?y+4:y;
      g+=`<text x="${L.lx}" y="${N?y+L.ly:by+L.ly+(c.pair?4:0)}" class="t-sm" style="fill:var(--ink);font-weight:700">${r.n}</text>`;
      g+=`<rect x="${L.bx}" y="${by}" width="${L.bw}" height="${L.bh}" rx="4" style="fill:var(--panel-2)"/>`;
      const v=r.v*cp,a=Math.min(X(0),X(v)),w=Math.abs(X(v)-X(0));
      if(r.lo!=null){const lo=X(r.lo*cp);g+=`<rect x="${f1(x0)}" y="${by}" width="${f1(Math.max(0,lo-x0))}" height="${L.bh}" rx="4" style="fill:var(--life);opacity:.45"/><rect x="${f1(lo)}" y="${by}" width="${f1(Math.max(0,X(v)-lo))}" height="${L.bh}" rx="4" style="fill:var(--life)"/>`}
      else g+=`<rect x="${f1(a)}" y="${by}" width="${f1(Math.max(2,w))}" height="${L.bh}" rx="4" style="fill:${r.v<0?'var(--tx)':'var(--life)'}"/>`;
      const lab=r.l||(Math.round(r.v)+(c.u));
      g+=`<text x="${f1(r.v<0?x0+6:X(v)+6)}" y="${by+L.bh-4}" class="t-xs" style="fill:var(--ink);font-weight:700">${cp>.98?lab:''}</text>`;
      if(c.pair){const yb=by+L.bh+4;g+=`<rect x="${L.bx}" y="${yb}" width="${f1(Math.max(2,X(r.w*cp)-L.bx))}" height="${L.bh-4}" rx="3" style="fill:none;stroke:var(--ink);stroke-width:1.3"/><text x="${f1(X(r.w*cp)+6)}" y="${yb+L.bh-7}" class="t-xs">${cp>.98?r.w+'%':''}</text>`}
    });
    csv.innerHTML=g;
    cnote.innerHTML=noteHTML({k:c.k,t:c.t,txt:c.txt});
  }
  cb.addEventListener('click',e=>{const b=e.target.closest('[data-cv]');if(!b)return;ci=+b.dataset.cv;$$('[data-cv]',cb).forEach(x=>x.setAttribute('aria-pressed',x===b));
    stopC&&stopC();stopC=animate(650,p=>{cp=ease(p);drawCmp()},()=>{stopC=null;cp=1;drawCmp()})});
  drawCmp();
  const prevR=redraws.children;redraws.children=()=>{prevR&&prevR();drawCmp()};
  const prevH=onHide.children;onHide.children=()=>{prevH&&prevH();stopC&&stopC();stopC=null;cp=1};
};
/* =============== 4.2 Pregnancy & fertility =============== */
/* Main player: a preconception-to-postpartum timeline. Risk lamps light as the marker reaches the stage where each
   risk is usually discussed (placement schematic; the odds ratios are published), and a chart below fills the IOM 2009
   gestational weight gain range for the chosen pre-pregnancy BMI class (only the end-of-pregnancy totals are published;
   the straight path to them is schematic). */
const PG_STAGE=[{a:0,b:.16,n:'Before pregnancy',s:'Pre'},{a:.16,b:.38,n:'Trimester 1',s:'T1'},{a:.38,b:.58,n:'Trimester 2',s:'T2'},{a:.58,b:.78,n:'Trimester 3',s:'T3'},{a:.78,b:.84,n:'Birth',s:'Birth'},{a:.84,b:1,n:'After the birth',s:'After'}];
const PG_LAMP=[
 {t:.05,n:'Longer time to conceive',v:'OR 1.32 per BMI group'},
 {t:.2,n:'Neural tube defects',v:'OR 1.87'},
 {t:.27,n:'Early pregnancy loss',v:'higher risk'},
 {t:.43,n:'Gestational diabetes',v:'OR 3.56; severe 8.56'},
 {t:.61,n:'Pre-eclampsia',v:'~2× per 5–7 BMI units'},
 {t:.69,n:'Stillbirth',v:'RR 1.24 per 5 BMI units'},
 {t:.79,n:'Caesarean birth',v:'OR 2.26; BMI >35: 3.38'},
 {t:.815,n:'Shoulder dystocia, bleeding',v:'higher risk'},
 {t:.87,n:'Clots, low mood, feeding',v:'higher risk'},
 {t:.95,n:'Obesity in the child later',v:'OR 3.64'}
];
const PG_GWG=[{b:'BMI under 18.5',lo:12.5,hi:18},{b:'BMI 18.5 to 24.9',lo:11.5,hi:16},{b:'BMI 25 to 29.9',lo:7,hi:11},{b:'BMI 30 or more',lo:5,hi:9}];
const PG_STEPS=[
 {from:0,at:.06,k:'Before pregnancy',t:'Fertility and planning',
  txt:'Obesity is the most common medical condition in women of reproductive age. <sup class="c" data-ref="ACOG2021PB230,Catalano2017" title="Source 4,68"><a href="/obesity/sources/#src-ACOG2021PB230">4,68</a></sup> It reduces fertility and increases the time taken to conceive. <sup class="c" data-ref="Poston2016" title="Source 438"><a href="/obesity/sources/#src-Poston2016">438</a></sup> In 47,835 Danish couples, each step up in BMI group raised the odds of taking more than 12 months to conceive (OR 1.32 per group in women, 1.19 in men). <sup class="c" data-ref="RamlauHansen2007" title="Source 454"><a href="/obesity/sources/#src-RamlauHansen2007">454</a></sup> ACOG recommends that obesity management begin before pregnancy and continue through the postpartum period. <sup class="c" data-ref="ACOG2021PB230" title="Source 4"><a href="/obesity/sources/#src-ACOG2021PB230">4</a></sup>',
  pt:'Planning ahead helps: a check-up before pregnancy is a good time to talk about vitamins, any weight medicines and other health conditions.',
  hook:'Wegovy label: stop at least 2 months before a planned pregnancy. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>'},
 {from:.16,at:.22,k:'Weeks 0 to 13',t:'The first trimester',
  txt:'Compared with mothers of recommended BMI, mothers with obesity had higher odds of neural tube defects (OR 1.87, 95% CI 1.62 to 2.15), spina bifida (2.24), cardiovascular anomalies (1.30) and hydrocephaly (1.68); gastroschisis was less common (OR 0.17). The authors note that the absolute increase in anomalies is likely small. <sup class="c" data-ref="Stothard2009" title="Source 525"><a href="/obesity/sources/#src-Stothard2009">525</a></sup> Early pregnancy loss is also more likely. <sup class="c" data-ref="Poston2016" title="Source 438"><a href="/obesity/sources/#src-Poston2016">438</a></sup>',
  pt:'A few birth differences are a little more common at a higher weight. The extra risk for any one pregnancy is small.',
  hook:'Maternal obesity and neural tube defects: OR 1.87; gastroschisis less common (OR 0.17). <sup class="c" data-ref="Stothard2009" title="Source 525"><a href="/obesity/sources/#src-Stothard2009">525</a></sup>'},
 {from:.38,at:.45,k:'Weeks 14 to 27',t:'Gestational diabetes',
  txt:'Compared with normal weight, the unadjusted odds of gestational diabetes were 2.14 with overweight, 3.56 with obesity and 8.56 with severe obesity. <sup class="c" data-ref="Chu2007" title="Source 78"><a href="/obesity/sources/#src-Chu2007">78</a></sup> Proposed mechanisms include higher insulin resistance, hyperinsulinaemia, inflammation and oxidative stress before pregnancy, which may affect early placental and fetal development. <span class="ev early">Early evidence</span> <sup class="c" data-ref="Catalano2017" title="Source 68"><a href="/obesity/sources/#src-Catalano2017">68</a></sup>',
  pt:'Diabetes that starts in pregnancy is more common at a higher weight. Regular checks help find it early so it can be treated.',
  hook:'Gestational diabetes ORs: 2.14 overweight, 3.56 obesity, 8.56 severe obesity. <sup class="c" data-ref="Chu2007" title="Source 78"><a href="/obesity/sources/#src-Chu2007">78</a></sup>'},
 {from:.58,at:.66,k:'Weeks 28 to 40',t:'Pre-eclampsia and stillbirth',
  txt:'In 13 cohorts of nearly 1.4 million women, pre-eclampsia risk typically doubled with each 5 to 7 kg/m² rise in pre-pregnancy BMI. <sup class="c" data-ref="OBrien2003" title="Source 406"><a href="/obesity/sources/#src-OBrien2003">406</a></sup> Each 5-unit rise in BMI was associated with a relative risk of 1.24 for stillbirth; absolute stillbirth risk was 40 per 10,000 pregnancies at BMI 20, 48 at BMI 25 and 59 at BMI 30. <sup class="c" data-ref="Aune2014" title="Source 34"><a href="/obesity/sources/#src-Aune2014">34</a></sup> These are population statistics.',
  pt:'High blood pressure in pregnancy is more common at a higher weight. Most pregnancies still go well; check-ups catch problems early.',
  hook:'Pre-eclampsia risk roughly doubles with each 5 to 7 kg/m² rise in pre-pregnancy BMI. <sup class="c" data-ref="OBrien2003" title="Source 406"><a href="/obesity/sources/#src-OBrien2003">406</a></sup>'},
 {from:.78,at:.8,k:'Birth',t:'Birth',
  txt:'Compared with BMI 20 to 25, the crude odds of caesarean delivery in first pregnancies were 1.53 for overweight, 2.26 for BMI 30 to 35 and 3.38 for BMI over 35. <sup class="c" data-ref="Poobalan2009" title="Source 437"><a href="/obesity/sources/#src-Poobalan2009">437</a></sup> Shoulder dystocia and post-partum haemorrhage are also more likely. <sup class="c" data-ref="Poston2016" title="Source 438"><a href="/obesity/sources/#src-Poston2016">438</a></sup> A review of 22 systematic reviews found more instrumental and caesarean births and surgical site infection. <sup class="c" data-ref="Marchi2015" title="Source 353"><a href="/obesity/sources/#src-Marchi2015">353</a></sup>',
  pt:'A caesarean birth is more likely at a higher weight. The care team plans for this, including the right equipment.',
  hook:'Caesarean odds (first births) vs BMI 20 to 25: 1.53, 2.26 and 3.38 with rising BMI. <sup class="c" data-ref="Poobalan2009" title="Source 437"><a href="/obesity/sources/#src-Poobalan2009">437</a></sup>'},
 {from:.84,at:.9,k:'After the birth',t:'Postpartum and beyond',
  txt:'After birth, risks include venous thromboembolism, depression and difficulty breastfeeding. <sup class="c" data-ref="Catalano2017" title="Source 68"><a href="/obesity/sources/#src-Catalano2017">68</a></sup> Breastfeeding initiation is lower and stopping earlier. <sup class="c" data-ref="Marchi2015" title="Source 353"><a href="/obesity/sources/#src-Marchi2015">353</a></sup> Maternal obesity before conception was associated with obesity in the child (OR 3.64, 95% CI 2.68 to 4.95). <sup class="c" data-ref="Heslehurst2019" title="Source 224"><a href="/obesity/sources/#src-Heslehurst2019">224</a></sup> Weight kept on after the birth raises later cardiometabolic risk. <sup class="c" data-ref="Catalano2017" title="Source 68"><a href="/obesity/sources/#src-Catalano2017">68</a></sup>',
  pt:'After the birth, support with feeding, mood and recovery matters. Ask for help early; it is part of good care.',
  hook:'Postpartum: VTE, depression and breastfeeding difficulty are more likely. <sup class="c" data-ref="Catalano2017" title="Source 68"><a href="/obesity/sources/#src-Catalano2017">68</a></sup>'}
];
/* planning cards */
const PG_CARDS=[
 {b:'Semaglutide (Wegovy)',ax:{a:-6,b:9,step:3,u:'months relative to a planned conception'},
  bars:[{r:0,a:-6,b:-2,col:'var(--rx-drug)',l:'on semaglutide'},{r:0,a:-2,b:0,col:'var(--warn)',l:'2 months off',out:1}],
  marks:[{at:0,l:'planned conception'}],
  k:'Label statement, quoted',t:'Stop at least 2 months before',
  txt:'The Wegovy label: “discontinue WEGOVY in patients at least 2 months before they plan to become pregnant to account for the long half-life of semaglutide”. It also says to stop when pregnancy is recognised: weight loss offers no benefit in pregnancy and may cause fetal harm, and semaglutide caused embryofetal harm in animal studies. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup> In early-pregnancy data from mothers with type 2 diabetes (938 exposed infants), the adjusted RR for major malformations vs insulin was 0.95 (95% CI 0.72 to 1.26), reassuring but imprecise. <span class="ev early">Early evidence</span> <sup class="c" data-ref="Cesta2024Pregnancy" title="Source 71"><a href="/obesity/sources/#src-Cesta2024Pregnancy">71</a></sup>'},
 {b:'Tirzepatide (Zepbound)',ax:{a:0,b:24,step:4,u:'weeks after starting'},
  bars:[{r:0,a:0,b:4,col:'var(--rx-drug)',l:'2.5 mg',op:.45},{r:0,a:4,b:8,col:'var(--rx-drug)',l:'5',op:.6},{r:0,a:8,b:12,col:'var(--rx-drug)',l:'7.5',op:.8},{r:0,a:12,b:24,col:'var(--rx-drug)',l:'10 mg maintenance'},
        {r:1,a:0,b:4,col:'var(--warn)',l:'4 wk',out:1},{r:1,a:4,b:8,col:'var(--warn)',l:'4 wk',out:1},{r:1,a:8,b:12,col:'var(--warn)',l:'4 wk',out:1},{r:1,a:12,b:16,col:'var(--warn)',l:'4 wk',out:1}],
  rows:['dose (one possible path)','backup method windows'],marks:[],
  k:'Label statement, quoted',t:'Pills may work less well: a backup method',
  txt:'Zepbound may reduce the efficacy of oral hormonal contraceptives. The label advises switching to a non-oral method, or adding a barrier method for 4 weeks after starting and for 4 weeks after each dose escalation. It also advises that weight loss is not recommended during pregnancy and to stop Zepbound when a pregnancy is recognised. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup> The doses drawn follow the label’s start of 2.5 mg for 4 weeks and 2.5 mg steps at least 4 weeks apart, here ending at 10 mg; real schedules vary. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>'},
 {b:'Phentermine-topiramate (Qsymia)',ax:{a:0,b:6,step:1,u:'months on treatment'},
  bars:[{r:0,a:0,b:6,col:'var(--rx-drug)',l:'on treatment'}],marks:[0,1,2,3,4,5,6].map(m=>({at:m,l:m?'':'test',tick:1})),
  rows:['pregnancy test before start, then monthly'],
  k:'Label statement',t:'Contraindicated in pregnancy',
  txt:'Qsymia is contraindicated in pregnancy: first-trimester topiramate exposure raises the risk of major malformations, including oral clefts. A negative pregnancy test is advised before starting and monthly during treatment, and it is dispensed only through a REMS programme of certified pharmacies. <sup class="c" data-ref="FDA-Qsymia" title="Source 146"><a href="/obesity/sources/#src-FDA-Qsymia">146</a></sup> Contrave, Xenical and Saxenda labels say to stop when pregnancy is recognised. <sup class="c" data-ref="FDA-Contrave,FDA-Xenical,FDA-Saxenda" title="Source 141,148,151"><a href="/obesity/sources/#src-FDA-Contrave">141,148,151</a></sup>'},
 {b:'After bariatric surgery',ax:{a:-3,b:30,step:6,u:'months after surgery'},
  bars:[{r:0,a:0,b:12,col:'var(--life)',l:'typically about 1 year',op:.75},{r:1,a:0,b:24,col:'var(--life)',l:'typically about 2 years',op:.75}],
  rows:['sleeve or bypass','band'],marks:[{at:-2,l:'contraception counselling'},{at:0,l:'surgery'}],
  k:'2019 international consensus',t:'Wait until weight is stable',
  txt:'The 2019 consensus advises postponing pregnancy until weight is stable, typically about 1 year after sleeve or bypass and 2 years after a band. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup> It notes that studies found no clear difference in outcomes by surgery-to-conception interval and that many recommendations lack high-quality evidence. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup> It advises contraceptive counselling before surgery, avoiding combined oral contraceptives and encouraging long-acting reversible contraception. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup>'},
 {b:'Vitamins after surgery',ax:{a:-12,b:40,step:13,u:'weeks of pregnancy (before 0: planning)',fmt:v=>v===-12?'':v},
  bars:[{r:0,a:-12,b:40,col:'var(--gold)',l:'consensus multivitamin, incl. folic acid 5 mg',op:.55}],
  rows:['supplement','blood tests each trimester'],marks:[{at:8,l:'',tick:1,r:1},{at:20,l:'',tick:1,r:1},{at:33,l:'',tick:1,r:1}],
  k:'2019 international consensus, as published',t:'Supplements and checks',
  txt:'After bariatric surgery, the consensus lists a minimum preconception multivitamin content including folic acid 5 mg, iron 45 to 60 mg, thiamine over 12 mg and vitamin A as beta-carotene 5000 IU, because the retinol form is teratogenic. It advises checking blood count, ferritin, folate, B12 and vitamin A every trimester. <sup class="c" data-ref="Shawe2019ObesRev" title="Source 508"><a href="/obesity/sources/#src-Shawe2019ObesRev">508</a></sup> Quoted as published, not as instructions. Use of 5 mg folic acid supplements is low: in Northern Ireland booking data (255,117 pregnancies) it rose only from 3.6% to 5.0% between 2015 and 2020, and most folic acid use started after conception. <sup class="c" data-ref="Cassinelli2026" title="Source 66"><a href="/obesity/sources/#src-Cassinelli2026">66</a></sup>'},
 {b:'PCOS',pcos:1,
  k:'Polycystic ovary syndrome',t:'A common link with weight and fertility',
  txt:'Women with PCOS had a higher prevalence of obesity than women without it (RR 2.77, 95% CI 1.88 to 4.10) and of central obesity (RR 1.73). <sup class="c" data-ref="Lim2012PCOS" title="Source 326"><a href="/obesity/sources/#src-Lim2012PCOS">326</a></sup> The 2023 international PCOS guideline recognises its metabolic and cardiovascular features and a high risk of adverse pregnancy outcomes, recommends a healthy lifestyle with “awareness and consideration of weight stigma”, and calls for cheaper and safer fertility management. <sup class="c" data-ref="Teede2024PCOS" title="Source 545"><a href="/obesity/sources/#src-Teede2024PCOS">545</a></sup> An estimated 25% of ovulatory infertility in US women may be attributable to BMI 25 or more. <sup class="c" data-ref="RichEdwards2002" title="Source 460"><a href="/obesity/sources/#src-RichEdwards2002">460</a></sup>'}
];
const PG_OUT=[
 {b:'Swedish register (Johansson 2015)',h:'670 pregnancies after surgery (filled) vs matched controls (outline), %',max:25,pair:1,
  rows:[{n:'Gestational diabetes',v:1.9,w:6.8},{n:'Large for gestational age',v:8.6,w:22.4},{n:'Small for gestational age',v:15.6,w:7.6},{n:'Stillbirth or neonatal death',v:1.7,w:.7}],
  k:'Johansson 2015',t:'Fewer large babies, more small ones',
  txt:'Compared with matched controls, gestational diabetes was lower (1.9% vs 6.8%, OR 0.25) and large-for-gestational-age babies fewer (8.6% vs 22.4%), but small-for-gestational-age babies were more common (15.6% vs 7.6%, OR 2.20). Stillbirth or neonatal death was 1.7% vs 0.7%, a non-significant difference (OR 2.39, 95% CI 0.98 to 5.85). <sup class="c" data-ref="Johansson2015NEJM" title="Source 267"><a href="/obesity/sources/#src-Johansson2015NEJM">267</a></sup>'},
 {b:'Meta-analysis (Akhter 2019)',h:'Odds ratios after surgery vs no surgery (line at 1 = no difference)',max:3,or:1,
  rows:[{n:'Perinatal death',v:1.38},{n:'Congenital anomalies',v:1.29},{n:'Preterm birth',v:1.57},{n:'NICU admission',v:1.41},{n:'SGA, after bypass',v:2.72},{n:'LGA, after bypass',v:.24}],
  k:'33 studies, 14,880 pregnancies after surgery',t:'Higher odds of some problems, lower of others',
  txt:'Pregnancies after bariatric surgery had higher odds of perinatal death (OR 1.38), congenital anomalies (1.29), preterm birth (1.57) and NICU admission (1.41); after gastric bypass, small-for-gestational-age babies rose (OR 2.72) and large ones fell (OR 0.24). Babies weighed on average 242 g less. <sup class="c" data-ref="Akhter2019PLoSMed" title="Source 12"><a href="/obesity/sources/#src-Akhter2019PLoSMed">12</a></sup> The status is counselling and nutritional monitoring. <sup class="c" data-ref="Johansson2015NEJM,Shawe2019ObesRev" title="Source 267,508"><a href="/obesity/sources/#src-Johansson2015NEJM">267,508</a></sup>'}
];

inits.pregnancy=()=>{
  /* ---------- timeline player ---------- */
  const svg=$('#pgSvg'),rg=$('#pgT'),note=$('#pgNote'),gb=$('#pgGwgBtns');let setA=null,gi=3;
  gb.innerHTML=PG_GWG.map((c,i)=>`<button class="btn" data-gw="${i}" aria-pressed="${i===gi}">${c.b}</button>`).join('');
  function draw(t){
    const N=vb(svg,'720 400','400 660');
    const L=N?{tx:20,tw:360,ty:58,ry:106,rh:26,rx:24,rw:356,cx:52,cy:430,cw:318,ch:170}
             :{tx:40,tw:640,ty:58,ry:116,rh:27,rx:20,rw:344,cx:426,cy:136,cw:270,ch:196};
    const TX=u=>L.tx+L.tw*u;let g='';
    /* track */
    PG_STAGE.forEach((s,i)=>{const a=TX(s.a),b=TX(s.b),on=t>=s.a&&t<s.b+(i===5?.01:0);
      g+=`<rect x="${f1(a+1)}" y="${L.ty-7}" width="${f1(b-a-2)}" height="14" rx="5" style="fill:${on?'var(--life)':'var(--panel-2)'};stroke:var(--line)"/>`;
      g+=`<text x="${f1((a+b)/2)}" y="${L.ty-14}" class="t-xs t-mid" style="fill:var(--ink);font-weight:${on?700:500}">${N||i===4?s.s:s.n}</text>`});
    [[.16,'conception'],[.38,'wk 13'],[.58,'wk 27'],[.78,'wk 40']].forEach(([u,l])=>{g+=`<text x="${f1(TX(u))}" y="${L.ty+30}" class="t-xs t-mid">${N&&u===.16?'conc.':l}</text>`});
    const mx=TX(t);g+=`<path d="M${f1(mx)} ${L.ty+9}l-6 9h12z" style="fill:var(--ink)"/><circle cx="${f1(mx)}" cy="${L.ty}" r="5" style="fill:var(--panel);stroke:var(--ink);stroke-width:2.4"/>`;
    /* lamps */
    PG_LAMP.forEach((l,i)=>{const y=L.ry+i*L.rh,on=t>=l.t,fresh=on?1-ramp(t,l.t,l.t+.06):0;
      if(fresh>0)g+=`<circle cx="${L.rx+8}" cy="${y}" r="${f1(8+8*fresh)}" style="fill:var(--risk);opacity:${f1(.3*fresh)}"/>`;
      g+=`<circle cx="${L.rx+8}" cy="${y}" r="6.5" style="fill:${on?'var(--risk)':'var(--panel)'};stroke:${on?'var(--risk)':'var(--line)'};stroke-width:1.6"/>`;
      g+=`<text x="${L.rx+22}" y="${y+4}" class="t-sm" style="fill:${on?'var(--ink)':'var(--muted)'};font-weight:${on?700:500}">${l.n}</text>`;
      g+=`<text x="${L.rx+L.rw}" y="${y+4}" class="t-xs t-end" style="fill:${on?'var(--ink)':'var(--muted)'}">${on?l.v:'·'}</text>`});
    /* weight gain chart */
    const c=PG_GWG[gi],wk=40*ramp(t,.16,.78);
    const ax=curveAxes(L.cx,L.cy,L.cw,L.ch,{x0:0,x1:40,y0:0,y1:20,xt:[0,13,27,40],yt:[0,5,10,15,20],yfmt:v=>v+' kg',xlabel:'weeks of pregnancy',ylabel:'total gain: IOM 2009 range'});
    g+=ax.svg;const X=ax.X,Y=ax.Y;
    PG_GWG.forEach((o,i)=>{if(i===gi)return;g+=`<line x1="${f1(X(40)-6+i*0)}" x2="${f1(X(40)-6)}" y1="${f1(Y(o.lo))}" y2="${f1(Y(o.hi))}" style="stroke:var(--muted);stroke-width:3;opacity:.35"/>`});
    if(wk>0){g+=`<path d="M${f1(X(0))} ${f1(Y(0))}L${f1(X(wk))} ${f1(Y(c.hi*wk/40))}L${f1(X(wk))} ${f1(Y(c.lo*wk/40))}Z" style="fill:var(--life);opacity:.35"/>`;
      g+=`<line x1="${f1(X(0))}" y1="${f1(Y(0))}" x2="${f1(X(wk))}" y2="${f1(Y(c.hi*wk/40))}" style="stroke:var(--life);stroke-width:1.6"/><line x1="${f1(X(0))}" y1="${f1(Y(0))}" x2="${f1(X(wk))}" y2="${f1(Y(c.lo*wk/40))}" style="stroke:var(--life);stroke-width:1.6"/>`}
    g+=`<line x1="${f1(X(40)+6)}" x2="${f1(X(40)+6)}" y1="${f1(Y(c.lo))}" y2="${f1(Y(c.hi))}" style="stroke:var(--life);stroke-width:5;stroke-linecap:round"/>`;
    g+=kitLabel(X(1),Y(18.6),`${c.b}: ${c.lo} to ${c.hi} kg at term`)+kitLabel(X(1),Y(16.6),t<.16?'before pregnancy':t<.78?'week '+Math.round(wk):'term reached');
    svg.innerHTML=g;
    const p=phaseOf(PG_STEPS,t);note.innerHTML=noteHTML(PG_STEPS[p]);setA&&setA(p);
  }
  const stop=playWire(rg,$('#pgPlay'),draw,15000,'Replay','pregnancy');
  setA=stepWire($('#pgSteps'),PG_STEPS,rg,draw,stop);
  gb.addEventListener('click',e=>{const b=e.target.closest('[data-gw]');if(!b)return;gi=+b.dataset.gw;$$('[data-gw]',gb).forEach(x=>x.setAttribute('aria-pressed',x===b));draw(+rg.value)});
  draw(+rg.value);

  /* ---------- planning cards ---------- */
  const psv=$('#pgPlan'),pb=$('#pgPlanBtns'),pnote=$('#pgPlanNote');let pi=0,pp=1,stopP=null;
  pb.innerHTML=PG_CARDS.map((c,i)=>`<button class="btn" data-pc="${i}" aria-pressed="${i===0}">${c.b}</button>`).join('');
  function drawPlan(){
    const N=vb(psv,'720 240','400 320'),c=PG_CARDS[pi];
    const L=N?{x:24,w:352,y:70,rh:70,lab:-14}:{x:40,w:640,y:64,rh:62,lab:-12};
    let g=`<text x="${L.x}" y="24" class="t-sm" style="fill:var(--ink);font-weight:700">${c.b}</text>`;
    if(c.pcos){const X=v=>L.x+L.w*v/4.5;
      g+=`<text x="${L.x}" y="44" class="t-xs">risk ratio vs women without PCOS (line at 1 = no difference)</text>`;
      [{n:'Obesity',v:2.77,lo:1.88,hi:4.1},{n:'Central obesity',v:1.73}].forEach((r,i)=>{const y=L.y+20+i*L.rh;
        g+=`<text x="${L.x}" y="${y-8}" class="t-sm" style="fill:var(--ink);font-weight:700">${r.n}</text><rect x="${L.x}" y="${y}" width="${f1(X(r.v*pp)-L.x)}" height="18" rx="4" style="fill:var(--hl)"/>`;
        if(r.lo&&pp>.98)g+=`<line x1="${f1(X(r.lo))}" x2="${f1(X(r.hi))}" y1="${y+9}" y2="${y+9}" style="stroke:var(--ink);stroke-width:1.6"/><line x1="${f1(X(r.lo))}" x2="${f1(X(r.lo))}" y1="${y+3}" y2="${y+15}" style="stroke:var(--ink);stroke-width:1.6"/><line x1="${f1(X(r.hi))}" x2="${f1(X(r.hi))}" y1="${y+3}" y2="${y+15}" style="stroke:var(--ink);stroke-width:1.6"/>`;
        g+=`<text x="${f1(X(r.v*pp)+(r.lo?X(4.1)-X(r.v)+8:8))}" y="${y+14}" class="t-xs" style="fill:var(--ink);font-weight:700">${pp>.98?'RR '+r.v:''}</text>`});
      g+=`<line x1="${f1(X(1))}" x2="${f1(X(1))}" y1="${L.y}" y2="${L.y+2*L.rh+10}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/>`+kitLabel(X(1)+4,L.y+6,'1');
      psv.innerHTML=g;pnote.innerHTML=noteHTML(c);return}
    const A=c.ax,X=v=>L.x+L.w*(v-A.a)/(A.b-A.a),axY=L.y+(c.rows?c.rows.length:1)*L.rh+4;
    for(let v=Math.ceil(A.a/A.step)*A.step;v<=A.b;v+=A.step){g+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${axY}" y2="${axY+4}" class="axis"/><text x="${f1(X(v))}" y="${axY+16}" class="t-xs t-mid">${A.fmt?A.fmt(v):v}</text>`}
    g+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${axY}" y2="${axY}" class="axis"/><text x="${L.x+L.w}" y="${axY+32}" class="t-xs t-end">${A.u}</text>`;
    (c.rows||[]).forEach((r,i)=>{g+=`<text x="${L.x}" y="${L.y+i*L.rh+L.lab+4}" class="t-xs" style="fill:var(--ink);font-weight:700">${r}</text>`});
    const cut=A.a+(A.b-A.a)*pp;
    c.bars.forEach(b=>{if(b.a>=cut)return;const y=L.y+b.r*L.rh,x1=X(b.a),x2=X(Math.min(b.b,cut));
      g+=`<rect x="${f1(x1+1)}" y="${y}" width="${f1(Math.max(1,x2-x1-2))}" height="22" rx="5" style="fill:${b.out?'none':b.col};${b.out?'stroke:'+b.col+';stroke-width:1.6;stroke-dasharray:4 3':''};opacity:${b.op||1}"/>`;
      if(b.b<=cut)g+=`<text x="${f1((x1+x2)/2)}" y="${y+15}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">${b.l}</text>`});
    (c.marks||[]).forEach(m=>{if(m.at>cut)return;const x=X(m.at),y=L.y+(m.r||0)*L.rh;
      if(m.tick){g+=`<path d="M${f1(x)} ${y-2}l-5 -8h10z" style="fill:var(--hl)"/>`;if(m.l)g+=kitLabel(x,y-14,m.l,{a:'m'});return}
      g+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${L.y-20}" y2="${axY}" style="stroke:var(--ink);stroke-width:1.4;stroke-dasharray:5 3"/>`+kitLabel(x+4,L.y-24,m.l)});
    psv.innerHTML=g;pnote.innerHTML=noteHTML(c);
  }
  pb.addEventListener('click',e=>{const b=e.target.closest('[data-pc]');if(!b)return;pi=+b.dataset.pc;$$('[data-pc]',pb).forEach(x=>x.setAttribute('aria-pressed',x===b));
    stopP&&stopP();stopP=animate(900,q=>{pp=ease(q);drawPlan()},()=>{stopP=null;pp=1;drawPlan()})});
  drawPlan();

  /* ---------- outcomes after surgery ---------- */
  const osv=$('#pgOut'),ob=$('#pgOutBtns'),onote=$('#pgOutNote');let oi=0,op=1,stopO=null;
  ob.innerHTML=PG_OUT.map((c,i)=>`<button class="btn" data-po="${i}" aria-pressed="${i===0}">${c.b}</button>`).join('');
  function drawOut(){
    const N=vb(osv,'720 300','400 440'),c=PG_OUT[oi];
    const L=N?{lx:20,bx:20,bw:300,y0:62,rh:c.pair?86:62,bh:16}:{lx:20,bx:270,bw:380,y0:56,rh:c.pair?56:38,bh:16};
    const X=v=>L.bx+L.bw*v/c.max;
    let g=`<text x="20" y="22" class="t-sm" style="fill:var(--ink);font-weight:700">${c.h}</text>`;
    if(c.or)g+=`<line x1="${f1(X(1))}" x2="${f1(X(1))}" y1="34" y2="${L.y0+c.rows.length*L.rh-10}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/>`+kitLabel(X(1),34,'1',{a:'m'});
    c.rows.forEach((r,i)=>{const y=L.y0+i*L.rh,by=N?y+6:y;
      g+=`<text x="${L.lx}" y="${N?y-4:by+12}" class="t-sm" style="fill:var(--ink);font-weight:700">${r.n}</text>`;
      if(c.or){const a=Math.min(X(1),X(lerp(1,r.v,op))),w=Math.abs(X(lerp(1,r.v,op))-X(1));
        g+=`<rect x="${f1(a)}" y="${by}" width="${f1(Math.max(2,w))}" height="${L.bh}" rx="4" style="fill:${r.v>1?'var(--risk)':'var(--good)'}"/><text x="${f1(Math.max(X(r.v),X(1))+6)}" y="${by+12}" class="t-xs" style="fill:var(--ink);font-weight:700">${op>.98?'OR '+r.v:''}</text>`}
      else{g+=`<rect x="${L.bx}" y="${by}" width="${f1(Math.max(2,X(r.v*op)-L.bx))}" height="${L.bh}" rx="4" style="fill:var(--life)"/><text x="${f1(X(r.v*op)+6)}" y="${by+12}" class="t-xs" style="fill:var(--ink);font-weight:700">${op>.98?r.v+'%':''}</text>`;
        g+=`<rect x="${L.bx}" y="${by+L.bh+4}" width="${f1(Math.max(2,X(r.w*op)-L.bx))}" height="${L.bh-4}" rx="3" style="fill:none;stroke:var(--ink);stroke-width:1.3"/><text x="${f1(X(r.w*op)+6)}" y="${by+L.bh+14}" class="t-xs">${op>.98?r.w+'%':''}</text>`}
    });
    osv.innerHTML=g;onote.innerHTML=noteHTML(c);
  }
  ob.addEventListener('click',e=>{const b=e.target.closest('[data-po]');if(!b)return;oi=+b.dataset.po;$$('[data-po]',ob).forEach(x=>x.setAttribute('aria-pressed',x===b));
    stopO&&stopO();stopO=animate(650,q=>{op=ease(q);drawOut()},()=>{stopO=null;op=1;drawOut()})});
  drawOut();
  const prevR=redraws.pregnancy;redraws.pregnancy=()=>{prevR&&prevR();drawPlan();drawOut()};
  const prevH=onHide.pregnancy;onHide.pregnancy=()=>{prevH&&prevH();stopP&&stopP();stopO&&stopO();stopP=stopO=null;pp=op=1};
};
/* =============== 4.3 Living with obesity =============== */
inits.living=()=>{
  /* ---------- the years after weight loss ----------
     x = months after the end of active weight loss (0..60), y = share of the lost weight regained (%), calculated here
     from published group means. Each series runs as a straight (schematic) line from 0 to its published end point. */
  const svg=$('#lvSvg'),rg=$('#lvT'),note=$('#lvNote'),rd=$('#lvRead'),lb=$('#lvLayers');
  const MX=60;
  const SER=[
   {ly:'contact',lab:'WLM: monthly contact',sh:'Monthly contact 47%',m:30,v:47,col:'var(--life)'},
   {ly:'contact',lab:'WLM: self-directed',sh:'Self-directed 65%',m:30,v:65,col:'var(--life)',dash:'6 4'},
   {ly:'contact',lab:'STOP Regain: face to face',sh:'Face to face 13%',m:18,v:13,col:'var(--tx)'},
   {ly:'contact',lab:'STOP Regain: newsletter only',sh:'Newsletter 25%',m:18,v:25,col:'var(--tx)',dash:'6 4'},
   {ly:'med',lab:'SURMOUNT-4: tirzepatide continued',sh:'Continued −21%',m:12,v:-21,col:'var(--rx-drug)'},
   {ly:'med',lab:'SURMOUNT-4: switched to placebo',sh:'Placebo 53%',m:12,v:53,col:'var(--rx-drug)',dash:'6 4'},
   {ly:'med',lab:'STEP 1 extension: all treatment stopped',sh:'Stopped 67%',m:12,v:67,col:'var(--hl)',dash:'2 3'},
   {ly:'reg',lab:'NWCR registry members (self-selected)',sh:'NWCR 24% at 5 y',m:60,v:24,col:'var(--gold)'}
  ];
  const LAYERS=[
   {id:'contact',b:'Follow-up contact',ev:'Randomised trials',from:.28,col:'var(--life)',
    say:'Regular contact slowed regain: WLM 4.0 vs 5.5 kg at 30 months; STOP Regain 2.5 vs 4.9 kg at 18 months. <sup class="c" data-ref="Svetkey2008WLM,Wing2006STOPRegain" title="Source 534,604"><a href="/obesity/sources/#src-Svetkey2008WLM">534,604</a></sup>'},
   {id:'med',b:'Medicine continued',ev:'Randomised trials',from:.08,col:'var(--rx-drug)',
    say:'Stopping a GLP-1-based medicine was followed by regain; continuing it held or added to the loss. <sup class="c" data-ref="Aronne2024SURMOUNT4,Wilding2022STEP1ext" title="Source 25,601"><a href="/obesity/sources/#src-Aronne2024SURMOUNT4">25,601</a></sup>'},
   {id:'act',b:'Activity',ev:'Observational',from:.55,col:'var(--accent)',
    say:'More than 250 min/week goes with better maintenance in observational studies; no well-designed trial tests it for preventing regain. <sup class="c" data-ref="Donnelly2009ACSM" title="Source 125"><a href="/obesity/sources/#src-Donnelly2009ACSM">125</a></sup>'},
   {id:'sleep',b:'Sleep',ev:'Early evidence',from:.55,col:'var(--pyy)',
    say:'In one trial, sleep counselling added about 1.2 hours a night and people ate 270 kcal a day less than controls. <sup class="c" data-ref="Tasali2022" title="Source 540"><a href="/obesity/sources/#src-Tasali2022">540</a></sup>'},
   {id:'mind',b:'Mental-health care',ev:'Established for BED',from:.55,col:'var(--hl)',
    say:'Low mood and obesity feed each other; CBT treats binge-eating disorder. <sup class="c" data-ref="Luppino2010,Hilbert2019" title="Source 229,346"><a href="/obesity/sources/#src-Luppino2010">229,346</a></sup>'}
  ];
  const on={contact:true,med:true,act:true,sleep:true,mind:true};
  lb.innerHTML=LAYERS.map(L=>`<button class="btn" data-ly="${L.id}" aria-pressed="true">${L.b}</button>`).join('');
  const STEPS=[
   {from:0,at:.03,k:'Month 0',t:'The body pushes back',
    txt:'One year after an average 13.5 kg loss on a very-low-energy diet, leptin, peptide YY, cholecystokinin and insulin were still lower and ghrelin still higher than at baseline, and hunger was still higher. <sup class="c" data-ref="Sumithran2011" title="Source 530"><a href="/obesity/sources/#src-Sumithran2011">530</a></sup> In a model built on trial data, appetite rose by about 100 kcal/day for every kilogram lost, more than three times the fall in energy use. <sup class="c" data-ref="Polidori2016" title="Source 432"><a href="/obesity/sources/#src-Polidori2016">432</a></sup> Reviews describe the usual course as early loss, a plateau at about 6 months, then gradual regain, and say long-term clinical care is needed. <sup class="c" data-ref="Hall2018Maintenance,Franz2007" title="Source 168,210"><a href="/obesity/sources/#src-Hall2018Maintenance">168,210</a></sup>',
    pt:'After weight loss, the body turns hunger up and keeps it up. That is why keeping weight off is hard, for everyone.',
    hook:'Hormonal changes that favour regain (leptin down, ghrelin up) persist 1 year after weight loss. <sup class="c" data-ref="Sumithran2011" title="Source 530"><a href="/obesity/sources/#src-Sumithran2011">530</a></sup>'},
   {from:.08,at:.2,k:'Month 12',t:'When treatment stops',
    txt:'In the STEP 1 extension, all treatment, including lifestyle support, stopped at week 68. People on semaglutide had lost 17.3%; by week 120 they had regained 11.6 percentage points, "two-thirds of their prior weight loss", and most cardiometabolic gains moved back towards baseline. The authors say this confirms the chronicity of obesity. <sup class="c" data-ref="Wilding2022STEP1ext" title="Source 601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">601</a></sup> In SURMOUNT-4, people switched to placebo after a 20.9% lead-in loss gained 14.0% from week 36 to 88. <sup class="c" data-ref="Aronne2024SURMOUNT4" title="Source 25"><a href="/obesity/sources/#src-Aronne2024SURMOUNT4">25</a></sup>',
    pt:'When a weight medicine stops, much of the weight usually comes back within a year. That is the disease returning, like blood pressure rising when a blood-pressure tablet stops.',
    hook:'STEP 1 extension: two-thirds of the weight lost came back within 1 year of stopping. <sup class="c" data-ref="Wilding2022STEP1ext" title="Source 601"><a href="/obesity/sources/#src-Wilding2022STEP1ext">601</a></sup>'},
   {from:.21,at:.23,k:'Month 12',t:'When medicine continues',
    txt:'In SURMOUNT-4, people who continued tirzepatide lost a further 5.5% from week 36 to 88, vs +14.0% on placebo; 89.5% vs 16.6% kept at least 80% of their lead-in loss. <sup class="c" data-ref="Aronne2024SURMOUNT4" title="Source 25"><a href="/obesity/sources/#src-Aronne2024SURMOUNT4">25</a></sup> In STEP 4, weight changed −7.9% with continued semaglutide vs +6.9% after switching to placebo, from week 20 to 68. <sup class="c" data-ref="Rubino2021STEP4" title="Source 478"><a href="/obesity/sources/#src-Rubino2021STEP4">478</a></sup> Long-term use is a decision made with a clinician; see <a href="#sideeffects" data-go="sideeffects">Side effects, safety &amp; stopping</a>. Do not start, stop or change a medicine without a clinician.',
    pt:'For many people, these medicines work while they are taken, like other medicines for long-term conditions.',
    hook:'SURMOUNT-4: −5.5% further with tirzepatide vs +14.0% regain on placebo. <sup class="c" data-ref="Aronne2024SURMOUNT4" title="Source 25"><a href="/obesity/sources/#src-Aronne2024SURMOUNT4">25</a></sup>'},
   {from:.28,at:.5,k:'Months 18–30',t:'Follow-up contact',
    txt:'In STOP Regain (people who had lost a mean 19.3 kg), 18-month regain was 2.5 kg face to face, 4.7 kg online and 4.9 kg with newsletters only. <sup class="c" data-ref="Wing2006STOPRegain" title="Source 604"><a href="/obesity/sources/#src-Wing2006STOPRegain">604</a></sup> In the Weight Loss Maintenance trial, regain at 30 months was 4.0 kg with monthly personal contact vs 5.5 kg self-directed. <sup class="c" data-ref="Svetkey2008WLM" title="Source 534"><a href="/obesity/sources/#src-Svetkey2008WLM">534</a></sup> Across 45 trials, diet-plus-activity programmes reduced regain by 1.56 kg at 12 months. <sup class="c" data-ref="Dombrowski2014" title="Source 122"><a href="/obesity/sources/#src-Dombrowski2014">122</a></sup> The 2013 guideline notes that even with contact every two months after year 1, regain averages 1–2 kg a year, but losses stay larger than with usual care. <sup class="c" data-ref="Jensen2014Guideline" title="Source 262"><a href="/obesity/sources/#src-Jensen2014Guideline">262</a></sup>',
    pt:'Keeping in touch with a coach, nurse or group, in person or remotely, slows regain. It does not have to stop completely to be worth it.',
    hook:'Maintenance meta-analysis: −1.56 kg regain at 12 months with diet-plus-activity programmes. <sup class="c" data-ref="Dombrowski2014" title="Source 122"><a href="/obesity/sources/#src-Dombrowski2014">122</a></sup>'},
   {from:.55,at:.66,k:'Ongoing',t:'Activity, sleep and mood',
    txt:'ACSM: after weight loss, maintenance is better with more than 250 min/week of activity in cross-sectional and prospective studies, but no well-designed trial shows it prevents regain. <sup class="c" data-ref="Donnelly2009ACSM" title="Source 125"><a href="/obesity/sources/#src-Donnelly2009ACSM">125</a></sup> In a 24-month trial in women, those who kept off 10% or more reported about 275 min/week. <sup class="c" data-ref="Jakicic2008" title="Source 248"><a href="/obesity/sources/#src-Jakicic2008">248</a></sup> Sleep extension helped people eat less in one trial. <span class="ev early">Early evidence</span> <sup class="c" data-ref="Tasali2022" title="Source 540"><a href="/obesity/sources/#src-Tasali2022">540</a></sup> Obesity raised the odds of later depression (OR 1.55), and depression the odds of later obesity (OR 1.58). <sup class="c" data-ref="Luppino2010" title="Source 346"><a href="/obesity/sources/#src-Luppino2010">346</a></sup> Addressing weight stigma and internalised bias is part of mental-health care. <span class="ev est">Established</span> <sup class="c" data-ref="Wu2018,Pearl2018WBI" title="Source 420,610"><a href="/obesity/sources/#src-Wu2018">420,610</a></sup>',
    pt:'Moving more, sleeping enough and getting help for low mood all support health, whatever happens to weight.',
    hook:'Activity matters more for maintenance and health than for initial loss. <sup class="c" data-ref="Thorogood2011,Donnelly2009ACSM" title="Source 125,547"><a href="/obesity/sources/#src-Thorogood2011">125,547</a></sup>'},
   {from:.8,at:1,k:'Year 5 and beyond',t:'Years on',
    txt:'In the National Weight Control Registry (2886 adults who had lost at least 13.6 kg and kept it off for a year), mean loss was 31.3 kg at entry, 23.8 kg at 5 years and 23.1 kg at 10 years; more than 87% were still at least 10% below their maximum. It is a self-selected group of successful maintainers, not a typical population. <sup class="c" data-ref="Thomas2014NWCR" title="Source 546"><a href="/obesity/sources/#src-Thomas2014NWCR">546</a></sup> About 20% succeed at long-term maintenance defined as 10% kept off for a year. <sup class="c" data-ref="Wing2005AJCN" title="Source 603"><a href="/obesity/sources/#src-Wing2005AJCN">603</a></sup> Behavioural programmes still lowered cardiometabolic risk factors 5 years on despite regain. <sup class="c" data-ref="HartmannBoyce2023" title="Source 219"><a href="/obesity/sources/#src-HartmannBoyce2023">219</a></sup>',
    pt:'Some weight often returns, yet health gains can last for years. Long-term care is normal for a long-term condition.',
    hook:'Registry: 31.3 kg lost at entry, 23.1 kg still off at 10 years (self-selected). <sup class="c" data-ref="Thomas2014NWCR" title="Source 546"><a href="/obesity/sources/#src-Thomas2014NWCR">546</a></sup>'}
  ];
  const stopP=playWire(rg,$('#lvPlay'),draw,20000,'Replay','living');
  const setStep=stepWire($('#lvSteps'),STEPS,rg,draw,stopP);
  lb.addEventListener('click',e=>{const b=e.target.closest('[data-ly]');if(!b)return;on[b.dataset.ly]=!on[b.dataset.ly];b.setAttribute('aria-pressed',on[b.dataset.ly]);draw(+rg.value)});
  function draw(t){
    vb(svg,'720 380','400 580');const N=NARROW(),p=phaseOf(STEPS,t),S=STEPS[p];setStep(p);
    const mo=MX*t;
    const L=N?{x:48,y:34,w:330,h:250}:{x:58,y:34,w:410,h:290};
    const ax=curveAxes(L.x,L.y,L.w,L.h,{x0:0,x1:MX,y0:-30,y1:100,xt:[0,12,24,36,48,60],yt:[-25,0,25,50,75,100],yfmt:v=>v+'%',xlabel:'months after weight loss',ylabel:'share of the lost weight regained'});
    let s=ax.svg;
    const X=ax.X,Y=ax.Y;
    s+=`<line x1="${L.x}" x2="${L.x+L.w}" y1="${f1(Y(0))}" y2="${f1(Y(0))}" style="stroke:var(--muted);stroke-width:1.2"/>`;
    s+=`<text x="${L.x+L.w-4}" y="${f1(Y(0)-5)}" class="t-xs t-end">no regain</text><text x="${L.x+L.w-4}" y="${f1(Y(100)+12)}" class="t-xs t-end">all regained</text>`;
    /* biology pushes back: an upward arrow, strongest at the start */
    const bio=1-ramp(t,.06,.16);
    if(bio>0){const bx=X(5),by0=Y(-5),by1=Y(40);
      s+=`<g style="opacity:${f1(bio)}"><path d="M${f1(bx)} ${f1(by0)}V${f1(by1)}" style="stroke:var(--agrp);stroke-width:4;fill:none" marker-end="url(#lvArr)"/>`+kitLabel(bx+8,by1+14,'hunger signals stay up')+kitLabel(bx+8,by1+27,'for a year or more')+`</g>`}
    const lbls=[];
    SER.forEach(Sr=>{
      const vis=Sr.ly==='reg'||on[Sr.ly];if(!vis)return;
      const P=[[0,0],[Sr.m,Sr.v]];
      const ln=plotLine(P,X,Y,{col:Sr.col,lw:2.6,dash:Sr.dash,upto:Math.min(mo,Sr.m)});s+=ln.svg;
      if(ln.end&&mo<Sr.m)s+=`<circle cx="${f1(ln.end[0])}" cy="${f1(ln.end[1])}" r="3.5" style="fill:${Sr.col}"/>`;
      if(mo>=Sr.m){const e=[X(Sr.m),Y(Sr.v)];s+=`<circle cx="${f1(e[0])}" cy="${f1(e[1])}" r="5" style="fill:${Sr.dash?'var(--panel)':Sr.col};stroke:${Sr.col};stroke-width:2.4"/>`;lbls.push(Sr.m>=MX*.9?[e[0]-4,e[1]-10,Sr.sh,'e']:[e[0]+8,e[1]+3.5,Sr.sh])}
    });
    lbls.forEach(l=>{s+=kitLabel(l[0],l[1],l[2],{a:l[3]})});
    /* the time cursor */
    const cx=X(mo);
    s+=`<line x1="${f1(cx)}" x2="${f1(cx)}" y1="${L.y}" y2="${L.y+L.h}" style="stroke:var(--ink);stroke-width:1;stroke-dasharray:3 3;opacity:.5"/>`;
    s+=`<text x="${f1(Math.min(cx+4,L.x+L.w-50))}" y="${L.y+L.h-6}" class="t-xs" style="fill:var(--ink);font-weight:700">${mo<24?Math.round(mo)+' mo':f1(mo/12)+' y'}</text>`;
    /* supports stack */
    const K=N?{x:16,y:350,w:368,bh:34,g:6}:{x:500,y:56,w:206,bh:46,g:10};
    s+=`<text x="${K.x}" y="${K.y-12}" class="t-sm" style="fill:var(--ink);font-weight:700">Supports layered</text>`;
    LAYERS.forEach((Ly,i)=>{
      const reached=t>=Ly.from,act=reached&&on[Ly.id],yy=K.y+(LAYERS.length-1-i)*(K.bh+K.g);
      const grow=ramp(t,Ly.from,Ly.from+.05);
      s+=`<g style="opacity:${act?f1(.45+.55*grow):.3}"><rect x="${K.x}" y="${yy}" width="${K.w}" height="${K.bh}" rx="9" style="fill:var(--panel-2);stroke:${act?Ly.col:'var(--line)'};stroke-width:${act?2:1}"/>`;
      s+=`<rect x="${K.x}" y="${yy}" width="6" height="${K.bh}" rx="3" style="fill:${Ly.col}"/>`;
      s+=`<text x="${K.x+16}" y="${f1(yy+(N?K.bh/2+4.5:19))}" class="t-lbl">${Ly.b}</text>`;
      s+=N?`<text x="${K.x+K.w-10}" y="${f1(yy+K.bh/2+4)}" class="t-xs t-end">${Ly.ev}</text>`:`<text x="${K.x+16}" y="${f1(yy+35)}" class="t-xs">${Ly.ev}${on[Ly.id]?'':' · hidden'}</text>`;
      s+=`</g>`});
    s=`<defs>${marker('lvArr','var(--agrp)',5)}</defs>`+s;
    svg.innerHTML=s;
    note.innerHTML=noteHTML(S);
    rd.innerHTML=LAYERS.map(Ly=>`<li class="${on[Ly.id]?'':'off'}"><i style="background:${Ly.col}"></i><span><b>${Ly.b}.</b> ${Ly.say}</span></li>`).join('');
  }
  draw(+rg.value);

  /* ---------- domains of daily life ---------- */
  const DM=[
   {b:'Work',k:'Work',t:'Fair treatment at work',
    say:['Weight discrimination is common at work. Institutional forms, such as in employment, and interpersonal forms, such as name-calling, were sometimes more common than gender or race discrimination. <sup class="c" data-ref="Puhl2008Discrimination" title="Source 441"><a href="/obesity/sources/#src-Puhl2008Discrimination">441</a></sup>','The weight-specific quality-of-life questionnaire IWQOL-Lite has a Work scale among its five, a sign of how much work life matters. <sup class="c" data-ref="Kolotkin2001" title="Source 297"><a href="/obesity/sources/#src-Kolotkin2001">297</a></sup>'],
    guide:['The 2020 consensus calls for clear policies that prohibit weight-based discrimination. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>']},
   {b:'Travel & transport',k:'Getting around',t:'Seats and seatbelts that fit',
    say:['In US fatal crashes 2003–2009, drivers of normal weight had 67% higher odds of wearing a seatbelt than drivers with the highest BMI (OR 1.67). Poor seatbelt fit is one practical reason seatbelt extenders matter. <sup class="c" data-ref="Jehle2014" title="Source 261"><a href="/obesity/sources/#src-Jehle2014">261</a></sup>'],
    guide:['The consensus says suitable infrastructure for people with obesity should be a standard requirement for medical facilities (unanimous). <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> Outside health care, asking for a seatbelt extender is a practical step.']},
   {b:'Clothing & equipment',k:'Things that fit',t:'The right cuff, chair and bed',
    say:['Kiosk blood pressure machines usually have a single cuff size that is too small for most US adults. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup>','A cuff that is too small overestimates blood pressure, a common error in people with larger arms; the AHA lists large and extra-large adult cuffs, and a thigh cuff when the arm is larger than the largest cuff. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup>','Ill-fitting clothes are one of the stigmatising framings in news images. <sup class="c" data-ref="Puhl2013Headless" title="Source 444"><a href="/obesity/sources/#src-Puhl2013Headless">444</a></sup>'],
    guide:['The consensus says suitable infrastructure for people with obesity should be a standard requirement for accrediting medical facilities (unanimous). <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup> See <a href="#nursing" data-go="nursing">Nursing care</a>.']},
   {b:'Relationships & intimacy',k:'Relationships',t:'Partners, family and friends',
    say:['IWQOL-Lite measures five areas: Physical Function, Self-Esteem, Sexual Life, Public Distress and Work, with scale reliability of 0.90–0.94. Sexual life and public distress are named parts of weight-related quality of life. <sup class="c" data-ref="Kolotkin2001" title="Source 297"><a href="/obesity/sources/#src-Kolotkin2001">297</a></sup>','Stigma can come from close to home: among 361 adolescents at weight-loss camps, parents were among the perpetrators of weight-based teasing (37%). <sup class="c" data-ref="Puhl2013Bullying" title="Source 443"><a href="/obesity/sources/#src-Puhl2013Bullying">443</a></sup>'],
    guide:['The AAP asks clinicians to address weight stigma and bullying at the visit and to model non-biased language for families. <sup class="c" data-ref="Pont2017AAP" title="Source 433"><a href="/obesity/sources/#src-Pont2017AAP">433</a></sup> More in <a href="#stigma" data-go="stigma">Weight stigma &amp; bias</a>.']},
   {b:'Mental health',k:'Mood',t:'Mood and weight feed each other',
    say:['Obesity at baseline raised the odds of later depression (OR 1.55; 95% CI 1.22–1.98), and depression raised the odds of later obesity (OR 1.58; 95% CI 1.33–1.87). <sup class="c" data-ref="Luppino2010" title="Source 346"><a href="/obesity/sources/#src-Luppino2010">346</a></sup>','Weight stigma and internalised weight bias are linked to depression, anxiety and disordered eating. <span class="ev est">Established</span> <sup class="c" data-ref="Wu2018,Pearl2018WBI" title="Source 420,610"><a href="/obesity/sources/#src-Wu2018">420,610</a></sup>'],
    guide:['Addressing stigma and internalised bias is part of mental-health care for people living with obesity. <sup class="c" data-ref="Wu2018,Pearl2018WBI" title="Source 420,610"><a href="/obesity/sources/#src-Wu2018">420,610</a></sup> Asking for help with mood is part of looking after health.']},
   {b:'Binge eating',k:'Eating',t:'Binge-eating disorder: screen, then refer',
    say:['Lifetime prevalence of BED in a US national survey was 3.5% in women and 2.0% in men; BED was associated with severe obesity, and only a minority ever sought treatment. <sup class="c" data-ref="Hudson2007" title="Source 237"><a href="/obesity/sources/#src-Hudson2007">237</a></sup>','BEDS-7 is a brief screen that flags possible BED for full evaluation; it screens rather than diagnoses. <sup class="c" data-ref="Herman2016BEDS7" title="Source 223"><a href="/obesity/sources/#src-Herman2016BEDS7">223</a></sup>'],
    guide:['Psychotherapy, mostly CBT, has large effects on binge episodes. <sup class="c" data-ref="Hilbert2019" title="Source 229"><a href="/obesity/sources/#src-Hilbert2019">229</a></sup> Lisdexamfetamine is labelled for moderate to severe BED in adults, "not indicated or recommended for weight loss". <sup class="c" data-ref="FDA-Vyvanse" title="Source 149"><a href="/obesity/sources/#src-FDA-Vyvanse">149</a></sup> The screen below shows what a positive result means.']},
   {b:'Sleep',k:'Sleep',t:'Sleep and appetite',
    say:['Short sleep was linked to obesity in adults (pooled OR 1.55) in a meta-analysis of 634,511 people; causal inference is difficult. <sup class="c" data-ref="Cappuccio2008" title="Source 61"><a href="/obesity/sources/#src-Cappuccio2008">61</a></sup>','Two days of restricted sleep in 12 young men lowered leptin by 18%, raised ghrelin by 28% and raised hunger by 24%. <sup class="c" data-ref="Spiegel2004" title="Source 521"><a href="/obesity/sources/#src-Spiegel2004">521</a></sup>'],
    guide:['In a trial in 80 adults who usually slept under 6.5 hours, sleep-hygiene counselling added about 1.2 hours a night and they ate 270 kcal a day less than controls. <span class="ev early">Early evidence</span> <sup class="c" data-ref="Tasali2022" title="Source 540"><a href="/obesity/sources/#src-Tasali2022">540</a></sup>']}
  ];
  const db=$('#lvDmBtns'),dp=$('#lvDm');
  db.innerHTML=DM.map((d,i)=>`<button class="btn" data-dm="${i}" aria-pressed="${i===0}">${d.b}</button>`).join('');
  function drawDm(i){const d=DM[i];
    dp.innerHTML=`<div class="kicker">${d.k}</div><h4>${d.t}</h4><div class="kicker">What studies show</div><ul>${d.say.map(x=>`<li>${x}</li>`).join('')}</ul><div class="kicker">What guidelines and experts say</div><ul>${d.guide.map(x=>`<li>${x}</li>`).join('')}</ul>`}
  db.addEventListener('click',e=>{const b=e.target.closest('[data-dm]');if(!b)return;$$('[data-dm]',db).forEach(x=>x.setAttribute('aria-pressed',x===b));drawDm(+b.dataset.dm)});
  drawDm(0);

  /* ---------- BEDS-7: screening arithmetic ---------- */
  const bs=$('#lvBeds'),bn=$('#lvBNote'),sel=$('#lvPrev');
  const SENS=1,SPEC=.387;
  let shown=[0,0],stopB=null;
  function counts(pv){const tp=pv*SENS,fp=(1-pv)*(1-SPEC);return {tp,fp,tn:1-pv-fp,ppv:tp/(tp+fp)}}
  function drawB(u){
    vb(bs,'720 280','400 470');const N=NARROW(),pv=+sel.value,C=counts(pv);
    const tp=Math.round(lerp(shown[0],C.tp*100,u)),fp=Math.round(lerp(shown[1],C.fp*100,u));
    const ia=iconArray(N?62:40,N?20:14,{n:100,cols:10,size:N?24:21,gap:N?4:4,shape:'dot',groups:[{k:tp,col:'var(--hl)'},{k:fp,col:'var(--warn)'}],base:'var(--line)'});
    let s=ia.svg;
    const tx=N?24:340,ty=N?ia.h+56:50,lh=N?28:30;
    const rows=[['var(--hl)',`${f1(C.tp*1000).replace('.0','')} per 1000`,'have BED and are flagged'],['var(--warn)',`${Math.round(C.fp*1000)} per 1000`,'are flagged but do not have BED'],['var(--line)',`${Math.round(C.tn*1000)} per 1000`,'are not flagged']];
    rows.forEach((r,i)=>{const y=ty+i*lh*1.6;s+=`<circle cx="${tx+7}" cy="${y-4}" r="7" style="fill:${r[0]}"/><text x="${tx+22}" y="${y}" class="t-lbl" style="font-size:15px">${r[1]}</text><text x="${tx+22}" y="${y+16}" class="t-sm">${r[2]}</text>`});
    const py=ty+3*lh*1.6+6;
    s+=`<text x="${tx}" y="${py}" class="t-big" style="fill:var(--life)">${Math.round(C.ppv*100)}%</text><text x="${tx+(N?56:62)}" y="${py}" class="t-sm" style="fill:var(--ink)">of people flagged have BED</text>`;
    s+=`<text x="${tx}" y="${py+18}" class="t-xs">each dot = 1 in 100 screened (rounded)</text>`;
    bs.innerHTML=s;
    bn.innerHTML=`<div class="kicker">Calculated here</div><h4>A positive screen means "look closer"</h4><div class="big-num">${Math.round(C.ppv*100)}%</div><p>At ${f1(pv*100)}% prevalence, about ${Math.round(C.ppv*100)} in 100 people who screen positive would have BED; the rest are flagged because specificity is 38.7%. Sensitivity of 100% means a negative screen rules BED out well in this arithmetic. <sup class="c" data-ref="Herman2016BEDS7" title="Source 223"><a href="/obesity/sources/#src-Herman2016BEDS7">223</a></sup> That is why BEDS-7 leads to a full evaluation, not a diagnosis.</p><div class="pt"><b>In plain words</b>A positive screen is a reason to talk to a clinician, not a label. Binge-eating disorder is treatable, and talking therapies help most. <sup class="c" data-ref="Hilbert2019" title="Source 229"><a href="/obesity/sources/#src-Hilbert2019">229</a></sup></div>`;
  }
  sel.addEventListener('change',()=>{if(stopB)stopB();const pv=+sel.value,C=counts(pv),from=shown.slice();
    stopB=animate(700,q=>{shown=from;drawB(ease(q))},()=>{stopB=null;shown=[C.tp*100,C.fp*100];drawB(0)})});
  {const C=counts(+sel.value);shown=[C.tp*100,C.fp*100];drawB(0)}
  const prevR=redraws.living;redraws.living=()=>{prevR&&prevR();drawB(0)};
  const prevH=onHide.living;onHide.living=()=>{prevH&&prevH();if(stopB){stopB();stopB=null;const C=counts(+sel.value);shown=[C.tp*100,C.fp*100]}};
};
/* =============== 4.4 Nursing care =============== */
/* Main player: a hospital stay in six stations. Each sixth of the timeline animates one vignette: admission and
   handling, blood pressure cuff fit, skin, airway position, injections, and observations after bariatric surgery.
   Numbers drawn in the scenes are published values; the simulated patient's readings are illustrative. */
const NU_ST=['Admission','BP cuff','Skin','Airway','Injections','After surgery'];
const NU_STEPS=[
 {from:0,at:.09,k:'Station 1 of 6',t:'Admission, equipment and handling',
  txt:'Start by asking permission to discuss weight, without judgement: the first of the modified 5As. <sup class="c" data-ref="Vallis2013" title="Source 561"><a href="/obesity/sources/#src-Vallis2013">561</a></sup> Many obesity-related safety incidents reported in the UK involved a lack of suitable equipment, and hospitals should invest in appropriately rated beds, operating tables, trolleys and lifting aids. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup> The Revised NIOSH Lifting Equation gives a recommended maximum of 35 lb (about 16 kg) for patient-handling tasks; above this, assistive devices should be used. <sup class="c" data-ref="Waters2007" title="Source 586"><a href="/obesity/sources/#src-Waters2007">586</a></sup> An international consensus says the right infrastructure should be a standard requirement for accrediting medical facilities. <sup class="c" data-ref="Rubino2020Stigma" title="Source 477"><a href="/obesity/sources/#src-Rubino2020Stigma">477</a></sup>',
  pt:'You can ask for equipment that fits you: a wider chair, a stronger bed, a seatbelt extender. Good care includes the right equipment.',
  hook:'NIOSH: 35 lb (about 16 kg) recommended maximum for manual patient-handling tasks. <sup class="c" data-ref="Waters2007" title="Source 586"><a href="/obesity/sources/#src-Waters2007">586</a></sup>'},
 {from:1/6,at:.27,k:'Station 2 of 6',t:'A cuff that fits the arm',
  txt:'The 2019 AHA statement: measure arm circumference at the midpoint between acromion and olecranon, and choose a cuff whose bladder length is 75% to 100% and width 37% to 50% of the arm circumference, on bare skin. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup> A cuff that is too small overestimates blood pressure, a common error in people with larger arms. <span class="ev est">Established</span> <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup> A tronco-conical cuff may suit some people, and a thigh cuff can be used if the arm is larger than the largest arm cuff. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup>',
  pt:'You can ask your nurse for a larger blood pressure cuff. A small cuff can give a falsely high reading.',
  hook:'AHA 2019: bladder length 75 to 100% and width 37 to 50% of arm circumference; too small reads high. <sup class="c" data-ref="Muntner2019" title="Source 376"><a href="/obesity/sources/#src-Muntner2019">376</a></sup>'},
 {from:2/6,at:.43,k:'Station 3 of 6',t:'Skin and pressure injury',
  txt:'In a dose-response meta-analysis of 31,389 hospitalised adults, the link between BMI and pressure injury was J-shaped: odds ratios vs normal weight were 1.70 for underweight, 1.12 for obesity and 1.70 for “morbid obesity”. <sup class="c" data-ref="Jia2024" title="Source 264"><a href="/obesity/sources/#src-Jia2024">264</a></sup> Immobile people with a high BMI need more staff to reposition them. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup> Obesity changes skin barrier function, sweat, lymphatic flow and wound healing, and is linked to intertrigo, cellulitis and lymphoedema. <sup class="c" data-ref="Yosipovitch2007" title="Source 617"><a href="/obesity/sources/#src-Yosipovitch2007">617</a></sup> A systematic review found no evidence on preventing intertrigo in skin folds and no firm evidence on any treatment. <sup class="c" data-ref="Mistiaen2010" title="Source 370"><a href="/obesity/sources/#src-Mistiaen2010">370</a></sup>',
  pt:'Skin in folds can get sore. Checking it and changing position regularly, with enough people to help, protects it.',
  hook:'Pressure injury risk vs BMI is J-shaped (ORs 1.70, 1.12, 1.70). <sup class="c" data-ref="Jia2024" title="Source 264"><a href="/obesity/sources/#src-Jia2024">264</a></sup>'},
 {from:3/6,at:.6,k:'Station 4 of 6',t:'Airway and the ramped position',
  txt:'Difficult intubation occurred in 15.5% of patients with BMI 35 or more vs 2.2% of lean patients. <sup class="c" data-ref="Juvin2003" title="Source 269"><a href="/obesity/sources/#src-Juvin2003">269</a></sup> In 100 patients with BMI over 40, neck circumference and Mallampati score, not BMI, predicted difficulty. <sup class="c" data-ref="Brodsky2002" title="Source 54"><a href="/obesity/sources/#src-Brodsky2002">54</a></sup> The ramped position, with the tragus of the ear level with the sternum, improves the laryngoscopy view and is recommended as the default for induction; after surgery, patients should be managed sitting or with 45° head-up tilt. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup> STOP-BANG is the best-validated sleep apnoea screen; a score of 5 or more suggests significant sleep-disordered breathing. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup>',
  pt:'Raising the head and shoulders makes breathing and airway care easier. Bring your own CPAP machine to hospital if you use one.',
  hook:'Ramped: tragus level with sternum. After surgery: sitting or 45° head-up. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup>'},
 {from:4/6,at:.77,k:'Station 5 of 6',t:'Injections and VTE prophylaxis',
  txt:'Deltoid fat pad thickness in 220 adults was 11.7 mm in women vs 8.3 mm in men; a 16 mm needle would not have reached 5 mm into muscle in 48.4% of women and 17% of men. <sup class="c" data-ref="Poland1997" title="Source 431"><a href="/obesity/sources/#src-Poland1997">431</a></sup> On CT, dorsogluteal depth exceeded 35 mm in 43 of 100 adults. <sup class="c" data-ref="Nisbet2006" title="Source 403"><a href="/obesity/sources/#src-Nisbet2006">403</a></sup> The AAGBI/SOBA guideline advises avoiding intramuscular drugs in obesity because of unpredictable pharmacokinetics, and recommends VTE prophylaxis for anything more than minor surgery. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup> The Lovenox label says the safety and efficacy of prophylactic doses with BMI over 30 “has not been fully determined and there is no consensus for dose adjustment”. <sup class="c" data-ref="FDA-Lovenox" title="Source 145"><a href="/obesity/sources/#src-FDA-Lovenox">145</a></sup>',
  pt:'A standard needle may not reach the muscle through a thicker fat layer. Nurses choose the needle length and site for each person.',
  hook:'A 16 mm deltoid needle missed muscle in 48.4% of women. <sup class="c" data-ref="Poland1997" title="Source 431"><a href="/obesity/sources/#src-Poland1997">431</a></sup>'},
 {from:5/6,at:.93,k:'Station 6 of 6',t:'After bariatric surgery: watch the pulse',
  txt:'In 210 patients after laparoscopic gastric bypass, 9 leaked (4.3%); respiratory distress and a heart rate above 120 beats per minute were the most sensitive signs, and a routine contrast swallow found only 2 of the 9 leaks. <sup class="c" data-ref="Hamilton2003" title="Source 213"><a href="/obesity/sources/#src-Hamilton2003">213</a></sup> Leak signs can be nonspecific: sustained tachycardia, fever, abdominal or shoulder pain and breathing changes. <sup class="c" data-ref="Kim2026Complications" title="Source 284"><a href="/obesity/sources/#src-Kim2026Complications">284</a></sup> Rhabdomyolysis is rare but serious; consider it with deep tissue pain, classically in the buttocks. <sup class="c" data-ref="Nightingale2015" title="Source 401"><a href="/obesity/sources/#src-Nightingale2015">401</a></sup> A team approach to perioperative care is mandatory. <sup class="c" data-ref="Mechanick2019" title="Source 363"><a href="/obesity/sources/#src-Mechanick2019">363</a></sup>',
  pt:'After weight-loss surgery, tell the team at once if you have a racing heart, trouble breathing or new belly pain.',
  hook:'Heart rate above 120 after gastric bypass is a leak warning sign; contrast studies missed 78% of leaks. <sup class="c" data-ref="Hamilton2003" title="Source 213"><a href="/obesity/sources/#src-Hamilton2003">213</a></sup>'}
];
/* pen teaching, from the labels (statements, not instructions) */
const NU_PENS=[
 {b:'Wegovy (semaglutide)',sites:['abdomen','thigh','arm'],
  items:['Weekly injection under the skin of the abdomen, thigh or upper arm. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>','If 2 or more consecutive doses are missed, the label says to restart dose escalation at a lower dosage. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>','Single-dose pens are kept in the fridge at 2 to 8 °C and may be kept at 8 to 30 °C for up to 28 days; FlexTouch pens can be stored for 56 days after first use. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>','Tell the care team about the medicine before any procedure under anaesthesia or deep sedation: there are rare reports of aspiration. <sup class="c" data-ref="FDA-Wegovy" title="Source 150"><a href="/obesity/sources/#src-FDA-Wegovy">150</a></sup>']},
 {b:'Zepbound (tirzepatide)',sites:['abdomen','thigh','backarm'],
  items:['Weekly injection in the abdomen or thigh; another person may inject in the back of the upper arm. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>','A missed dose is given within 4 days (96 hours); if more than 4 days have passed, it is skipped. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>','Single-dose pens are refrigerated and may be kept unrefrigerated, up to 30 °C, for a total of 21 days. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>','It may reduce the effect of oral contraceptive pills: the label advises a non-oral or added barrier method for 4 weeks after starting and each dose increase. <sup class="c" data-ref="FDA-Zepbound" title="Source 152"><a href="/obesity/sources/#src-FDA-Zepbound">152</a></sup>']},
 {b:'Saxenda (liraglutide)',sites:['abdomen','thigh','arm'],
  items:['Daily injection in the abdomen, thigh or upper arm. <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup>','A missed dose is not made up with an extra or larger dose. <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup>','Indicated from age 12 with body weight over 60 kg and obesity. <sup class="c" data-ref="FDA-Saxenda" title="Source 148"><a href="/obesity/sources/#src-FDA-Saxenda">148</a></sup>']}
];

inits.nursing=()=>{
  /* ---------- the hospital stay ---------- */
  const svg=$('#nuSvg'),rg=$('#nuT'),note=$('#nuNote');let setA=null;
  const txt=(x,y,s,c='t-xs',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${c}" style="${st}">${s}</text>`;
  const B='fill:var(--ink);font-weight:700';
  /* 1 admission: scale, equipment, a load bar crossing the 35 lb line */
  function vAdmit(u,N,ox,oy,W){let g='';const sx=ox+(N?90:120),base=oy+(N?236:270);
    g+=`<rect x="${sx-48}" y="${base}" width="96" height="14" rx="4" style="fill:var(--device)"/><rect x="${sx-20}" y="${base+3}" width="40" height="8" rx="2" style="fill:var(--panel)"/>`;
    g+=person(sx,base-170,170,{size:.75}).svg;
    g+=txt(sx,base+32,'a platform scale rated for the person','t-xs t-mid',B);
    const bx=N?ox+200:ox+300,bw=N?150:150,by=oy+40,bh=N?190:220,lim=.42,load=lerp(.12,.95,ramp(u,.15,.8));
    g+=txt(bx,by-14,'manual lifting load','t-xs',B);
    g+=`<rect x="${bx}" y="${by}" width="44" height="${bh}" rx="6" style="fill:var(--panel-2);stroke:var(--line)"/><rect x="${bx}" y="${f1(by+bh*(1-load))}" width="44" height="${f1(bh*load)}" rx="6" style="fill:${load>lim?'var(--risk)':'var(--life)'};opacity:.85"/>`;
    const ly=by+bh*(1-lim);g+=`<line x1="${bx-6}" x2="${bx+60}" y1="${f1(ly)}" y2="${f1(ly)}" style="stroke:var(--ink);stroke-width:1.6;stroke-dasharray:5 3"/>`+txt(bx+64,ly+4,'35 lb ≈ 16 kg','t-xs',B)+txt(bx+64,ly+16,'NIOSH limit');
    const over=load>lim;g+=`<rect x="${bx+56}" y="${by+6}" width="${N?126:150}" height="36" rx="8" style="fill:${over?'var(--life-soft)':'var(--panel)'};stroke:${over?'var(--life)':'var(--line)'};${over?'':'stroke-dasharray:4 3'}"/>`+txt(bx+64,by+21,over?'above the limit:':'below the limit','t-xs',B)+txt(bx+64,by+34,over?'use assistive devices':'');
    if(!N){const ex=ox+540;g+=txt(ex,oy+40,'rated equipment','t-xs',B);
      ['bed','operating table','trolley','lifting aid'].forEach((e,i)=>{const y=oy+62+i*48,on=u>.2+i*.12;
        g+=`<rect x="${ex}" y="${y}" width="130" height="36" rx="8" style="fill:${on?'var(--life-soft)':'var(--panel)'};stroke:${on?'var(--life)':'var(--line)'}"/>`+txt(ex+12,y+22,e,'t-sm',on?B:'')})}
    return g}
  /* 2 BP cuff: arm cross-section with the bladder arc, and the 75-100% band */
  function vCuff(u,N,ox,oy,W){let g='';const ac=lerp(32,48,ramp(u,.05,.55)),xl=u>.68,bl=xl?42:30,r=bl/ac;
    const cx=ox+(N?110:150),cy=oy+(N?120:150),R=ac*(N?2.1:2.5);
    g+=`<circle cx="${cx}" cy="${cy}" r="${f1(R)}" style="fill:var(--lean);opacity:.55;stroke:var(--figure-line)"/><circle cx="${cx}" cy="${cy}" r="${f1(R*.22)}" style="fill:var(--panel);stroke:var(--figure-line)"/>`;
    const a0=-Math.PI/2,a1=a0+2*Math.PI*Math.min(r,.999),Rc=R+7,big=r>.5?1:0;
    g+=`<path d="M${f1(cx+Rc*Math.cos(a0))} ${f1(cy+Rc*Math.sin(a0))}A${f1(Rc)} ${f1(Rc)} 0 ${big} 1 ${f1(cx+Rc*Math.cos(a1))} ${f1(cy+Rc*Math.sin(a1))}" style="fill:none;stroke:${r<.75?'var(--risk)':'var(--device)'};stroke-width:10;stroke-linecap:round"/>`;
    g+=txt(cx,cy+R+30,'upper arm, cross-section','t-xs t-mid',B)+txt(cx,cy+R+44,'(ring = cuff bladder length)','t-xs t-mid');
    const bx=N?ox+20:ox+330,bw=N?340:330,by=N?oy+(N?280:0):oy+50,S=bw/52;
    g+=txt(bx,by,`arm circumference ${ac.toFixed(0)} cm`,'t-sm',B);
    g+=`<rect x="${bx}" y="${by+10}" width="${f1(ac*S)}" height="16" rx="4" style="fill:var(--lean);opacity:.55"/><rect x="${f1(bx+ac*S*.75)}" y="${by+8}" width="${f1(ac*S*.25)}" height="20" style="fill:none;stroke:var(--good);stroke-width:2"/>`;
    g+=txt(bx+ac*S*.75,by+42,'75 to 100% band','t-xs',B);
    g+=txt(bx,by+70,`${xl?'extra-large adult cuff':'adult cuff'}: bladder ${bl} cm`,'t-sm',B);
    g+=`<rect x="${bx}" y="${by+80}" width="${f1(bl*S)}" height="16" rx="4" style="fill:${r<.75?'var(--risk)':'var(--device)'}"/>`;
    const ok=r>=.75&&r<=1;
    g+=`<rect x="${bx}" y="${by+112}" width="${bw}" height="${N?56:62}" rx="10" style="fill:${ok?'var(--good-soft)':'var(--bad-soft)'}"/>`;
    g+=txt(bx+12,by+134,`bladder = ${Math.round(r*100)}% of the arm`,'t-sm',`fill:${ok?'var(--good)':'var(--bad)'};font-weight:700`);
    g+=txt(bx+12,by+152,ok?'fits the AHA range':'too small: the reading will be falsely high','t-xs',B);
    return g}
  /* 3 skin: J-shaped odds ratios */
  function vSkin(u,N,ox,oy,W){let g='';const D=[['underweight',1.7],['normal',1],['obesity',1.12],['“morbid obesity”',1.7]];
    const x0=ox+(N?30:60),w=N?320:420,y0=oy+(N?40:40),h=N?190:220,Y=v=>y0+h-h*v/2,bw=w/4*.56;
    g+=txt(x0,y0-14,'pressure injury, odds ratio vs normal weight','t-xs',B);
    g+=`<line x1="${x0}" x2="${x0+w}" y1="${f1(Y(1))}" y2="${f1(Y(1))}" style="stroke:var(--ink);stroke-width:1;stroke-dasharray:4 3"/>`+txt(x0-4,Y(1)+4,'1','t-xs t-end');
    const pts=[];D.forEach(([n,v],i)=>{const g2=ramp(u,.05+i*.12,.3+i*.12),x=x0+w/4*(i+.5),vv=lerp(0,v,ease(g2));pts.push([x,Y(v)]);
      g+=`<rect x="${f1(x-bw/2)}" y="${f1(Y(vv))}" width="${f1(bw)}" height="${f1(Y(0)-Y(vv))}" rx="4" style="fill:var(--hl);opacity:.75"/>`;
      g+=txt(x,Y(0)+14,n,'t-xs t-mid',B)+(g2>.98?txt(x,Y(v)-6,v.toFixed(2),'t-xs t-mid',B):'')});
    if(u>.65)g+=`<path d="${smoothPath(pts,false)}" style="fill:none;stroke:var(--ink);stroke-width:2;opacity:${f1(ramp(u,.65,.8))}"/>`+kitLabel(pts[3][0]-20,pts[3][1]-22,'J-shaped',{a:'e'});
    if(!N){const sx=ox+520;g+=txt(sx,oy+40,'skin folds','t-xs',B);
      g+=`<path d="M${sx} ${oy+80}q60 -30 120 0q-60 40 -120 0z" style="fill:var(--fat);opacity:.6;stroke:var(--fat-line)"/><path d="M${sx} ${oy+100}q60 40 120 0" style="fill:none;stroke:var(--fat-line);stroke-width:1.4"/>`;
      const glow=bump(u,.3,1);g+=`<ellipse cx="${sx+60}" cy="${oy+92}" rx="50" ry="6" style="fill:var(--risk);opacity:${f1(.15+.3*glow)}"/>`;
      g+=txt(sx,oy+140,'intertrigo: no evidence on','t-xs')+txt(sx,oy+154,'prevention, none firm on','t-xs')+txt(sx,oy+168,'treatment (review of 68 studies)','t-xs')}
    return g}
  /* 4 airway: torso pivots at the hip until the ear is level with the sternum, then 45 degrees after surgery */
  function vAirway(u,N,ox,oy,W){let g='';const th=(u<.55?lerp(0,23.7,ease(ramp(u,.08,.5))):lerp(23.7,45,ease(ramp(u,.66,.95))))*Math.PI/180;
    const hx=ox+(N?290:330),hy=oy+(N?210:230),c=Math.cos(th),s=Math.sin(th);
    /* a point d along the torso from the hip, p in front of it */
    const at=(d,p)=>[hx-d*c+p*s, hy-d*s-p*c];
    g+=`<rect x="${hx-220}" y="${hy+18}" width="${N?320:420}" height="12" rx="4" style="fill:var(--device);opacity:.6"/>`;
    /* wedge / bed back */
    const k1=at(190,-18);g+=`<path d="M${hx} ${hy+18}L${f1(k1[0])} ${f1(k1[1]+18*c)}L${f1(k1[0])} ${hy+18}Z" style="fill:var(--panel-2);stroke:var(--line)"/>`;
    /* legs */
    g+=`<path d="M${hx} ${hy}L${hx+(N?70:150)} ${hy+4}" style="stroke:var(--figure);stroke-width:34;stroke-linecap:round"/>`;
    /* torso */
    const sh=at(140,0);g+=`<path d="M${hx} ${hy}L${f1(sh[0])} ${f1(sh[1])}" style="stroke:var(--figure);stroke-width:62;stroke-linecap:round"/>`;
    const head=at(186,4);g+=`<circle cx="${f1(head[0])}" cy="${f1(head[1])}" r="22" style="fill:var(--figure);stroke:var(--figure-line)"/>`;
    const ear=at(180,8),st=at(130,30);
    const lvl=Math.abs(ear[1]-st[1])<2.5;
    g+=`<circle cx="${f1(ear[0])}" cy="${f1(ear[1])}" r="4" style="fill:var(--ink)"/><circle cx="${f1(st[0])}" cy="${f1(st[1])}" r="4" style="fill:var(--ink)"/>`;
    g+=`<line x1="${f1(ear[0]-20)}" x2="${f1(st[0]+40)}" y1="${f1(ear[1])}" y2="${f1(ear[1])}" style="stroke:${lvl?'var(--good)':'var(--muted)'};stroke-width:1.6;stroke-dasharray:5 3"/>`;
    g+=kitLabel(ear[0]-10,ear[1]-12,'tragus',{a:'e'})+kitLabel(st[0]+8,st[1]+16,'sternum');
    const deg=Math.round(th*180/Math.PI);
    g+=txt(ox+(N?20:30),oy+30,u<.6?(lvl?'ramped: ear level with sternum':'raising the head and shoulders'):(deg>=44?'after surgery: 45° head-up':'tilting towards 45°'),'t-sm',B)+txt(ox+(N?20:30),oy+48,`back angle about ${deg}° (schematic)`);
    const bx=ox+(N?20:500),by=oy+(N?290:80);
    g+=txt(bx,by,'difficult intubation','t-xs',B);
    [['lean',2.2],['BMI ≥35',15.5]].forEach(([n,v],i)=>{const y=by+12+i*30;g+=`<rect x="${bx}" y="${y}" width="${f1(v*6*ramp(u,.1,.4))}" height="16" rx="4" style="fill:var(--hl)"/>`+txt(bx+v*6+6,y+12,`${n}: ${v}%`,'t-xs',B)});
    return g}
  /* 5 injections: needles of 16, 25 and 38 mm through a growing fat layer */
  function vNeedle(u,N,ox,oy,W){let g='';const fat=lerp(8,30,ease(ramp(u,.1,.75))),k=N?3.6:4.2,x0=ox+(N?20:40),w=N?340:400,y0=oy+64;
    g+=txt(x0,y0-38,`subcutaneous fat over the muscle: ${fat.toFixed(0)} mm (schematic)`,'t-xs',B);
    g+=`<rect x="${x0}" y="${y0}" width="${w}" height="6" style="fill:var(--cyto);stroke:var(--fat-line)"/><rect x="${x0}" y="${y0+6}" width="${w}" height="${f1(fat*k)}" style="fill:var(--fat);opacity:.75"/><rect x="${x0}" y="${f1(y0+6+fat*k)}" width="${w}" height="${f1(Math.max(30,(46-fat)*k))}" style="fill:var(--lean);opacity:.8"/>`;
    g+=kitLabel(x0+w-6,y0+20,'fat',{a:'e'})+kitLabel(x0+w-6,y0+6+fat*k+18,'muscle',{a:'e'});
    [16,25,38].forEach((L,i)=>{const x=x0+w*(i+1)/4.4,tip=y0+L*k,reach=L>=fat+5;
      g+=`<rect x="${f1(x-5)}" y="${y0-26}" width="10" height="20" rx="2" style="fill:var(--pen-dark)"/><line x1="${f1(x)}" x2="${f1(x)}" y1="${y0-6}" y2="${f1(tip)}" style="stroke:var(--device);stroke-width:2"/>`;
      g+=`<circle cx="${f1(x)}" cy="${f1(tip)}" r="5" style="fill:${reach?'var(--good)':'var(--risk)'};stroke:var(--panel);stroke-width:1.5"/>`;
      g+=kitLabel(x+8,y0-12,L+' mm')+kitLabel(x+8,tip+4,reach?'in muscle':'in fat')});
    if(!N){const sx=ox+500;g+=txt(sx,oy+60,'deltoid fat pad, mean','t-xs',B)+txt(sx,oy+76,'women 11.7 mm · men 8.3 mm','t-xs');
      g+=txt(sx,oy+110,'16 mm needle short of','t-xs',B)+txt(sx,oy+126,'5 mm into muscle:','t-xs',B)+txt(sx,oy+142,'48.4% of women, 17% of men','t-xs');
      g+=txt(sx,oy+180,'enoxaparin label, BMI >30:','t-xs',B)+txt(sx,oy+196,'“no consensus for dose','t-xs')+txt(sx,oy+212,'adjustment”','t-xs')}
    return g}
  /* 6 after surgery: a simulated heart rate climbing past 120 */
  function vObs(u,N,ox,oy,W){let g='';const hr=lerp(84,132,ease(ramp(u,.08,.75))),rr=Math.round(lerp(16,28,ease(ramp(u,.2,.8))));
    const mx=ox+(N?10:30),mw=N?360:420,my=oy+20,mh=N?170:200;
    g+=`<rect x="${mx}" y="${my}" width="${mw}" height="${mh}" rx="12" style="fill:var(--ink);opacity:.92"/>`;
    const tY=v=>my+mh-14-(mh-78)*(v-60)/(140-60);
    g+=`<line x1="${mx+10}" x2="${mx+mw-10}" y1="${f1(tY(120))}" y2="${f1(tY(120))}" style="stroke:var(--bad);stroke-width:1.4;stroke-dasharray:6 4"/>`;
    g+=`<text x="${mx+mw-14}" y="${f1(tY(120)-5)}" class="t-xs t-end" style="fill:var(--bad-soft)">120 /min</text>`;
    let d='';const n=70;for(let i=0;i<=n;i++){const q=i/n,uu=Math.max(0,u-(1-q)*.35),h=lerp(84,132,ease(ramp(uu,.08,.75)))+Math.sin(i*1.7)*2;d+=(i?'L':'M')+f1(mx+12+(mw-24)*q)+' '+f1(tY(h))}
    g+=`<path d="${d}" style="fill:none;stroke:var(--good-soft);stroke-width:2.2"/>`;
    g+=`<text x="${mx+18}" y="${my+34}" class="t-big" style="fill:${hr>120?'var(--bad-soft)':'var(--good-soft)'};font-size:28px">HR ${Math.round(hr)}</text><text x="${mx+18}" y="${my+52}" class="t-xs" style="fill:var(--bg)">breaths ${rr}/min · simulated patient</text>`;
    const al=hr>120,ay=my+mh+14;
    g+=`<rect x="${mx}" y="${ay}" width="${mw}" height="${N?62:52}" rx="10" style="fill:${al?'var(--bad-soft)':'var(--panel-2)'};stroke:${al?'var(--bad)':'var(--line)'}"/>`;
    g+=txt(mx+12,ay+20,al?'heart rate above 120: a leak warning sign':'observations within the usual range','t-sm',`fill:${al?'var(--bad)':'var(--ink)'};font-weight:700`)+txt(mx+12,ay+38,al?(N?'tell the surgical team now':'tell the surgical team now (contrast swallow found 2 of 9 leaks)'):'keep watching pulse, breathing and pain');
    if(!N){const sx=ox+480;g+=txt(sx,oy+40,'leak warning features','t-xs',B);
      ['sustained fast pulse','breathing changes','fever','belly or shoulder pain'].forEach((e,i)=>{const on=u>.3+i*.12;g+=`<circle cx="${sx+6}" cy="${oy+64+i*26}" r="5" style="fill:${on?'var(--risk)':'var(--panel)'};stroke:var(--risk)"/>`+txt(sx+18,oy+68+i*26,e,'t-sm',on?B:'')})}
    return g}
  const NU_V=[vAdmit,vCuff,vSkin,vAirway,vNeedle,vObs];
  function draw(t){
    const N=vb(svg,'720 400','400 530');
    const i=Math.min(5,Math.floor(t*6)),u=ramp(t,i/6,(i+1)/6);
    let g='';const rx0=N?30:50,rx1=N?370:670,ry=26,RX=k=>lerp(rx0,rx1,k/5);
    g+=`<line x1="${rx0}" x2="${rx1}" y1="${ry}" y2="${ry}" style="stroke:var(--line);stroke-width:4;stroke-linecap:round"/><line x1="${rx0}" x2="${f1(lerp(rx0,rx1,clamp(t*6/5)))}" y1="${ry}" y2="${ry}" style="stroke:var(--life);stroke-width:4;stroke-linecap:round"/>`;
    NU_ST.forEach((s,k)=>{const on=k<=i;g+=`<circle cx="${f1(RX(k))}" cy="${ry}" r="${k===i?9:6}" style="fill:${on?'var(--life)':'var(--panel)'};stroke:var(--life);stroke-width:2"/>`;
      if(!N||k===i)g+=`<text x="${f1(RX(k))}" y="${ry+24}" class="t-xs ${N&&k===5?'t-end':N&&k===0?'':'t-mid'}" style="fill:var(--ink);font-weight:${k===i?700:500}">${N?s:s}</text>`});
    const fade=Math.min(ramp(u,0,.08),1);
    g+=`<g style="opacity:${f1(.25+.75*fade)}">`+NU_V[i](u,N,N?10:10,N?62:66,N?380:700)+'</g>';
    svg.innerHTML=g;
    const p=phaseOf(NU_STEPS,t);note.innerHTML=noteHTML(NU_STEPS[p]);setA&&setA(p);
  }
  const stop=playWire(rg,$('#nuPlay'),draw,24000,'Replay','nursing');
  setA=stepWire($('#nuSteps'),NU_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- body-weight descriptors (teaching only; no dosing output) ---------- */
  const sx=$('#nuSex'),ht=$('#nuHt'),wt=$('#nuWt'),bsv=$('#nuBw'),out=$('#nuBwOut');
  function calc(){
    const male=sx.value==='m',h=clamp(+ht.value||0,120,220),w=clamp(+wt.value||0,30,350);
    const ibw=h-(male?100:105),abw=ibw+.4*(w-ibw),cap=male?100:70;
    const N=vb(bsv,'720 220','400 270');
    const L=N?{lx:20,bx:20,bw:300,y0:24,rh:66}:{lx:20,bx:250,bw:400,y0:40,rh:52};
    const mx=Math.max(w,ibw,abw,cap)*1.08,X=v=>L.bx+L.bw*v/mx;
    const rows=[['Total body weight (TBW)',w,'var(--figure-line)','the weight on the scale'],['Ideal body weight (IBW)',ibw,'var(--tx)',`height ${h} − ${male?100:105}`],['Adjusted body weight (ABW)',abw,'var(--life)','IBW + 0.4 × (TBW − IBW)']];
    let g='';
    rows.forEach(([n,v,col,f],i)=>{const y=L.y0+i*L.rh,by=N?y+8:y;
      g+=`<text x="${L.lx}" y="${N?y:by+13}" class="t-sm" style="fill:var(--ink);font-weight:700">${n}</text>`;
      if(!N)g+=`<text x="${L.lx}" y="${by+28}" class="t-xs">${f}</text>`;
      g+=`<rect x="${L.bx}" y="${by}" width="${f1(Math.max(2,X(Math.max(0,v))-L.bx))}" height="18" rx="4" style="fill:${col};opacity:.85"/><text x="${f1(X(Math.max(0,v))+6)}" y="${by+13}" class="t-xs" style="fill:var(--ink);font-weight:700">${v.toFixed(1)} kg</text>`;
      if(i===2&&w>ibw){const a=X(ibw),b=X(w),c=X(abw);g+=`<path d="M${f1(a)} ${by+24}v6H${f1(b)}v-6" style="fill:none;stroke:var(--muted);stroke-width:1.2"/>`+kitLabel(c,by+44,'40% of the excess',{a:'m'})}});
    const cy=L.y0+3*L.rh+(N?6:0);
    g+=`<line x1="${f1(X(cap))}" x2="${f1(X(cap))}" y1="${L.y0-14}" y2="${cy}" style="stroke:var(--hl);stroke-width:1.4;stroke-dasharray:5 3"/>`+(N?kitLabel(20,cy+20,`dashed line: lean body weight rarely above ${cap} kg (${male?'men':'women'})`):kitLabel(X(cap)+4,L.y0-16,`lean body weight rarely above ${cap} kg (${male?'men':'women'})`));
    bsv.innerHTML=g;
    out.innerHTML=`<b>${w.toFixed(0)} kg</b> total · <b>${ibw.toFixed(1)} kg</b> ideal · <b>${abw.toFixed(1)} kg</b> adjusted`+(w<ibw?' · total is below ideal here, so adjusted falls between them':'');
  }
  [sx,ht,wt].forEach(el=>{el.addEventListener('input',calc);el.addEventListener('change',calc)});
  calc();

  /* ---------- pen teaching ---------- */
  const psv=$('#nuPen'),pb=$('#nuPenBtns'),pl=$('#nuPenList');let pi=0;
  pb.innerHTML=NU_PENS.map((p,i)=>`<button class="btn" data-pen="${i}" aria-pressed="${i===0}">${p.b}</button>`).join('');
  function drawPen(){
    const N=vb(psv,'720 300','400 300'),P=NU_PENS[pi];
    const px=N?120:200,py=20,ps=260,pr=person(px,py,ps,{size:.5});
    let g=pr.svg;const k=ps/100;
    const S={abdomen:[[px-18*k/2.6,py+48*k],[px+18*k/2.6,py+48*k]],thigh:[[px-7*k,py+70*k],[px+7*k,py+70*k]],arm:[[px-17*k,py+34*k],[px+17*k,py+34*k]],backarm:[[px-17*k,py+34*k],[px+17*k,py+34*k]]};
    const NM={abdomen:'abdomen',thigh:'thigh',arm:'upper arm',backarm:'back of upper arm (by another person)'};
    P.sites.forEach((s,j)=>{S[s].forEach(q=>{g+=`<circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="9" style="fill:var(--rx-drug);opacity:.25"/><circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="4.5" style="fill:var(--rx-drug)"/>`});
      const q=S[s][1],lx=N?px+90:px+120,ly=q[1]+(s==='abdomen'?6:0);g+=`<line x1="${f1(q[0]+6)}" y1="${f1(q[1])}" x2="${lx-4}" y2="${ly}" style="stroke:var(--muted);stroke-width:1"/>`+kitLabel(lx,ly+3,NM[s])});
    if(!N)g+=pen(560,150,1.4,{ang:-30,needle:0,cap:true}).svg+`<text x="560" y="250" class="t-xs t-mid">prefilled pen (no dose shown)</text>`;
    psv.innerHTML=g;
    pl.innerHTML=P.items.map((it,j)=>`<li><label><input type="checkbox"> <span>${it}</span></label></li>`).join('');
  }
  pb.addEventListener('click',e=>{const b=e.target.closest('[data-pen]');if(!b)return;pi=+b.dataset.pen;$$('[data-pen]',pb).forEach(x=>x.setAttribute('aria-pressed',x===b));drawPen()});
  drawPen();
  const prevR=redraws.nursing;redraws.nursing=()=>{prevR&&prevR();calc();drawPen()};
};
/* =============== 4.5 Research frontier =============== */
